// Corporate actions -- real Alpaca trading-API endpoint (paper-api host;
// this account's keys are data-only on the live api.alpaca.markets host,
// confirmed in CLAUDE.md's own credentials table). ca_types is a
// required param; max 90-day since/until window (both confirmed live,
// 2026-08-06). "Unresolved" is read as "any split/spinoff announcement
// with an ex_date on or after `since`" -- i.e. still within its own
// effective window, not yet fully in the past.
async function v3CheckRecentCorporateAction(symbol, lookbackDays) {
  try {
    const fetch = (await import("node-fetch")).default;
    const until = new Date().toISOString().split("T")[0];
    const since = new Date(Date.now() - Math.min(lookbackDays, 90) * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
    const r = await fetch(`https://paper-api.alpaca.markets/v2/corporate_actions/announcements?since=${since}&until=${until}&symbol=${encodeURIComponent(symbol)}&ca_types=split,spinoff`, {
      headers: { "APCA-API-KEY-ID": ALPACA_KEY_ID, "APCA-API-SECRET-KEY": ALPACA_SECRET },
    });
    if (!r.ok) return { ok: false, hasUnresolvedAction: false, error: `HTTP ${r.status}` };
    const announcements = await r.json();
    return { ok: true, hasUnresolvedAction: Array.isArray(announcements) && announcements.length > 0, announcements };
  } catch (e) {
    return { ok: false, hasUnresolvedAction: false, error: e.message };
  }
}

// REAL BUG FOUND AND FIXED (2026-08-06, during the v3 foundation review):
// the old v3HasListedOptions called /v2/options/contracts with NO
// expiration_date filter at all. Confirmed live that Alpaca's documented
// default behavior for that endpoint returns only contracts expiring
// before the upcoming weekend when no expiration filter is given -- for
// any symbol whose nearest listed expiration falls outside that narrow
// window (common for lower-volume monthly-only names), the unfiltered
// call returned an EMPTY list even though the symbol has real, active
// listed options. Verified directly against all 10 symbols the prior
// build had excluded as "no_listed_options" (CDW, BAH, TFC, MET, TRV,
// DUK, AEP, D, GIS, ELV): every single one returned 0 contracts with no
// filter, but >=1 real active contract the instant
// expiration_date_gte=<today> was added -- never a genuine Alpaca
// options-coverage gap, just a mis-querying bug.
//
// FIX 2 (2026-08-06) — the two separate helper functions this replaced
// (v3HasListedOptions/v3HasLongDatedOptions) each independently called
// the endpoint with a single expiration_date_gte cutoff and treated any
// non-empty result as proof of "options exist at/beyond that date." Real
// gap: none of them recorded WHAT was actually returned (nearest real
// expiration, furthest real expiration actually observed), just a
// collapsed boolean -- not enough to audit later whether "6-month"/
// "9-month" claims were genuinely verified against real contract dates
// or just inferred from a non-empty array. This single function now
// runs the three explicit queries per the instruction and records the
// exact dates used and returned.
async function v3VerifyOptionsEligibility(symbol) {
  const fetch = (await import("node-fetch")).default;
  const todayET = new Date().toLocaleDateString("en-CA", { timeZone: "America/New_York" });
  const sixMonthsOut = new Date(Date.now() + 6 * 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
  const nineMonthsOut = new Date(Date.now() + 9 * 30 * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
  const checkedAt = new Date().toISOString();

  async function queryContracts(expirationDateGte, limit) {
    try {
      const r = await fetch(`https://paper-api.alpaca.markets/v2/options/contracts?underlying_symbols=${encodeURIComponent(symbol)}&expiration_date_gte=${expirationDateGte}&limit=${limit}`, {
        headers: { "APCA-API-KEY-ID": ALPACA_KEY_ID, "APCA-API-SECRET-KEY": ALPACA_SECRET },
      });
      if (!r.ok) return { ok: false, contracts: [] };
      const d = await r.json();
      return { ok: true, contracts: Array.isArray(d?.option_contracts) ? d.option_contracts : [] };
    } catch {
      return { ok: false, contracts: [] };
    }
  }

  // Query 1 — hasListedOptions. limit=5 (not 1) so nearestExpiration is
  // computed from a real small sample rather than an arbitrary single row.
  const q1 = await queryContracts(todayET, 5);
  const hasListedOptions = q1.ok && q1.contracts.length > 0;
  const nearestExpiration = hasListedOptions ? q1.contracts.map((c) => c.expiration_date).sort()[0] : null;

  // Query 2 — longDatedOptionsAvailable (6+ months).
  const q2 = await queryContracts(sixMonthsOut, 1);
  const longDatedOptionsAvailable = q2.ok && q2.contracts.length > 0;

  // Query 3 — leapsEligible (9+ months, OCC LEAPS definition). limit=10
  // so furthestVerifiedExpiration reflects a real observed date, not a
  // guess -- this is explicitly "furthest VERIFIED," i.e. bounded by
  // what this one query's limit actually returned, not a claim about the
  // symbol's true furthest-ever listed contract.
  const q3 = await queryContracts(nineMonthsOut, 10);
  const leapsEligible = q3.ok && q3.contracts.length > 0;
  const furthestVerifiedExpiration = leapsEligible ? q3.contracts.map((c) => c.expiration_date).sort().slice(-1)[0] : null;

  return {
    hasListedOptions,
    longDatedOptionsAvailable,
    leapsEligible,
    nearestExpiration,
    furthestVerifiedExpiration,
    checkedAt,
    queryParameters: {
      query1: { expiration_date_gte: todayET, purpose: "hasListedOptions" },
      query2: { expiration_date_gte: sixMonthsOut, purpose: "longDatedOptionsAvailable" },
      query3: { expiration_date_gte: nineMonthsOut, purpose: "leapsEligible" },
    },
    // Alpaca's options data on this account's Basic plan is the
    // "indicative" feed, not OPRA (confirmed via Alpaca's own docs during
    // the prior review) -- labeled explicitly so any future consumer of
    // this record knows the provenance without re-deriving it.
    provider: "alpaca_indicative",
  };
}

// candidateSymbolsOverride: optional, real testability hook (same
// pattern as flexai-saas's own trend-regime route's ?symbol= single-
// symbol test mode) -- when omitted, evaluates the full curated list
// above. Manually triggered, then refreshed monthly, per explicit
// instruction -- a long runtime (one real network round trip per
// candidate: SIP bars, corporate actions, options check) is accepted
// for an infrequent batch job, not optimized against here.
async function v3BuildUniverse(candidateSymbolsOverride) {
  const candidateSymbols = candidateSymbolsOverride ?? V3_CURATED_SWING_CANDIDATES;

  const swingSymbols = [];
  const leapsSymbols = [];
  const optionsMeta = [];
  const exclusions = [];

  for (const symbol of candidateSymbols) {
    const corpAction = await v3CheckRecentCorporateAction(symbol, 30);
    if (!corpAction.ok) {
      exclusions.push({ symbol, reason: `corporate_action_check_failed: ${corpAction.error}` });
      continue;
    }
    if (corpAction.hasUnresolvedAction) {
      exclusions.push({ symbol, reason: "unresolved_corporate_action_last_30d" });
      continue;
    }

    let sipResult;
    try {
      const r = await v3GetCompletedDailySipBars([symbol], 320);
      sipResult = r[symbol];
    } catch (e) {
      exclusions.push({ symbol, reason: `sip_fetch_threw: ${e.message}` });
      continue;
    }
    if (!sipResult.ok) {
      exclusions.push({ symbol, reason: `sip_error: ${sipResult.error}` });
      continue;
    }
    if (sipResult.barCount < 300) {
      exclusions.push({ symbol, reason: `insufficient_bars (${sipResult.barCount}/300)` });
      continue;
    }
    if (sipResult.dataIntegrityFailure) {
      exclusions.push({ symbol, reason: "sip_yahoo_data_integrity_failure" });
      continue;
    }

    const bars = sipResult.bars;
    const lastBar = bars[bars.length - 1];
    if (lastBar.c < 10) {
      exclusions.push({ symbol, reason: `price_below_10 ($${lastBar.c})` });
      continue;
    }

    const last20 = bars.slice(-20);
    const dollarVolumes = last20.map((b) => b.c * b.v).sort((a, b) => a - b);
    const mid = Math.floor(dollarVolumes.length / 2);
    const medianDollarVolume = dollarVolumes.length === 0 ? 0 : dollarVolumes.length % 2 === 0 ? (dollarVolumes[mid - 1] + dollarVolumes[mid]) / 2 : dollarVolumes[mid];
    if (medianDollarVolume < 50_000_000) {
      exclusions.push({ symbol, reason: `median_dollar_volume_below_50M ($${(medianDollarVolume / 1e6).toFixed(1)}M)` });
      continue;
    }

    // FIX 2 (2026-08-06) — single call, three explicit real queries
    // inside (today/6mo/9mo), full provenance recorded (exact query
    // dates, real nearest/furthest-verified expirations actually
    // returned, checkedAt, provider). longDatedOptionsAvailable (6+
    // months) and leapsEligible (9+ months, the OCC's own LEAPS
    // definition) stay two separate, independently-checked fields, never
    // conflated -- both are pure contract-existence checks, no OPRA quote
    // data (strike, premium, bid/ask, spread) is fetched or available on
    // this account tier, so neither field nor anything derived from it
    // may ever be presented as a specific contract recommendation.
    const optionsCheck = await v3VerifyOptionsEligibility(symbol);
    if (!optionsCheck.hasListedOptions) {
      exclusions.push({ symbol, reason: "no_listed_options" });
      continue;
    }

    swingSymbols.push(symbol);
    optionsMeta.push({ symbol, ...optionsCheck });
    if (optionsCheck.leapsEligible) leapsSymbols.push(symbol);

    await new Promise((r) => setTimeout(r, 100));
  }

  const createdAt = new Date().toISOString();
  const version = "v1";

  await kvSet("v3:universe:swing:v1", {
    symbols: swingSymbols,
    version,
    createdAt,
    symbolCount: swingSymbols.length,
    criteria: "explicitly curated liquid US common stocks",
  });
  await kvSet("v3:universe:leaps:v1", {
    symbols: leapsSymbols,
    version,
    createdAt,
    symbolCount: leapsSymbols.length,
    criteria: "subset of v3:universe:swing:v1 with leapsEligible=true (9+ months to expiration, OCC LEAPS definition -- never the 6-month longDatedOptionsAvailable figure)",
  });
  await kvSet("v3:universe:etf:v1", { symbols: ["SPY", "QQQ", "IWM", "XLK", "XLF", "XLE", "XLV"], version, createdAt });
  // Disclosed addition beyond the three lists explicitly named in the
  // instruction: per-symbol longDatedOptionsAvailable/leapsEligible
  // detail, so the two fields stay inspectable/verifiable independently
  // rather than only existing as an already-collapsed leapsSymbols list.
  await kvSet("v3:universe:optionsMeta:v1", { records: optionsMeta, version, createdAt });

  return { swingSymbols, leapsSymbols, optionsMeta, exclusions, candidatesChecked: candidateSymbols.length };
}

// ---- v3BuildUniverseV2 (2026-08-12) -- top-100-by-liquidity trim of
// v3:universe:swing:v1, built ALONGSIDE v1 per explicit instruction --
// v1 is only ever READ here (its symbol list), never modified, and
// nothing in the live scanners (Channel Scanner / Master Swing Agent /
// Data Agent) has been changed to read v2 instead -- v1 stays the live
// universe those three functions use. Manually triggered, refreshed
// monthly per explicit instruction -- same "manual, infrequent batch
// job" precedent v3BuildUniverse itself already uses (also never
// auto-scheduled in tick()). Reuses the EXACT median-dollar-volume
// formula v3BuildUniverse already computes for its own >=$50M/20-day
// filter (line ~11690 above) -- same real, proven math, just used here
// to RANK instead of filter.
//
// The instruction's own literal v3:universe:swing:v2 example shape
// lists only summary/metadata fields (activeCount, reserveCount,
// rankingMethod, etc) with no symbols array at all -- as written, no
// scanner could ever determine WHICH 100 symbols are active from that
// record alone. Disclosed addition beyond the literal example: this
// also stores `symbols` (plain ticker array, same shape v1 already
// uses) and `activeSymbols` (the full per-symbol rank/volume/status
// records) on the v2 record itself, so it's actually self-contained --
// flagging this as my own judgment call, not something independently
// specified.
async function v3BuildUniverseV2(dateET = v3TradingDateET()) {
  const v1Result = await kvGet("v3:universe:swing:v1");
  const v1 = v1Result.ok ? v1Result.value : null;
  if (!v1 || !Array.isArray(v1.symbols) || v1.symbols.length === 0) {
    return { ok: false, error: "v3:universe:swing:v1 missing or empty -- run v3BuildUniverse first" };
  }

  const ranked = [];
  const failures = [];
  for (const symbol of v1.symbols) {
    try {
      const sipResult = (await v3GetCompletedDailySipBars([symbol], 40))[symbol];
      if (!sipResult.ok) { failures.push({ symbol, reason: `sip_error: ${sipResult.error}` }); continue; }
      if (sipResult.dataIntegrityFailure) { failures.push({ symbol, reason: "sip_yahoo_data_integrity_failure" }); continue; }
      if (sipResult.barCount < 20) { failures.push({ symbol, reason: `insufficient_bars (${sipResult.barCount}/20)` }); continue; }

      const last20 = sipResult.bars.slice(-20);
      const dollarVolumes = last20.map((b) => b.c * b.v).sort((a, b) => a - b);
      const mid = Math.floor(dollarVolumes.length / 2);
      const medianDailyDollarVolume = dollarVolumes.length % 2 === 0
        ? (dollarVolumes[mid - 1] + dollarVolumes[mid]) / 2
        : dollarVolumes[mid];
      ranked.push({ symbol, medianDailyDollarVolume });
      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      failures.push({ symbol, reason: `threw: ${e.message}` });
    }
  }

  ranked.sort((a, b) => b.medianDailyDollarVolume - a.medianDailyDollarVolume);
  ranked.forEach((r, i) => {
    r.rank = i + 1;
    r.calculationDate = dateET;
    r.sourceVersion = "v1";
    r.status = i < 100 ? "active" : "reserve";
  });

  const active = ranked.slice(0, 100);
  const reserve = ranked.slice(100);
  const createdAt = new Date().toISOString();

  await kvSet("v3:universe:swing:v2", {
    version: "v2",
    createdAt,
    calculationDate: dateET,
    activeCount: active.length,
    reserveCount: reserve.length,
    rankingMethod: "20_session_median_daily_dollar_volume",
    refreshPolicy: "monthly_after_last_trading_session",
    note: "SPY/QQQ/ETFs are separate context universe (v3:universe:etf:v1) -- not included here",
    symbols: active.map((r) => r.symbol),
    activeSymbols: active,
    failures, // v1 symbols that couldn't be ranked this run (real data gap, not silently dropped)
  });
  await kvSet("v3:universe:swing:v2:reserve", {
    symbols: reserve,
    note: "Reserve — outside active universe. Monitor for major movers.",
    calculationDate: dateET,
    createdAt,
  });

  return { ok: true, active, reserve, failures, totalRanked: ranked.length, totalFromV1: v1.symbols.length };
}

// ============================================================
// CHANNEL BOUNCE V3 — SHADOW SCANNER (2026-08-06)
//
// A completely new, v3-namespaced port of the same proven channel/pivot/
// ATR math the legacy runChannelBounceV2 already uses (v2FindPivotsInWindow/
// v2LinearRegression/v2BuildChannel/v2ATRSeries, all still intact,
// unmodified, just frozen at the tick() call site per the earlier v3
// freeze work) -- reusing well-tested formulas is not the same as
// depending on v2 state, no v2 function/KV key is called or read here.
// Two deliberate, DISCLOSED differences from v2's implementation, per
// this build's own literal instruction rather than v2's precedent:
//   - parallelism tolerance is 20% here (v2 uses 15%) -- looser, exactly
//     as specified.
//   - v2's additional "no prior close materially outside the channel"
//     invalidation check is NOT ported here -- it isn't part of this
//     build's literal channel-validity spec, so it's omitted rather than
//     silently carried over.
// SHADOW MODE: writes KV only, per explicit instruction -- no
// sendTelegram/sendTelegramWithId/gatewaySendTelegram/v3SendTelegram call
// exists anywhere in this section.
// ============================================================

function v3ATRSeries(bars, period = 14) {
  if (bars.length < period + 1) return [];
  const trueRanges = [];
  for (let i = 1; i < bars.length; i++) {
    trueRanges.push(Math.max(bars[i].h - bars[i].l, Math.abs(bars[i].h - bars[i - 1].c), Math.abs(bars[i].l - bars[i - 1].c)));
  }
  const series = [];
  let atr = trueRanges.slice(0, period).reduce((a, b) => a + b, 0) / period;
  series[period] = atr;
  for (let i = period; i < trueRanges.length; i++) {
    atr = (atr * (period - 1) + trueRanges[i]) / period;
    series[i + 1] = atr;
  }
  return series;
}

// Pivot definition per explicit instruction: high/low greater/less than
// 3 bars each side -- barsEachSide defaults to 3 (not v2's 2, used
// elsewhere for a deliberately looser double-top/bottom pivot); every
// call site below passes 3 explicitly anyway.
function v3FindPivotsInWindow(bars, side, barsEachSide = 3) {
  const pivots = [];
  for (let i = barsEachSide; i < bars.length - barsEachSide; i++) {
    const b = bars[i];
    let isPivot = true;
    for (let k = 1; k <= barsEachSide && isPivot; k++) {
      isPivot = side === "high"
        ? b.h > bars[i - k].h && b.h > bars[i + k].h
        : b.l < bars[i - k].l && b.l < bars[i + k].l;
    }
    if (isPivot) pivots.push({ localIndex: i, bar: b, high: b.h, low: b.l, date: v3BarDateStr(b) });
  }
  return pivots;
}

function v3BarDateStr(bar) {
  return new Date(bar.t).toLocaleDateString("en-CA", { timeZone: "America/New_York" });
}

function v3LinearRegression(points) {
  const n = points.length;
  const sumT = points.reduce((s, p) => s + p.t, 0);
  const sumP = points.reduce((s, p) => s + p.price, 0);
  const sumTP = points.reduce((s, p) => s + p.t * p.price, 0);
  const sumTT = points.reduce((s, p) => s + p.t * p.t, 0);
  const denom = n * sumTT - sumT * sumT;
  if (denom === 0) return { slope: 0, intercept: sumP / n };
  const slope = (n * sumTP - sumT * sumP) / denom;
  const intercept = (sumP - slope * sumT) / n;
  return { slope, intercept };
}

// windowLen: 40-120 completed daily SIP bars, per explicit instruction.
// Returns { channel: null, rejectionReason } if no valid parallel
// ascending/descending channel exists in this exact window length --
// v3FindBestChannel below tries multiple window lengths. Codex review
// FIX 2 (2026-08-07) — this used to return a bare `null` on every
// failure path, collapsing genuinely different reasons (too few pivots,
// mixed slope, degenerate lines, failed parallelism, failed residuals,
// too few touches) into one undifferentiated "no channel" outcome. The
// Swing Lab daily report needs a real parallelism_failed count
// specifically, and "never discard a rejected pattern -- it is learning
// data" applies just as much to "why didn't a channel even form" as it
// does to "a channel formed but failed an eligibility gate."
function v3BuildChannel(allBars, windowLen, currentAtr) {
  if (allBars.length < windowLen) return { channel: null, rejectionReason: "insufficient_bars_for_window" };
  const window = allBars.slice(-windowLen);

  const pivotHighs = v3FindPivotsInWindow(window, "high", 3);
  const pivotLows = v3FindPivotsInWindow(window, "low", 3);
  // Minimum: 2 confirmed upper pivots + 2 confirmed lower pivots.
  if (pivotHighs.length < 2 || pivotLows.length < 2) return { channel: null, rejectionReason: "insufficient_pivots" };

  const { slope: bHigh, intercept: aHigh } = v3LinearRegression(pivotHighs.map((p) => ({ t: p.localIndex, price: p.high })));
  const { slope: bLow, intercept: aLow } = v3LinearRegression(pivotLows.map((p) => ({ t: p.localIndex, price: p.low })));
  const upperAt = (t) => aHigh + bHigh * t;
  const lowerAt = (t) => aLow + bLow * t;

  let direction = null;
  if (bHigh > 0 && bLow > 0) direction = "ascending";
  else if (bHigh < 0 && bLow < 0) direction = "descending";
  else return { channel: null, rejectionReason: "mixed_slope_not_parallel" };

  const startT = 0, endT = window.length - 1;
  const widthStart = upperAt(startT) - lowerAt(startT);
  const widthEnd = upperAt(endT) - lowerAt(endT);
  if (widthStart <= 0 || widthEnd <= 0) return { channel: null, rejectionReason: "degenerate_or_crossed_lines" };

  const widths = [];
  for (let t = startT; t <= endT; t++) widths.push(upperAt(t) - lowerAt(t));
  widths.sort((a, b) => a - b);
  const mid = Math.floor(widths.length / 2);
  const medianChannelWidth = widths.length % 2 === 0 ? (widths[mid - 1] + widths[mid]) / 2 : widths[mid];
  if (medianChannelWidth <= 0) return { channel: null, rejectionReason: "degenerate_or_crossed_lines" };
  // Parallelism test — 20% per this build's explicit instruction
  // (v2's own equivalent check uses 15%; not reused here, see header).
  const channelParallelism = Math.abs(widthEnd - widthStart) / medianChannelWidth;
  if (channelParallelism > 0.20) return { channel: null, rejectionReason: "parallelism_failed" };

  // Pivot residuals within 0.5 × ATR(14) — how tightly the real pivot
  // points actually sit on the fitted lines.
  const residualsOk = pivotHighs.every((p) => Math.abs(p.high - upperAt(p.localIndex)) <= 0.5 * currentAtr) &&
    pivotLows.every((p) => Math.abs(p.low - lowerAt(p.localIndex)) <= 0.5 * currentAtr);
  if (!residualsOk) return { channel: null, rejectionReason: "pivot_residuals_exceeded" };

  // Minimum: 4 alternating touches total. Touches are counted directly
  // against the fitted lines across every bar in the window (not just
  // the confirmed pivots themselves) using the same ATR-based touch zone
  // used everywhere else in this scanner — "alternating" is satisfied
  // structurally by requiring at least 2 touches on EACH line (a channel
  // by definition alternates between testing support and resistance;
  // requiring >=2 of each with >=4 total rules out a lopsided "channel"
  // that only ever touched one side).
  let touchesUpper = 0, touchesLower = 0;
  for (let i = 0; i < window.length; i++) {
    const b = window[i];
    const td = Math.min(b.c * 0.01, 0.5 * currentAtr);
    if (Math.abs(b.h - upperAt(i)) <= td) touchesUpper++;
    if (Math.abs(b.l - lowerAt(i)) <= td) touchesLower++;
  }
  if (touchesUpper < 2 || touchesLower < 2 || touchesUpper + touchesLower < 4) return { channel: null, rejectionReason: "insufficient_touches" };

  const sortedPivotHighs = [...pivotHighs].sort((a, b) => (a.date < b.date ? -1 : 1));
  const sortedPivotLows = [...pivotLows].sort((a, b) => (a.date < b.date ? -1 : 1));
  return {
    channel: {
      windowLen, direction, aHigh, bHigh, aLow, bLow, upperAt, lowerAt,
      touchesUpper, touchesLower, channelParallelism,
      pivotCount: pivotHighs.length + pivotLows.length,
      channelId: `${windowLen}d_${sortedPivotHighs[0].date}_${sortedPivotLows[0].date}_${direction}`,
    },
    rejectionReason: null,
  };
}

// Lookback: 40-120 completed daily SIP bars, per explicit instruction.
// Tries the widest window first (most established channel), same
// step-of-10 granularity v2's own equivalent search already uses
// (disclosed, reasonable, not independently re-derived). Returns
// { channel, rejectionReason } — rejectionReason is only meaningful when
// channel is null, and reflects the widest window's (120-day) rejection
// reason specifically (the first one tried, most standard) rather than a
// full diagnostic across all 9 attempted window lengths — a disclosed
// simplification, not a claim that every window length failed for the
// same reason.
function v3FindBestChannel(allBars, currentAtr) {
  let widestAttemptReason = null;
  for (let windowLen = 120; windowLen >= 40; windowLen -= 10) {
    const { channel, rejectionReason } = v3BuildChannel(allBars, windowLen, currentAtr);
    if (channel) return { channel, rejectionReason: null };
    if (widestAttemptReason === null) widestAttemptReason = rejectionReason;
  }
  return { channel: null, rejectionReason: widestAttemptReason };
}

// Weekly bars, v3's own SIP-explicit fetch (feed=sip, no end= param, same
// 403-avoidance rule as every other v3 Alpaca call in this file) — not a
// reuse of alpacaBarsV2, which specifies no feed at all.
async function v3GetWeeklyBarsSip(symbol, lookbackDays) {
  try {
    const fetch = (await import("node-fetch")).default;
    const startDate = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
    const r = await fetch(`https://data.alpaca.markets/v2/stocks/${symbol}/bars?timeframe=1Week&start=${encodeURIComponent(startDate)}&limit=60&sort=asc&feed=sip`, {
      headers: { "APCA-API-KEY-ID": ALPACA_KEY_ID, "APCA-API-SECRET-KEY": ALPACA_SECRET },
    });
    if (!r.ok) return [];
    const d = await r.json();
    return d?.bars ?? [];
  } catch {
    return [];
  }
}

// Nearest weekly swing level genuinely beyond targetLevel — same 2-bars-
// each-side swing shape as the rest of this file's weekly-level logic,
// scoped to v3's own SIP weekly fetch above.
async function v3FindWeeklyLevelBeyond(symbol, targetLevel, isAbove) {
  const weeklyBars = await v3GetWeeklyBarsSip(symbol, 400);
  const levels = [];
  for (let i = 2; i < weeklyBars.length - 2; i++) {
    const b = weeklyBars[i];
    if (isAbove) {
      if (b.h > weeklyBars[i - 1].h && b.h > weeklyBars[i - 2].h && b.h > weeklyBars[i + 1].h && b.h > weeklyBars[i + 2].h && b.h > targetLevel) levels.push(b.h);
    } else {
      if (b.l < weeklyBars[i - 1].l && b.l < weeklyBars[i - 2].l && b.l < weeklyBars[i + 1].l && b.l < weeklyBars[i + 2].l && b.l < targetLevel) levels.push(b.l);
    }
  }
  if (levels.length === 0) return null;
  return isAbove ? Math.min(...levels) : Math.max(...levels);
}

// Each entry is "<canonical_bucket_key>: <human-readable detail>" — the
// bucket key (before the colon) is what the Swing Lab daily report tallies
// by; the detail after it is what makes the immutable KV record actually
// useful as learning data instead of just a boolean.
function v3DescribeGateFailure(bucketKey, detail) {
  return `${bucketKey}: ${detail}`;
}

// Evaluates one symbol's already-detected channel against the exact
// ASCENDING CHANNEL LONG / DESCENDING CHANNEL SHORT gates from the
// instruction, treating the last bar in `bars` as the confirmation/entry
// bar. Every gate is computed unconditionally (never short-circuited),
// matching this file's established "log every gate, not just the first
// failure" convention (see v2EvaluateDoubleTopBottom).
//
// Codex review FIX 2 (2026-08-07) — ineligibleReason (singular, first-
// failure-only) replaced with ineligibleReasons (plural array) listing
// EVERY failing gate with a real descriptive detail, not just the first
// one hit — "never discard a rejected pattern, it is learning data"
// applies to the FULL set of reasons a pattern failed, not only the
// first-checked one. Canonical bucket keys (touch_distance_exceeded,
// candle_quality_failed, volume_insufficient, channel_not_intact,
// insufficient_rr) match what the Swing Lab daily report tallies by.
//
// target2/weekly-level lookup is optional (weeklyLevelFn) so the 90-day
// backtest can skip ~11,000 extra live network calls and pass a no-op
// instead — target2 is a secondary/informational field, never part of
// the eligibility gate itself.
async function v3EvaluateChannelSetup(symbol, bars, channel, currentAtr, weeklyLevelFn = v3FindWeeklyLevelBeyond) {
  const confirmBar = bars[bars.length - 1];
  const todayT = channel.windowLen - 1;
  const price = confirmBar.c;
  const upperToday = channel.upperAt(todayT);
  const lowerToday = channel.lowerAt(todayT);
  // ATR-based touch zone — not a fixed 1%, per explicit instruction.
  const touchDistance = Math.min(price * 0.01, 0.5 * currentAtr);
  const touchDistanceATR = currentAtr > 0 ? touchDistance / currentAtr : null;
  const stopBuffer = Math.max(0.10, 0.25 * currentAtr);

  const rangeSize = confirmBar.h - confirmBar.l;
  const closePositionPct = rangeSize > 0 ? (confirmBar.c - confirmBar.l) / rangeSize : null;
  const closedGreen = confirmBar.c > confirmBar.o;
  const closedRed = confirmBar.c < confirmBar.o;

  const barsForVolume = bars.slice(-21, -1).filter((b) => b.v && b.v > 0);
  let priorMedianVol = null;
  if (barsForVolume.length >= 15) {
    const vols = barsForVolume.map((b) => b.v).sort((a, b) => a - b);
    const mid = Math.floor(vols.length / 2);
    priorMedianVol = vols.length % 2 === 0 ? (vols[mid - 1] + vols[mid]) / 2 : vols[mid];
  }
  const volumeRatio = priorMedianVol && priorMedianVol > 0 ? confirmBar.v / priorMedianVol : null;
  const volumeOk = volumeRatio != null && volumeRatio >= 1.5;

  const barDate = v3BarDateStr(confirmBar);
  const detectedAt = new Date().toISOString();
  const base = {
    symbol,
    channelType: channel.direction,
    channelDuration: channel.windowLen,
    pivotCount: channel.pivotCount,
    touchDistance,
    touchDistanceATR,
    channelParallelism: channel.channelParallelism,
    volumeRatio,
    dataSource: "alpaca_sip",
    barDate,
    detectedAt,
  };

  if (channel.direction === "ascending") {
    const setupType = "CHANNEL_BOUNCE_LONG";
    // Price within min(1% of price, 0.5×ATR14) of lower line — same
    // "touched down near support" interpretation the proven v2 channel
    // agent uses (day's low reaching the touch zone), not just the
    // close — disclosed since the instruction's wording alone doesn't
    // pin down close-vs-low.
    const touchOk = confirmBar.l <= lowerToday + touchDistance;
    const candleQuality = { closedGreen, closePositionPct, upperHalf: closePositionPct != null && closePositionPct >= 0.5 };
    const candleOk = closedGreen && candleQuality.upperHalf;
    // "Channel still intact" — today's close hasn't already broken
    // outside either line beyond the same touch-zone tolerance.
    const channelIntact = confirmBar.c <= upperToday + touchDistance && confirmBar.c >= lowerToday - touchDistance;

    const target1 = upperToday;
    const target2 = await weeklyLevelFn(symbol, target1, true);
    const stop = lowerToday - stopBuffer;
    const risk = price - stop;
    const reward = target1 - price;
    const riskReward = risk > 0 ? reward / risk : null;
    const rrOk = risk > 0 && reward > 0 && riskReward >= 2.0;

    const gates = { touch: touchOk, candle: candleOk, volume: volumeOk, channelIntact, riskReward: rrOk };
    const eligible = touchOk && candleOk && volumeOk && channelIntact && rrOk;
    const ineligibleReasons = [];
    if (!touchOk) ineligibleReasons.push(v3DescribeGateFailure("touch_distance_exceeded", `today's low $${confirmBar.l.toFixed(2)} is not within touch zone $${touchDistance.toFixed(2)} of the lower line $${lowerToday.toFixed(2)}`));
    if (!candleOk) ineligibleReasons.push(v3DescribeGateFailure("candle_quality_failed", `closedGreen=${closedGreen}, closePositionPct=${closePositionPct != null ? closePositionPct.toFixed(3) : "null"} (need green + upper 50% of range)`));
    if (!volumeOk) ineligibleReasons.push(v3DescribeGateFailure("volume_insufficient", `volumeRatio=${volumeRatio != null ? volumeRatio.toFixed(2) : "null"}x 20-day median (need >=1.5x)`));
    if (!channelIntact) ineligibleReasons.push(v3DescribeGateFailure("channel_not_intact", `today's close $${confirmBar.c.toFixed(2)} outside [$${(lowerToday - touchDistance).toFixed(2)}, $${(upperToday + touchDistance).toFixed(2)}]`));
    if (!rrOk) ineligibleReasons.push(v3DescribeGateFailure("insufficient_rr", `riskReward=${riskReward != null ? riskReward.toFixed(2) : "null"} (need >=2.0, risk=${risk.toFixed(2)}, reward=${reward.toFixed(2)})`));

    // STEP 1 (2026-08-17, System vs. Market outcome capture) -- structured
    // required/actual/passed per gate, IN EVALUATION ORDER, purely
    // exposing values already computed above -- no formula changes.
    // Compound (non-single-threshold) gates get a descriptive
    // required/actual string rather than a fabricated single number.
    const gateResults = [
      { gate: "touch", required: `<=${touchDistance.toFixed(4)} from lower line ($${lowerToday.toFixed(2)})`, actual: (confirmBar.l - lowerToday).toFixed(4), passed: touchOk },
      { gate: "candle", required: "closedGreen && closePositionPct>=0.5", actual: `closedGreen=${closedGreen}, closePositionPct=${closePositionPct != null ? closePositionPct.toFixed(3) : "null"}`, passed: candleOk },
      { gate: "volume", required: 1.5, actual: volumeRatio, passed: volumeOk },
      { gate: "channel_intact", required: `[$${(lowerToday - touchDistance).toFixed(2)}, $${(upperToday + touchDistance).toFixed(2)}]`, actual: confirmBar.c, passed: channelIntact },
      { gate: "riskReward", required: 2.0, actual: riskReward, passed: rrOk },
    ];
    const failedGates = gateResults.filter((g) => !g.passed).map((g) => g.gate);
    const lastGatePassed = (() => { let last = null; for (const g of gateResults) { if (!g.passed) break; last = g.gate; } return last; })();

    return { ...base, setupType, patternLabel: "Channel bounce", weeklyTrendBullish: null, supportLevel: lowerToday, entryReference: price, stop, target1, target2, riskReward, candleQuality, eligible, ineligibleReasons, gates, gateResults, failedGates, lastGatePassed };
  }

  // descending — exact reverse
  const setupType = "CHANNEL_BOUNCE_SHORT";
  const touchOk = confirmBar.h >= upperToday - touchDistance;
  const candleQuality = { closedRed, closePositionPct, lowerHalf: closePositionPct != null && closePositionPct <= 0.5 };
  const candleOk = closedRed && candleQuality.lowerHalf;
  const channelIntact = confirmBar.c <= upperToday + touchDistance && confirmBar.c >= lowerToday - touchDistance;

  const target1 = lowerToday;
  const target2 = await weeklyLevelFn(symbol, target1, false);
  const stop = upperToday + stopBuffer;
  const risk = stop - price;
  const reward = price - target1;
  const riskReward = risk > 0 ? reward / risk : null;
  const rrOk = risk > 0 && reward > 0 && riskReward >= 2.0;

  const gates = { touch: touchOk, candle: candleOk, volume: volumeOk, channelIntact, riskReward: rrOk };
  const eligible = touchOk && candleOk && volumeOk && channelIntact && rrOk;
  const ineligibleReasons = [];
  if (!touchOk) ineligibleReasons.push(v3DescribeGateFailure("touch_distance_exceeded", `today's high $${confirmBar.h.toFixed(2)} is not within touch zone $${touchDistance.toFixed(2)} of the upper line $${upperToday.toFixed(2)}`));
  if (!candleOk) ineligibleReasons.push(v3DescribeGateFailure("candle_quality_failed", `closedRed=${closedRed}, closePositionPct=${closePositionPct != null ? closePositionPct.toFixed(3) : "null"} (need red + lower 50% of range)`));
  if (!volumeOk) ineligibleReasons.push(v3DescribeGateFailure("volume_insufficient", `volumeRatio=${volumeRatio != null ? volumeRatio.toFixed(2) : "null"}x 20-day median (need >=1.5x)`));
  if (!channelIntact) ineligibleReasons.push(v3DescribeGateFailure("channel_not_intact", `today's close $${confirmBar.c.toFixed(2)} outside [$${(lowerToday - touchDistance).toFixed(2)}, $${(upperToday + touchDistance).toFixed(2)}]`));
  if (!rrOk) ineligibleReasons.push(v3DescribeGateFailure("insufficient_rr", `riskReward=${riskReward != null ? riskReward.toFixed(2) : "null"} (need >=2.0, risk=${risk.toFixed(2)}, reward=${reward.toFixed(2)})`));

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- same
  // structured gateResults treatment as the ascending branch above.
  const gateResultsShort = [
    { gate: "touch", required: `<=${touchDistance.toFixed(4)} from upper line ($${upperToday.toFixed(2)})`, actual: (upperToday - confirmBar.h).toFixed(4), passed: touchOk },
    { gate: "candle", required: "closedRed && closePositionPct<=0.5", actual: `closedRed=${closedRed}, closePositionPct=${closePositionPct != null ? closePositionPct.toFixed(3) : "null"}`, passed: candleOk },
    { gate: "volume", required: 1.5, actual: volumeRatio, passed: volumeOk },
    { gate: "channel_intact", required: `[$${(lowerToday - touchDistance).toFixed(2)}, $${(upperToday + touchDistance).toFixed(2)}]`, actual: confirmBar.c, passed: channelIntact },
    { gate: "riskReward", required: 2.0, actual: riskReward, passed: rrOk },
  ];
  const failedGatesShort = gateResultsShort.filter((g) => !g.passed).map((g) => g.gate);
  const lastGatePassedShort = (() => { let last = null; for (const g of gateResultsShort) { if (!g.passed) break; last = g.gate; } return last; })();

  return { ...base, setupType, entryReference: price, stop, target1, target2, riskReward, candleQuality, eligible, ineligibleReasons, gates, gateResults: gateResultsShort, failedGates: failedGatesShort, lastGatePassed: lastGatePassedShort };
}

// ---- runV3ChannelScanner — 4:30pm ET, shadow mode (KV only, no Telegram) ----
// Three independent self-checks, per explicit instruction (defense in
// depth — tick() already only calls this inside the FLEXAI_MODE branch,
// but this function re-verifies all three on its own so it's never
// unsafe to call from anywhere else in the future):
//   1. FLEXAI_MODE === swing_transition or swing_lab
//   2. v3:data:health:{date} status === "ok"
//   3. v3:data:health:{date} finalDailyBarVerified === true
// 2026-08-10 (Codex review, critical fix, second pass) -- dateET is a
// REQUIRED parameter (see runV3DataAgent's header comment for the same
// rationale), supplied by tick() via v3RunJobWithManifest.
// 2026-08-12 (Codex review, critical fix) -- structured return at every
// exit point, same contract as runV3DataAgent above. Also fixed a
// related, same-class bug found while making this change: the health
// gate required status==="ok" strictly, meaning a single excluded
// symbol (status "degraded") would have blocked the channel scanner
// entirely -- the exact bug already fixed for the Master Swing Agent's
// own health gate, just missed here at the time.
// Shared scanning core (2026-08-11, Codex review CHANGE 1) -- extracted
// so an AM instance (real setup pipeline, feeds Master Swing Agent) and
// an EOD instance (pattern-engine-only, "tomorrow's candidates", never
// alerts) can both run the SAME real detection logic on the SAME day
// without the daily-manifest immutability fix (see v3RunJobWithManifest)
// blocking the second call -- each instance is tracked under its own
// jobName/done-flag by its thin wrapper below, this core has no window
// check or done-flag of its own. keySuffix ("" for AM, ":eod" for EOD)
// keeps the two runs' output in separate KV keys so the EOD run never
// clobbers the AM run's same-day shadowlog/candidates (which
// runV3SwingLabDailyReport and the Quality Agent still read at 6pm).
async function v3ChannelScannerCore(dateET, keySuffix) {
  const date = dateET;
  const healthResult = await kvGet(`v3:data:health:${date}`);
  const health = healthResult.ok ? healthResult.value : null;
  const dataUsable = health && (health.status === "ok" || health.status === "degraded") && health.finalDailyBarVerified === true;
  if (!dataUsable) {
    console.log(`v3 CHANNEL SCANNER: gate not satisfied (status=${health?.status}, finalDailyBarVerified=${health?.finalDailyBarVerified}) — not scanning today. Will retry later in this window if health updates.`);
    return { didWork: false, status: "blocked_dependency", skipReason: `Data Agent status=${health?.status ?? "missing"}, finalDailyBarVerified=${health?.finalDailyBarVerified ?? "missing"}` };
  }

  // FIX 1 (2026-08-14, Codex review) -- ALL active v3 jobs now read
  // v3:universe:swing:v2 (100 active symbols), never v1 (123) --
  // mixing the two across a pipeline is exactly what caused the
  // missed-mover audit's validMath:false (its expected-count came from
  // v2 while the real scans it was checking against used v1). Fails
  // explicit if v2 is missing -- never silently falls back to v1.
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols) || universe.symbols.length === 0) {
    console.error("v3 CHANNEL SCANNER: no v3:universe:swing:v2 found — v3BuildUniverseV2 must be run first.");
    await v3SendUniverseUnavailableIncident(dateET, "channelScanner");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };
  }

  // FIX 1 (2026-08-11, Codex review) -- claimed here, after both
  // retryable blocked_dependency gates above, so a legitimate "not
  // ready yet" outcome never consumes the claim and blocks a real
  // later-tick retry. jobName ("channelScanner"/"channelScannerEod")
  // derived from keySuffix so the AM and EOD instances claim
  // independently, matching how they're tracked in v3:jobs:* elsewhere.
  const jobName = keySuffix === ":eod" ? "channelScannerEod" : "channelScanner";
  if (!(await v3ClaimJobStart(jobName, dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };

  console.log("=== v3 CHANNEL SCANNER (shadow mode, no Telegram) starting ===");
  const businessWorkStartedAt = new Date().toISOString();
  const startTime = Date.now();
  const candidates = [];
  const suppressionReasons = {};
  let candidatesEligible = 0;

  const bump = (reason) => { suppressionReasons[reason] = (suppressionReasons[reason] ?? 0) + 1; };
  // Extracts the canonical bucket key from a "<bucket>: <detail>" string
  // (see v3DescribeGateFailure) for tallying purposes.
  const bucketOf = (fullReason) => fullReason.split(":")[0];

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- one real
  // snapshot batch, real gate/setup detail written per symbol below.
  // v3ChannelScannerCore is hardcoded shadow-mode (never sends, see the
  // "no Telegram" log line above, not gated by any flag) -- so a
  // fully-eligible candidate here is always eligible_shadow_blocked,
  // never sent/eligible_capped (no ranking/cap logic exists in this scan
  // at all, unlike the old pipeline's channel/pullback/breakout path).
  const stepOneSnapshots = await v2GetAlpacaSnapshotsForSymbols(universe.symbols);

  for (const symbol of universe.symbols) {
    const { intradayMovePct, isMaterialMover } = v3MoveContextFromSnapshot(stepOneSnapshots[symbol]);
    try {
      // 170 lookback days comfortably covers the 137 bars a 120-day
      // channel + 14-bar ATR seed + 3-bar pivot padding needs, via the
      // same real, SIP-explicit, finalization-gated fetch (v3
      // GetCompletedDailySipBars) used everywhere else in this file —
      // re-verifies the close/final-bar gate on every call, which is
      // redundant with the health-record check above but harmless
      // (belt-and-suspenders, same convention this file already uses).
      const sipResult = (await v3GetCompletedDailySipBars([symbol], 170))[symbol];
      if (!sipResult.ok) { bump("sip_fetch_error"); await v3WriteOutcomeRecord("channel", date, symbol, "skipped_data", { intradayMovePct, isMaterialMover }); continue; }
      if (sipResult.dataIntegrityFailure) { bump("sip_yahoo_data_integrity_failure"); await v3WriteOutcomeRecord("channel", date, symbol, "skipped_data", { intradayMovePct, isMaterialMover }); continue; }
      if (sipResult.barCount < 137) { bump("insufficient_history"); await v3WriteOutcomeRecord("channel", date, symbol, "skipped_data", { intradayMovePct, isMaterialMover }); continue; }

      const bars = sipResult.bars;
      const atrSeries = v3ATRSeries(bars, 14);
      const currentAtr = atrSeries[atrSeries.length - 1];
      if (currentAtr == null) { bump("atr_not_computable"); await v3WriteOutcomeRecord("channel", date, symbol, "skipped_data", { intradayMovePct, isMaterialMover }); continue; }

      // Codex review FIX 2 — v3FindBestChannel now returns a granular
      // rejectionReason (parallelism_failed, insufficient_pivots, etc.)
      // instead of a bare null, so "no channel found today" is still
      // real, tallied learning data, not a single opaque bucket.
      const { channel, rejectionReason } = v3FindBestChannel(bars, currentAtr);
      if (!channel) {
        bump(rejectionReason ?? "no_valid_channel");
        // Real bars, real evaluation -- this stock's price action just
        // didn't form a valid channel shape today. That's a trading
        // judgment, not a data problem, so "rejected" (not
        // skipped_data), with a single descriptive gate entry (no clean
        // required/actual numeric pair exists for "no channel shape
        // found" the way there is for e.g. volume >= 1.5x).
        await v3WriteOutcomeRecord("channel", date, symbol, "rejected", {
          gateResults: [{ gate: "channel_shape", required: "valid ascending/descending channel", actual: rejectionReason ?? "no_valid_channel", passed: false }],
          failedGates: ["channel_shape"], lastGatePassed: null, intradayMovePct, isMaterialMover,
        });
        continue;
      }

      const result = await v3EvaluateChannelSetup(symbol, bars, channel, currentAtr);
      candidates.push(result);
      await v3WriteOutcomeRecord("channel", date, symbol, result.eligible ? "eligible_shadow_blocked" : "rejected", {
        gateResults: result.gateResults ?? null, failedGates: result.failedGates ?? null, lastGatePassed: result.lastGatePassed ?? null,
        setup: result.eligible ? { direction: result.setupType === "CHANNEL_BOUNCE_SHORT" ? "bearish" : "bullish", entry: result.entryReference, stop: result.stop, target1: result.target1, target2: result.target2, riskReward: result.riskReward, dataTimestamp: result.barDate, ruleVersion: "channel_bounce_v2" } : null,
        intradayMovePct, isMaterialMover,
      });

      // Codex review FIX 2 — immutable, individually-addressable record
      // for EVERY pattern found (eligible AND rejected), per explicit
      // schema. Never overwritten by a later symbol/day since the key is
      // unique per date+symbol+setupType; "never discard a rejected
      // pattern — it is learning data."
      await kvSet(`v3:swing:candidate:${date}${keySuffix}:${symbol}:${result.setupType}`, {
        symbol: result.symbol,
        setupType: result.setupType,
        channelType: result.channelType,
        channelDuration: result.channelDuration,
        pivotCount: result.pivotCount,
        touchDistance: result.touchDistance,
        touchDistanceATR: result.touchDistanceATR,
        entryReference: result.entryReference,
        stop: result.stop,
        target1: result.target1,
        target2: result.target2,
        riskReward: result.riskReward,
        volumeRatio: result.volumeRatio,
        candleQuality: result.candleQuality,
        channelParallelism: result.channelParallelism,
        eligible: result.eligible,
        ineligibleReasons: result.ineligibleReasons,
        dataSource: result.dataSource,
        barDate: result.barDate,
        detectedAt: result.detectedAt,
        ...v3SessionDateFields(date, result),
        // Literal per instruction — names the detection METHODOLOGY
        // lineage (this ports the same math as the legacy
        // runChannelBounceV2 function), a different axis from the
        // flexai v2-vs-v3 system distinction; not a typo.
        version: "channel_bounce_v2",
      });

      if (result.eligible) candidatesEligible++;
      else {
        // Every failing gate is tallied here — Codex review FIX 2 also
        // asked that rejected patterns not collapse to "the first reason
        // only"; a pattern failing 2 gates bumps 2 buckets.
        for (const reason of result.ineligibleReasons) bump(bucketOf(reason));
      }

      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      bump("unexpected_error");
      console.error(`v3 CHANNEL SCANNER: error for ${symbol} —`, e.message);
      await v3WriteOutcomeRecord("channel", date, symbol, "skipped_data", { intradayMovePct, isMaterialMover });
    }
  }

  const candidatesFound = candidates.length;
  const candidatesSuppressed = candidatesFound - candidatesEligible;
  const scanDuration = Date.now() - startTime;
  const businessWorkCompletedAt = new Date().toISOString();

  await kvSet(`v3:swing:candidates:${date}${keySuffix}`, candidates);
  await kvSet(`v3:swing:shadowlog:${date}${keySuffix}`, {
    symbolsScanned: universe.symbols.length,
    candidatesFound,
    candidatesEligible,
    candidatesSuppressed,
    suppressionReasons,
    scanDuration,
    completedAt: businessWorkCompletedAt,
  });

  console.log(`v3 CHANNEL SCANNER${keySuffix}: complete — scanned=${universe.symbols.length}, channelsFound=${candidatesFound}, eligible=${candidatesEligible}, suppressed=${candidatesSuppressed}, durationMs=${scanDuration}`);
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt };
}

// ---- runV3ChannelScanner — AM instance, 8:15-8:25am ET (moved from
// 4:30pm 2026-08-11, Codex review CHANGE 1). Feeds the same-morning
// Master Swing Agent / Swing Lab Morning Report chain -- shadow mode
// (KV only, no Telegram), unchanged behavior otherwise. ----
async function runV3ChannelScanner(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3ChannelScannerDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  // 8:15-8:25am ET -- 10-minute window (tick() runs every 5 minutes;
  // anything narrower risks a real day where no tick lands inside the
  // window at all, same reasoning as every other v3 job's window width).
  if (total < 495 || total >= 505) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 8:15-8:25am ET window" };
  // FIX 1's claim happens inside v3ChannelScannerCore, after its own
  // retryable blocked_dependency gates -- see that function's comment.

  const result = await v3ChannelScannerCore(dateET, "");
  if (result.didWork) v3ChannelScannerDone = true;
  return result;
}

// ---- runV3ChannelScannerEod — NEW 2026-08-11, Codex review CHANGE 1.
// 4:30-4:40pm ET (the AM instance's OLD slot) -- pattern-engine-only
// re-scan using today's now-final daily bar, producing tomorrow's
// candidates. Deliberately does NOT run Master Swing Agent and does NOT
// send a subscriber/setup message -- only sends an admin alert if the
// scan itself couldn't run (bad/missing data), per explicit instruction
// ("no evening Telegram unless system/data problem"). ----
async function runV3ChannelScannerEod(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3ChannelScannerEodDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  if (total < 990 || total >= 1000) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 4:30-4:40pm ET window" };
  // FIX 1's claim happens inside v3ChannelScannerCore, after its own
  // retryable blocked_dependency gates -- see that function's comment.

  // URGENT FIX 1 (2026-08-11, Codex review) -- removed the
  // blocked_dependency/failed admin alert that used to send here. Per
  // explicit instruction, the EOD path must never send to Swing Lab at
  // all, full stop -- "writes candidates to KV only... nothing else."
  // A failure is still fully visible via this job's own KV manifest
  // (v3:jobs:channelScannerEod:{date}, status/skipReason) -- same
  // "inspectable in KV, not necessarily pushed to Telegram" principle
  // FIX 4 applies to the scan's own diagnostic content below.
  const result = await v3ChannelScannerCore(dateET, ":eod");
  if (result.didWork) v3ChannelScannerEodDone = true;
  return result;
}

// ============================================================
// PATTERN SUITE — TREND PULLBACK / SUPPORT RECLAIM,
// BASE BREAKOUT / VOLATILITY CONTRACTION (2026-08-10)
//
// Per CLAUDE.md's THRESHOLD/CONDITION CHANGE RULE, every numeric
// threshold below is sourced from a real 8+ query research pass (not
// invented) -- cited inline at each threshold, not just in this header.
// Ports v2EMASeries/v2RSISeries (proven, already-live formulas) to
// v3-namespaced versions, same "reuse proven math, no v2 state
// dependency" principle already used for pivot/ATR/regression.
// ============================================================

function v3EMASeries(closes, period) {
  if (closes.length < period) return [];
  const k = 2 / (period + 1);
  const series = [];
  let ema = closes.slice(0, period).reduce((a, b) => a + b, 0) / period;
  series[period - 1] = ema;
  for (let i = period; i < closes.length; i++) { ema = closes[i] * k + ema * (1 - k); series[i] = ema; }
  return series;
}

// Wilder's smoothing RSI -- the canonical formula itself, not a tunable
// threshold (same note as v2RSISeries, which this ports verbatim).
function v3RSISeries(closes, period = 14) {
  if (closes.length < period + 1) return [];
  const series = [];
  let gainSum = 0, lossSum = 0;
  for (let i = 1; i <= period; i++) {
    const change = closes[i] - closes[i - 1];
    if (change >= 0) gainSum += change; else lossSum -= change;
  }
  let avgGain = gainSum / period;
  let avgLoss = lossSum / period;
  series[period] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
  for (let i = period + 1; i < closes.length; i++) {
    const change = closes[i] - closes[i - 1];
    const gain = change >= 0 ? change : 0;
    const loss = change < 0 ? -change : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
    series[i] = avgLoss === 0 ? 100 : 100 - 100 / (1 + avgGain / avgLoss);
  }
  return series;
}

// SOURCED (2026-08-10): "price staying above rising 10-week and 30-week
// moving averages would serve as confirmation of an upward trend" --
// the standard Stan Weinstein-style weekly "Stage 2 uptrend" filter,
// confirmed across multiple swing-trading sources. "Rising" = the EMA's
// current value exceeds its value 4 weeks ago (a standard slope check).
// Requires 34+ weekly bars (30-period EMA + 4-week slope lookback).
function v3CheckWeeklyTrendBullish(weeklyBars) {
  if (!weeklyBars || weeklyBars.length < 34) return { bullish: false, reason: "insufficient_weekly_bars" };
  const closes = weeklyBars.map((b) => b.c);
  const ema10 = v3EMASeries(closes, 10);
  const ema30 = v3EMASeries(closes, 30);
  const lastIdx = closes.length - 1;
  const ema10Now = ema10[lastIdx], ema30Now = ema30[lastIdx];
  const ema10Prior = ema10[lastIdx - 4], ema30Prior = ema30[lastIdx - 4];
  if (ema10Now == null || ema30Now == null || ema10Prior == null || ema30Prior == null) {
    return { bullish: false, reason: "ema_not_computable" };
  }
  const price = closes[lastIdx];
  const priceAboveBoth = price > ema10Now && price > ema30Now;
  const ema10Rising = ema10Now > ema10Prior;
  const ema30Rising = ema30Now > ema30Prior;
  const bullish = priceAboveBoth && ema10Rising && ema30Rising;
  return { bullish, priceAboveBoth, ema10Rising, ema30Rising, ema10: ema10Now, ema30: ema30Now, reason: bullish ? "weekly_uptrend_confirmed" : "weekly_trend_not_bullish" };
}

function v3DescribeSwingGateFailure(bucketKey, detail) {
  return `${bucketKey}: ${detail}`;
}

// ---- PATTERN 2 — Trend Pullback / Support Reclaim ----
// SOURCED (2026-08-10):
//  - Pullback = daily price retraces to the 20 or 50 daily EMA (dynamic
//    support in an uptrend) and holds -- "price retraces to the 20 or
//    50 EMA, holds that level, and then resumes" (multiple sources).
//  - RSI(14) 40-60 on the reclaim day -- "above 70, the pullback hasn't
//    gone far enough... below 40, the trend might be breaking... 40-60
//    is where the stock has found equilibrium."
//  - Reclaim candle: closes green, volume >= 1.5x the 20-day average --
//    "the reversal candle itself should print volume at least 1.5x the
//    20-bar average," and confirmation should come "within 1 to 3 days."
//    This implementation checks the confirm (today) bar directly.
//  - Stop: below the pullback low (the support being tested) -- "stop
//    below support... just below the support."
//  - R:R >= 2:1 -- same sourced standard as Channel Bounce V3.
// ATR-based touch zone (not fixed 1%) reuses the exact convention
// already established and sourced for Channel Bounce V3.
async function v3EvaluateTrendPullback(symbol, bars, weeklyBars, currentAtr, weeklyLevelFn = v3FindWeeklyLevelBeyond) {
  const setupType = "TREND_PULLBACK_LONG";
  const confirmBar = bars[bars.length - 1];
  const price = confirmBar.c;
  const barDate = v3BarDateStr(confirmBar);
  const detectedAt = new Date().toISOString();
  const dataSource = "alpaca_sip";

  const weeklyTrend = v3CheckWeeklyTrendBullish(weeklyBars);

  const closes = bars.map((b) => b.c);
  if (closes.length < 51) {
    return { symbol, setupType, eligible: false, ineligibleReasons: [v3DescribeSwingGateFailure("insufficient_history", `${closes.length} daily bars, need 51+ for a 50-EMA seed`)], dataSource, barDate, detectedAt };
  }
  const ema20Series = v3EMASeries(closes, 20);
  const ema50Series = v3EMASeries(closes, 50);
  const rsiSeries = v3RSISeries(closes, 14);
  const lastIdx = closes.length - 1;
  const ema20 = ema20Series[lastIdx], ema50 = ema50Series[lastIdx], rsi = rsiSeries[lastIdx];
  if (ema20 == null || ema50 == null || rsi == null) {
    return { symbol, setupType, eligible: false, ineligibleReasons: [v3DescribeSwingGateFailure("indicators_not_computable", "EMA20/EMA50/RSI14 not computable from available bars")], dataSource, barDate, detectedAt };
  }

  const touchDistance = Math.min(price * 0.01, 0.5 * currentAtr);
  const touchDistanceATR = currentAtr > 0 ? touchDistance / currentAtr : null;
  // Touched EITHER the 20 or 50 EMA today (whichever is nearer/relevant) -- prefer the 20 EMA (shallower pullback) if both qualify.
  const touched20 = confirmBar.l <= ema20 + touchDistance && confirmBar.l >= ema20 - touchDistance * 3;
  const touched50 = confirmBar.l <= ema50 + touchDistance && confirmBar.l >= ema50 - touchDistance * 3;
  const touchedEma = touched20 ? "ema20" : touched50 ? "ema50" : null;
  const pullbackLevel = touched20 ? ema20 : touched50 ? ema50 : null;
  const touchOk = touchedEma !== null;

  const closeBuffer = Math.max(0.10, price * 0.001);
  const reclaimOk = touchOk && confirmBar.c >= pullbackLevel + closeBuffer;
  const closedGreen = confirmBar.c > confirmBar.o;
  const rsiOk = rsi >= 40 && rsi <= 60;

  const barsForVolume = bars.slice(-21, -1).filter((b) => b.v && b.v > 0);
  let priorMedianVol = null;
  if (barsForVolume.length >= 15) {
    const vols = barsForVolume.map((b) => b.v).sort((a, b) => a - b);
    const mid = Math.floor(vols.length / 2);
    priorMedianVol = vols.length % 2 === 0 ? (vols[mid - 1] + vols[mid]) / 2 : vols[mid];
  }
  const volumeRatio = priorMedianVol && priorMedianVol > 0 ? confirmBar.v / priorMedianVol : null;
  const volumeOk = volumeRatio != null && volumeRatio >= 1.5;

  // Target1: most recent swing high in the last 40 bars (a real,
  // measurable near-term objective) -- must be genuinely above entry.
  const last40 = bars.slice(-40);
  const recentHigh = Math.max(...last40.map((b) => b.h));
  const target1 = recentHigh > price ? recentHigh : null;
  const target2 = target1 != null ? await weeklyLevelFn(symbol, target1, true) : null;
  const pullbackLow = touchOk ? Math.min(confirmBar.l, pullbackLevel) : confirmBar.l;
  const stopBuffer = Math.max(0.10, 0.25 * currentAtr);
  const stop = pullbackLow - stopBuffer;
  const risk = price - stop;
  const reward = target1 != null ? target1 - price : null;
  const riskReward = risk > 0 && reward != null ? reward / risk : null;
  const rrOk = risk > 0 && reward != null && reward > 0 && riskReward >= 2.0;

  const candleQuality = { closedGreen, rsi: Math.round(rsi * 10) / 10 };
  const gates = { touch: touchOk, reclaim: reclaimOk, candle: closedGreen, rsi: rsiOk, volume: volumeOk, weeklyTrend: weeklyTrend.bullish, riskReward: rrOk };
  const eligible = touchOk && reclaimOk && closedGreen && rsiOk && volumeOk && weeklyTrend.bullish && rrOk;

  const ineligibleReasons = [];
  if (!touchOk) ineligibleReasons.push(v3DescribeSwingGateFailure("touch_distance_exceeded", `today's low $${confirmBar.l.toFixed(2)} did not touch the 20-EMA ($${ema20.toFixed(2)}) or 50-EMA ($${ema50.toFixed(2)}) within $${touchDistance.toFixed(2)}`));
  if (touchOk && !reclaimOk) ineligibleReasons.push(v3DescribeSwingGateFailure("reclaim_not_confirmed", `close $${confirmBar.c.toFixed(2)} did not close back above the touched EMA ($${pullbackLevel.toFixed(2)}) + buffer`));
  if (!closedGreen) ineligibleReasons.push(v3DescribeSwingGateFailure("candle_quality_failed", `did not close green (o=$${confirmBar.o.toFixed(2)}, c=$${confirmBar.c.toFixed(2)})`));
  if (!rsiOk) ineligibleReasons.push(v3DescribeSwingGateFailure("rsi_outside_reclaim_range", `RSI14=${rsi.toFixed(1)} (need 40-60)`));
  if (!volumeOk) ineligibleReasons.push(v3DescribeSwingGateFailure("volume_insufficient", `volumeRatio=${volumeRatio != null ? volumeRatio.toFixed(2) : "null"}x 20-day median (need >=1.5x)`));
  if (!weeklyTrend.bullish) ineligibleReasons.push(v3DescribeSwingGateFailure("weekly_trend_not_bullish", weeklyTrend.reason));
  if (!rrOk) ineligibleReasons.push(v3DescribeSwingGateFailure("insufficient_rr", `riskReward=${riskReward != null ? riskReward.toFixed(2) : "null"} (need >=2.0)`));

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- structured
  // required/actual/passed per gate, IN EVALUATION ORDER, purely
  // exposing values already computed above -- no formula changes.
  const nearestEmaDistance = Math.min(Math.abs(confirmBar.l - ema20), Math.abs(confirmBar.l - ema50));
  const gateResults = [
    { gate: "touch", required: `<=${touchDistance.toFixed(4)} from EMA20 ($${ema20.toFixed(2)}) or EMA50 ($${ema50.toFixed(2)})`, actual: nearestEmaDistance.toFixed(4), passed: touchOk },
    { gate: "reclaim", required: pullbackLevel != null ? `close >= $${(pullbackLevel + closeBuffer).toFixed(2)}` : "n/a (no EMA touched)", actual: pullbackLevel != null ? (confirmBar.c - pullbackLevel).toFixed(4) : null, passed: reclaimOk },
    { gate: "candle", required: "closedGreen", actual: closedGreen, passed: closedGreen },
    { gate: "rsi", required: "40-60", actual: rsi, passed: rsiOk },
    { gate: "volume", required: 1.5, actual: volumeRatio, passed: volumeOk },
    { gate: "weeklyTrend", required: "bullish", actual: weeklyTrend.bullish, passed: weeklyTrend.bullish },
    { gate: "riskReward", required: 2.0, actual: riskReward, passed: rrOk },
  ];
  const failedGates = gateResults.filter((g) => !g.passed).map((g) => g.gate);
  const lastGatePassed = (() => { let last = null; for (const g of gateResults) { if (!g.passed) break; last = g.gate; } return last; })();

  return {
    symbol, setupType, patternLabel: "Trend pullback / support reclaim",
    weeklyTrendBullish: weeklyTrend.bullish, touchedEma, pullbackLevel, rsi14: rsi,
    touchDistance, touchDistanceATR, entryReference: price, stop, target1, target2, riskReward,
    volumeRatio, candleQuality, eligible, ineligibleReasons, gates, gateResults, failedGates, lastGatePassed, dataSource, barDate, detectedAt,
  };
}

// ---- PATTERN 3 — Base Breakout / Volatility Contraction ----
// SOURCED (2026-08-10):
//  - Base window: ~40 trading days (~8 weeks) -- within the sourced
//    5-12+ week base-duration range (IBD flat base minimum 5 weeks;
//    Minervini VCP typically spans multiple weeks of contraction).
//  - Base depth: <=25% off the base high -- a defensible middle bound
//    between the two sourced figures (IBD flat base caps depth at 15%;
//    cup-with-handle allows up to 33%).
//  - Contraction: the most recent ~10-day sub-window's high-low range
//    must be tighter than the base's earlier sub-window -- a disclosed,
//    SIMPLIFIED 2-leg proxy for Minervini's full "three or more
//    contractions, each smaller than the previous" VCP structure (a
//    complete 3+-leg segmentation is out of scope for a single-day
//    real-time check).
//  - Breakout trigger: close clears the base pivot (highest CLOSE in
//    the base window, excluding today) on volume >= 1.4x the 50-day
//    average -- sourced ("volume at least 40% to 50% above the 50-day
//    average volume" -- IBD/Minervini).
//  - Target1: measured-move projection (pivot + base height) -- the
//    same measured-move convention already used elsewhere in this
//    project's chart-pattern work (head-and-shoulders neckline target).
//  - Stop: below the base low. R:R >= 2:1, same sourced standard.
async function v3EvaluateBaseBreakout(symbol, bars, weeklyBars, currentAtr, weeklyLevelFn = v3FindWeeklyLevelBeyond) {
  const setupType = "BASE_BREAKOUT_LONG";
  const confirmBar = bars[bars.length - 1];
  const price = confirmBar.c;
  const barDate = v3BarDateStr(confirmBar);
  const detectedAt = new Date().toISOString();
  const dataSource = "alpaca_sip";

  const weeklyTrend = v3CheckWeeklyTrendBullish(weeklyBars);

  const BASE_WINDOW = 40;
  if (bars.length < BASE_WINDOW + 51) {
    return { symbol, setupType, eligible: false, ineligibleReasons: [v3DescribeSwingGateFailure("insufficient_history", `${bars.length} daily bars, need ${BASE_WINDOW + 51}+`)], dataSource, barDate, detectedAt };
  }
  const baseBars = bars.slice(-(BASE_WINDOW + 1), -1); // excludes today (the potential breakout day)
  const baseHighClose = Math.max(...baseBars.map((b) => b.c));
  const baseHigh = Math.max(...baseBars.map((b) => b.h));
  const baseLow = Math.min(...baseBars.map((b) => b.l));
  const baseDepthPct = baseHigh > 0 ? (baseHigh - baseLow) / baseHigh : 1;
  const baseDepthOk = baseDepthPct <= 0.25;

  const firstHalf = baseBars.slice(0, Math.floor(baseBars.length / 2));
  const secondHalf = baseBars.slice(-10); // most recent ~10 days
  const rangePct = (segment) => {
    const hi = Math.max(...segment.map((b) => b.h));
    const lo = Math.min(...segment.map((b) => b.l));
    return hi > 0 ? (hi - lo) / hi : 1;
  };
  const firstHalfRange = rangePct(firstHalf);
  const secondHalfRange = rangePct(secondHalf);
  const contractionOk = secondHalfRange < firstHalfRange;

  const pivot = baseHighClose;
  const breakoutOk = confirmBar.c > pivot;

  const last50Vol = bars.slice(-51, -1).filter((b) => b.v && b.v > 0);
  let avgVol50 = null;
  if (last50Vol.length >= 30) avgVol50 = last50Vol.reduce((s, b) => s + b.v, 0) / last50Vol.length;
  const volumeRatio = avgVol50 && avgVol50 > 0 ? confirmBar.v / avgVol50 : null;
  const volumeOk = volumeRatio != null && volumeRatio >= 1.4;

  const closedGreen = confirmBar.c > confirmBar.o;

  const baseHeight = baseHigh - baseLow;
  // Unconditional on breakoutOk -- the measured-move target is a
  // property of the base structure itself ("if/when this breaks out,
  // here's the objective"), not of whether today specifically confirmed
  // the breakout. This matters for the Master Swing Agent's conditional
  // watch candidates, which need a real target/R:R computed even before
  // the trigger fires.
  const target1 = pivot + baseHeight;
  const target2 = target1 != null ? await weeklyLevelFn(symbol, target1, true) : null;
  const stopBuffer = Math.max(0.10, 0.25 * currentAtr);
  const stop = baseLow - stopBuffer;
  const risk = price - stop;
  const reward = target1 != null ? target1 - price : null;
  const riskReward = risk > 0 && reward != null ? reward / risk : null;
  const rrOk = risk > 0 && reward != null && reward > 0 && riskReward >= 2.0;

  const candleQuality = { closedGreen };
  const gates = { baseDepth: baseDepthOk, contraction: contractionOk, breakout: breakoutOk, candle: closedGreen, volume: volumeOk, weeklyTrend: weeklyTrend.bullish, riskReward: rrOk };
  const eligible = baseDepthOk && contractionOk && breakoutOk && closedGreen && volumeOk && weeklyTrend.bullish && rrOk;

  const ineligibleReasons = [];
  if (!baseDepthOk) ineligibleReasons.push(v3DescribeSwingGateFailure("base_too_deep", `base depth ${(baseDepthPct * 100).toFixed(1)}% (need <=25%)`));
  if (!contractionOk) ineligibleReasons.push(v3DescribeSwingGateFailure("no_contraction", `recent 10-day range ${(secondHalfRange * 100).toFixed(1)}% not tighter than earlier base range ${(firstHalfRange * 100).toFixed(1)}%`));
  if (!breakoutOk) ineligibleReasons.push(v3DescribeSwingGateFailure("touch_distance_exceeded", `close $${confirmBar.c.toFixed(2)} has not cleared the base pivot $${pivot.toFixed(2)}`));
  if (!closedGreen) ineligibleReasons.push(v3DescribeSwingGateFailure("candle_quality_failed", `did not close green`));
  if (!volumeOk) ineligibleReasons.push(v3DescribeSwingGateFailure("volume_insufficient", `volumeRatio=${volumeRatio != null ? volumeRatio.toFixed(2) : "null"}x 50-day average (need >=1.4x)`));
  if (!weeklyTrend.bullish) ineligibleReasons.push(v3DescribeSwingGateFailure("weekly_trend_not_bullish", weeklyTrend.reason));
  if (!rrOk) ineligibleReasons.push(v3DescribeSwingGateFailure("insufficient_rr", `riskReward=${riskReward != null ? riskReward.toFixed(2) : "null"} (need >=2.0)`));

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- structured
  // required/actual/passed per gate, IN EVALUATION ORDER, purely
  // exposing values already computed above -- no formula changes.
  const gateResults = [
    { gate: "baseDepth", required: 0.25, actual: baseDepthPct, passed: baseDepthOk },
    { gate: "contraction", required: firstHalfRange, actual: secondHalfRange, passed: contractionOk },
    { gate: "breakout", required: pivot, actual: confirmBar.c, passed: breakoutOk },
    { gate: "candle", required: "closedGreen", actual: closedGreen, passed: closedGreen },
    { gate: "volume", required: 1.4, actual: volumeRatio, passed: volumeOk },
    { gate: "weeklyTrend", required: "bullish", actual: weeklyTrend.bullish, passed: weeklyTrend.bullish },
    { gate: "riskReward", required: 2.0, actual: riskReward, passed: rrOk },
  ];
  const failedGates = gateResults.filter((g) => !g.passed).map((g) => g.gate);
  const lastGatePassed = (() => { let last = null; for (const g of gateResults) { if (!g.passed) break; last = g.gate; } return last; })();

  return {
    symbol, setupType, patternLabel: "Base breakout / volatility contraction",
    weeklyTrendBullish: weeklyTrend.bullish, baseDurationDays: BASE_WINDOW, baseDepthPct, contractionConfirmed: contractionOk, pivotPrice: pivot,
    entryReference: price, stop, target1, target2, riskReward,
    volumeRatio, candleQuality, eligible, ineligibleReasons, gates, gateResults, failedGates, lastGatePassed, dataSource, barDate, detectedAt,
  };
}

// ---- runV3SwingLabDailyReport — 6:00-6:10pm ET, added 2026-08-07 per
// Codex review. Sends to TELEGRAM_SWING_ADMIN_CHAT_ID ONLY, via
// v3SendTelegram (never sendTelegram/sendTelegramWithId/
// gatewaySendTelegram — those all resolve to legacy chats and are
// already FLEXAI_MODE-blocked besides). Reads today's shadowlog +
// candidates written by runV3ChannelScanner above; if the scanner hasn't
// completed yet (shadowlog missing) this simply doesn't send rather than
// sending a report with fabricated/placeholder numbers. ----
// 2026-08-10 (Codex review, critical fix, second pass) -- dateET is a
// REQUIRED parameter (see runV3DataAgent's header comment for the same
// rationale), supplied by tick() via v3RunJobWithManifest (now also
// wrapping this function, previously the one v3 job left unwrapped).
// 2026-08-12 (Codex review, critical fix) -- structured return at every
// exit point, same contract as the other v3 jobs above.
async function runV3SwingLabDailyReport(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3SwingLabReportDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  if (total < 1080 || total >= 1090) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 6:00-6:10pm ET window" }; // 6:00-6:10pm ET

  const date = dateET;
  const businessWorkStartedAt = new Date().toISOString();
  const shadowlogResult = await kvGet(`v3:swing:shadowlog:${date}`);
  const shadowlog = shadowlogResult.ok ? shadowlogResult.value : null;
  if (!shadowlog) {
    console.log("v3 SWING LAB REPORT: no shadowlog yet for today — scanner may not have completed. Will retry later in this window.");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:swing:shadowlog:{date} not written yet -- Channel Scanner may not have completed" };
  }
  // FIX 1 (2026-08-11) -- claimed after the retryable shadowlog gate above.
  if (!(await v3ClaimJobStart("swingLabReport", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };
  const candidatesResult = await kvGet(`v3:swing:candidates:${date}`);
  const candidates = candidatesResult.ok && Array.isArray(candidatesResult.value) ? candidatesResult.value : [];
  // FIX 3 (2026-08-11, urgent) -- the report now shows universe
  // scan coverage and any excluded symbols explicitly, sourced from the
  // same health record runV3DataAgent already writes (no separate
  // LIST/SCAN needed -- exclusionReasons already carries the per-symbol
  // diffPct detail added by that same fix).
  const healthResult = await kvGet(`v3:data:health:${date}`);
  const health = healthResult.ok ? healthResult.value : null;

  // URGENT FIX (2026-08-11, Codex review) -- this report is internal
  // scanner diagnostics (channel-detection counts, parallelism/pivot
  // failure buckets, "Shadow mode" status text) built by
  // v3BuildSwingLabReportMessage. It used to be the ONLY thing this
  // system sent to the Swing Lab chat, back when the whole pipeline was
  // shadow-only -- appropriate then. Now that runV3SwingLabMorningReport
  // sends real actionable setups to the SAME chat every morning, this
  // 6pm diagnostic dump doesn't belong there anymore: confirmed live
  // (real KV, mode=swing_live_admin) that it sent "CHANNEL PATTERNS
  // DETECTED" + "STATUS: Shadow mode — no trade alerts sent" to Swing
  // Lab tonight at 6:03pm ET, which read as a real alert to anyone not
  // expecting an internal-diagnostics message in that chat. Per
  // explicit instruction, Swing Lab now receives ONLY the morning
  // actionable-plan-or-no-setup message -- this report's data (exactly
  // "channel detection counts, parallelism failures, pivot counts")
  // stays KV-only, same convention as v3:swing:morningReport:{date}.
  // BUG FIX (2026-08-26) -- `message` was referenced below without ever
  // being built, throwing ReferenceError every run in this window
  // (unhandled rejection -> worker crash/restart). The 2026-08-11 fix
  // above removed the v3SendTelegram(message, ...) call (this report
  // moved KV-only) but the line that actually built `message` via
  // v3BuildSwingLabReportMessage was dropped along with it instead of
  // being kept. Restored here -- same function, same real
  // shadowlog/candidates/health inputs already computed above.
  const message = v3BuildSwingLabReportMessage(date, shadowlog, candidates, health);
  await kvSet(`v3:swing:eveningReport:${date}`, { date, message, health, completedAt: new Date().toISOString() });
  v3SwingLabReportDone = true;
  console.log("v3 SWING LAB REPORT: complete — written to v3:swing:eveningReport (KV only, no longer sent to Telegram, see 2026-08-11 fix).");
  const businessWorkCompletedAt = new Date().toISOString();
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt };
}

// 2026-08-08 (Codex review FIX 1) — the flat "Gate failures:" list from
// the prior version mixed structural pattern-detection reasons
// (parallelism_failed, insufficient_pivots, etc. -- checked against ALL
// scanned symbols) with trade-quality eligibility reasons
// (channel_not_intact, volume_insufficient, etc. -- only meaningful for
// the small number of symbols where a channel was actually DETECTED),
// so a big number like parallelism_failed:84 appeared to compete with
// "3 patterns found" as if they were the same funnel stage. They are
// two separate funnel stages and are now reported as two separate
// sections. Extracted into its own function (previously inlined) so it
// can be called with real KV data for a live send AND with the exact
// same real data for a dry-run preview (see the "Show what tomorrow's
// report will look like" verification below) without ever needing a
// second, hand-typed copy of the template that could drift from the
// real one.
const V3_STRUCTURAL_BUCKETS = [
  { key: "parallelism_failed", label: "parallelism failed" },
  { key: "insufficient_pivots", label: "insufficient pivots" },
  { key: "degenerate_or_crossed_lines", label: "degenerate/crossed lines" },
  { key: "mixed_slope_not_parallel", label: "mixed slope" },
];
const V3_TRADE_QUALITY_BUCKETS = [
  { key: "channel_not_intact", label: "channel no longer intact" },
  { key: "volume_insufficient", label: "volume confirmation absent" },
  { key: "insufficient_rr", label: "reward/risk below 2:1" },
  { key: "touch_distance_exceeded", label: "touch distance exceeded" },
];
const V3_TRADE_QUALITY_KEYS = new Set(V3_TRADE_QUALITY_BUCKETS.map((b) => b.key).concat(["candle_quality_failed"]));

function v3BuildSwingLabReportMessage(date, shadowlog, candidates, health = null) {
  const reasons = shadowlog.suppressionReasons || {};

  // FIX 3 (2026-08-11, urgent), reformatted 2026-08-12 (Codex review
  // FIX 1) -- universe scan coverage + excluded symbols, now folded
  // into a single "Data notes:" line instead of the previous per-symbol
  // immediate Telegram alert (removed -- see the exclusion branch in
  // runV3DataAgent). This report line is the ONLY place excluded
  // symbols are now surfaced. Only data-integrity exclusions get the
  // diffPct-annotated phrasing (that's what this fix is actually about
  // surfacing); other exclusion reasons (insufficient_bars, corporate
  // action, etc.) still show, just without a percentage. Note: by
  // construction, anything landing in exclusionReasons with reason
  // "sip_yahoo_data_integrity_failure" has diffPct > 1.0% (the
  // exclusion threshold) -- there is no "excluded but actually below
  // threshold" case anymore post-fix, unlike the GS incident this whole
  // fix chain responds to.
  let universeLine = "";
  if (health && typeof health.symbolsValid === "number" && typeof health.symbolsChecked === "number") {
    universeLine = `Universe: ${health.symbolsValid}/${health.symbolsChecked} scanned\n`;
    const excluded = (health.exclusionReasons || []);
    if (excluded.length > 0) {
      const dataNoteLines = excluded.map((e) => {
        if (e.reason === "sip_yahoo_data_integrity_failure" && e.diffPct != null) {
          return `${e.symbol} excluded — ${e.diffPct}% SIP/Yahoo discrepancy`;
        }
        return `${e.symbol} excluded — ${e.reason}`;
      });
      universeLine += `Data notes: ${dataNoteLines.join("; ")}\n`;
    }
    universeLine += "\n";
  }

  // Everything NOT a trade-quality reason is structural (pattern never
  // even formed for that symbol) -- includes the 4 named buckets plus
  // anything else real that occurred (pivot_residuals_exceeded,
  // insufficient_touches, sip_fetch_error, etc.), never silently
  // dropped, per "never discard a rejected pattern."
  const structuralReasonKeys = Object.keys(reasons).filter((k) => !V3_TRADE_QUALITY_KEYS.has(k));
  const structuralTotal = structuralReasonKeys.reduce((sum, k) => sum + reasons[k], 0);
  const structuralNamedLines = V3_STRUCTURAL_BUCKETS.map((b) => `  - ${b.label}: ${reasons[b.key] ?? 0}`);
  const structuralOtherLines = structuralReasonKeys
    .filter((k) => !V3_STRUCTURAL_BUCKETS.some((b) => b.key === k))
    .map((k) => `  - ${k}: ${reasons[k]}`);

  const tradeQualityNamedLines = V3_TRADE_QUALITY_BUCKETS.map((b) => `  - ${b.label}: ${reasons[b.key] ?? 0}`);
  const tradeQualityOtherLines = Object.keys(reasons)
    .filter((k) => V3_TRADE_QUALITY_KEYS.has(k) && !V3_TRADE_QUALITY_BUCKETS.some((b) => b.key === k))
    .map((k) => `  - ${k}: ${reasons[k]}`);

  const eligible = candidates.filter((c) => c.eligible);
  const eligibleLines = eligible.length > 0
    ? eligible.map((c) => `${c.symbol} — ${c.setupType === "CHANNEL_BOUNCE_LONG" ? "LONG" : "SHORT"} — R:R ${c.riskReward.toFixed(1)}:1`).join("\n")
    : "No eligible setups today";

  return `📊 FLEXAI SWING LAB — ${date}

${universeLine}STRUCTURAL SCREENING (applied to all ${shadowlog.symbolsScanned} symbols):
- No valid channel structure: ${structuralTotal}
${structuralNamedLines.join("\n")}${structuralOtherLines.length > 0 ? "\n" + structuralOtherLines.join("\n") : ""}

CHANNEL PATTERNS DETECTED: ${shadowlog.candidatesFound}

TRADE QUALITY SCREENING (applied to ${shadowlog.candidatesFound} detected patterns):
- Eligible: ${shadowlog.candidatesEligible}
- Rejected: ${shadowlog.candidatesSuppressed}
${tradeQualityNamedLines.join("\n")}${tradeQualityOtherLines.length > 0 ? "\n" + tradeQualityOtherLines.join("\n") : ""}

Eligible candidates:
${eligibleLines}

STATUS: Shadow mode — no trade alerts sent
⚠️ Not financial advice`;
}

// ============================================================
// MASTER SWING AGENT (2026-08-10) -- FLEXAI_MODE=swing_live_admin
//
// Runs the full pattern suite (Channel Bounce + Trend Pullback + Base
// Breakout) fresh across the swing universe (one SIP-bar + weekly-bar
// fetch per symbol serves all 3 checks), rejects bad/incomplete data,
// ranks all ELIGIBLE candidates by risk:reward, selects a MAXIMUM of 2
// per day (deduplicated by symbol -- a symbol qualifying on more than
// one pattern only ever contributes its single best one), and sends
// complete setup plans via v3SendTelegram -- but ONLY when
// isSwingLiveAdminActive(). In swing_transition/swing_lab this still
// runs the exact same ranking/selection logic and writes the exact same
// KV records, just never calls v3SendTelegram -- so the real selection
// logic is exercised and verifiable before it is ever live.
//
// "Rejects bad data": gated on v3:data:health:{dateET}.status==="ok"
// AND finalDailyBarVerified===true before scanning anything.
//
// Channel Bounce's own eligibility (v3EvaluateChannelSetup) has no
// weekly-trend gate of its own (that function is shared with, and its
// existing behavior preserved for, the already-tested standalone
// runV3ChannelScanner shadow scanner) -- the Master Agent applies an
// ADDITIONAL weekly-trend-bullish requirement on top, specifically for
// its own ranking pool, rather than changing the shared function.
// Short-side channel setups (CHANNEL_BOUNCE_SHORT) are excluded from
// Master Agent ranking entirely -- the alert format itself
// ("Weekly trend: bullish") is long-only, per explicit instruction;
// short candidates are still evaluated and written as immutable
// records for learning-data purposes, just never selected/sent.
//
// If fewer than 2 fully eligible setups exist, remaining slots (up to 2
// total) are filled with CONDITIONAL WATCH candidates: every gate
// passes EXCEPT the immediate trigger gate (channel/pullback "touch" or
// breakout "breakout") -- i.e. structurally qualified, not yet at the
// trigger price. These are sent/labeled distinctly and are never
// presented as trades, per explicit instruction.
// ============================================================

function v3PatternDisplayName(setupType) {
  if (setupType === "CHANNEL_BOUNCE_LONG") return "Channel bounce";
  if (setupType === "CHANNEL_BOUNCE_SHORT") return "Channel bounce (short)";
  if (setupType === "TREND_PULLBACK_LONG") return "Trend pullback / support reclaim";
  if (setupType === "BASE_BREAKOUT_LONG") return "Base breakout / volatility contraction";
  return setupType;
}

// The one gate that represents "has the trigger actually fired yet" per
// pattern type -- used to define "conditional watch" (every OTHER gate
// passes) vs. genuinely not-yet-qualified (something else also fails).
function v3TriggerGateKey(setupType) {
  if (setupType === "BASE_BREAKOUT_LONG") return "breakout";
  return "touch";
}

async function v3WriteImmutableCandidateRecord(dateET, result) {
  if (!result || !result.symbol || !result.setupType) return;
  await kvSet(`v3:swing:candidate:${dateET}:${result.symbol}:${result.setupType}`, {
    ...result,
    ...v3SessionDateFields(dateET, result),
    version: "swing_pattern_suite_v1",
  });
}

// Real setup-plan message, per explicit format. optionsInfo is the
// real v3VerifyOptionsEligibility() result for this symbol (fetched
// once per selected/watch candidate, not for every scanned symbol, to
// avoid ~369 unnecessary Alpaca options calls for candidates that were
// never going to be ranked in the top 2).
function v3BuildSwingSetupMessage(candidate, optionsInfo, statusMode) {
  const rr = candidate.riskReward != null ? candidate.riskReward.toFixed(1) : "n/a";
  const weeklyTrendLine = candidate.weeklyTrendBullish === true ? "bullish"
    : candidate.weeklyTrendBullish === false ? "not confirmed bullish"
    : "not checked by this pattern";
  const supportLevel = candidate.supportLevel ?? candidate.pullbackLevel ?? candidate.pivotPrice ?? null;
  const volRatio = candidate.volumeRatio != null ? candidate.volumeRatio.toFixed(1) : "n/a";
  const optionsLine = optionsInfo?.longDatedOptionsAvailable
    ? "long-dated availability confirmed"
    : optionsInfo?.hasListedOptions
      ? "listed options available, long-dated (6mo+) not confirmed"
      : "not confirmed available";

  // 2026-08-12 (Codex review FIX 2) -- exact labels per explicit
  // instruction, confirmed clearly distinct: actionable uses 🎯 SWING
  // SETUP (was 📈), watch uses 👀 WATCH — not yet triggered (was 👀
  // SWING WATCH). Symbol is kept in the header on both -- a Telegram
  // message with no symbol in its own header line isn't scannable in a
  // chat -- appended after the required label text, not replacing it.
  const isWatch = statusMode === "watch";
  const header = isWatch ? `👀 WATCH — not yet triggered — ${candidate.symbol}` : `🎯 SWING SETUP — ${candidate.symbol}`;
  const entryLabel = isWatch ? "Watch trigger (not yet confirmed)" : "Entry trigger";
  const statusLine = isWatch
    ? "Status: CONDITIONAL WATCH — trigger not yet confirmed. This is NOT a live trade."
    : "Status: actionable on confirmation";

  return `${header}
Setup: ${v3PatternDisplayName(candidate.setupType)}
Timeframe: Swing (days to weeks)

${entryLabel}: $${candidate.entryReference.toFixed(2)}
Invalidation / stop: $${candidate.stop.toFixed(2)}
Target 1: ${candidate.target1 != null ? "$" + candidate.target1.toFixed(2) : "n/a"}
Target 2: ${candidate.target2 != null ? "$" + candidate.target2.toFixed(2) : "n/a (no weekly level found beyond target 1)"}
Risk/reward: ${rr}:1

Why it qualifies${isWatch ? " so far" : ""}:
• Weekly trend: ${weeklyTrendLine}
• Daily support held: ${supportLevel != null ? "$" + supportLevel.toFixed(2) : "n/a"}
• Volume confirmation: ${volRatio}× median
• Pattern quality: ${candidate.eligible ? "verified" : "partial -- see watch caveat below"}
• Options: ${optionsLine}

${statusLine}
⚠️ Not financial advice`;
}

// 2026-08-12 (Codex review, critical fix) -- structured return at every
// exit point, same contract as runV3DataAgent/runV3ChannelScanner above.
async function runV3MasterSwingAgent(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3MasterSwingAgentDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  // 8:20-8:30am ET (moved from 4:45-4:55pm, 2026-08-11 Codex review
  // CHANGE 1) -- after Data Agent (8:00-8:10) and Channel Scanner
  // (8:15-8:25). Windows overlap 8:20-8:25 by design; the explicit
  // Scanner dependency check below (FIX 2, 2026-08-11) is what makes
  // that overlap safe -- Master will not proceed on a Scanner run that
  // hasn't actually finished yet, it just retries on a later tick still
  // within its own window.
  if (total < 500 || total >= 510) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 8:20-8:30am ET window" };

  // "ok" OR "degraded" -- degraded means some individual symbols were
  // excluded (e.g. a SIP/Yahoo data-integrity mismatch on one name) but
  // the majority of the universe is still valid; that's the system
  // working as designed, not bad data. Only "blocked" and
  // "market_closed_no_scan" represent genuinely unusable data for the
  // whole run -- those are what "rejects bad data" actually means here.
  const healthResult = await kvGet(`v3:data:health:${dateET}`);
  const health = healthResult.ok ? healthResult.value : null;
  const dataUsable = health && (health.status === "ok" || health.status === "degraded") && health.finalDailyBarVerified === true;
  if (!dataUsable) {
    console.log(`v3 MASTER SWING AGENT: rejecting bad/incomplete data (status=${health?.status}) — not scanning today.`);
    return { didWork: false, status: "blocked_dependency", skipReason: `Data Agent status=${health?.status ?? "missing"}, finalDailyBarVerified=${health?.finalDailyBarVerified ?? "missing"}` };
  }

  // FIX 2 (2026-08-11, Codex review) -- strict dependency chain: Data
  // Agent completed -> Scanner completed -> Master commits -> Report
  // sends. Reads Channel Scanner's own JOB MANIFEST (not its shadowlog
  // output -- the manifest is the thing that actually distinguishes
  // "ran and wrote real data" from "attempted, blocked, or never ran"),
  // and requires the SAME real completion signal Master's own manifest
  // uses (status==="completed" && didWork===true). Never proceeds on a
  // partial/incomplete/blocked Scanner run. This is what makes the
  // 8:20-8:25 window overlap between Scanner and Master safe -- without
  // it, Master could start scanning before Scanner has actually
  // finished writing today's data.
  const scannerManifestResult = await kvGet(`v3:jobs:channelScanner:${dateET}`);
  const scannerManifest = scannerManifestResult.ok ? scannerManifestResult.value : null;
  const scannerComplete = scannerManifest?.status === "completed" && scannerManifest?.didWork === true;
  if (!scannerComplete) {
    console.log(`v3 MASTER SWING AGENT: Channel Scanner not complete yet (status=${scannerManifest?.status}, didWork=${scannerManifest?.didWork}) — waiting. Will retry later in this window.`);
    return { didWork: false, status: "blocked_dependency", skipReason: `Channel Scanner not complete (status=${scannerManifest?.status ?? "missing"}, didWork=${scannerManifest?.didWork ?? "missing"})` };
  }

  // FIX 1 (2026-08-14, Codex review) -- switched to v2, even though the
  // instruction's own explicit function list didn't name this one:
  // runV3MasterSwingAgent hard-gates on v3:data:health:{date}, which
  // runV3DataAgent now computes against v2's 100 symbols only -- leaving
  // this function scanning v1's 123 would mean 23 symbols get scanned
  // here that were never actually health-checked, exactly the "mixing
  // v1 and v2 in the same pipeline" the instruction says never to do.
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols) || universe.symbols.length === 0) {
    console.error("v3 MASTER SWING AGENT: no v3:universe:swing:v2 found — v3BuildUniverseV2 must be run first.");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };
  }

  // FIX 1 -- claimed only now, after every retryable blocked_dependency
  // gate above has passed, so a legitimate "not ready yet" outcome never
  // consumes the claim and blocks a real later-tick retry this same
  // morning.
  if (!(await v3ClaimJobStart("masterSwingAgent", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };

  console.log("=== v3 MASTER SWING AGENT starting ===");
  const businessWorkStartedAt = new Date().toISOString();
  const startTime = Date.now();
  const allCandidates = [];
  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- pullback
  // and breakout only exist in this function (no separate new-pipeline
  // generator for them), so their outcome capture lives here. Channel
  // candidates ARE also re-evaluated in this loop (a pre-existing
  // duplicate of v3ChannelScannerCore's own channel scan, not something
  // this step introduces or fixes) -- deliberately NOT instrumented
  // here, to avoid two different scans writing conflicting outcome
  // records to the same v3:outcome:channel:{date}:{symbol} key;
  // v3ChannelScannerCore is the single source of truth for "channel".
  const stepOneSnapshots = await v2GetAlpacaSnapshotsForSymbols(universe.symbols);
  const evaluatedSymbols = new Set();

  for (const symbol of universe.symbols) {
    try {
      const sipResult = (await v3GetCompletedDailySipBars([symbol], 170))[symbol];
      if (!sipResult.ok || sipResult.dataIntegrityFailure || sipResult.barCount < 137) continue;
      evaluatedSymbols.add(symbol);
      const bars = sipResult.bars;
      const atrSeries = v3ATRSeries(bars, 14);
      const currentAtr = atrSeries[atrSeries.length - 1];
      if (currentAtr == null) continue;
      const weeklyBars = await v3GetWeeklyBarsSip(symbol, 400);
      const weeklyTrend = v3CheckWeeklyTrendBullish(weeklyBars);

      const { channel } = v3FindBestChannel(bars, currentAtr);
      if (channel && channel.direction === "ascending") {
        const r = await v3EvaluateChannelSetup(symbol, bars, channel, currentAtr);
        r.weeklyTrendBullish = weeklyTrend.bullish; // Master Agent's own additional gate, see header comment
        allCandidates.push(r);
        await v3WriteImmutableCandidateRecord(dateET, r);
      } else if (channel && channel.direction === "descending") {
        // Still evaluated + recorded (learning data), never ranked/sent -- long-only alert format.
        const r = await v3EvaluateChannelSetup(symbol, bars, channel, currentAtr);
        await v3WriteImmutableCandidateRecord(dateET, r);
      }

      const pullback = await v3EvaluateTrendPullback(symbol, bars, weeklyBars, currentAtr);
      allCandidates.push(pullback);
      await v3WriteImmutableCandidateRecord(dateET, pullback);

      const breakout = await v3EvaluateBaseBreakout(symbol, bars, weeklyBars, currentAtr);
      allCandidates.push(breakout);
      await v3WriteImmutableCandidateRecord(dateET, breakout);

      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      console.error(`v3 MASTER SWING AGENT: error for ${symbol} —`, e.message);
    }
  }

  // "Fully eligible" for Master Agent ranking = the pattern's own gates
  // passed AND (for patterns that don't check it internally) weekly
  // trend is bullish.
  const fullyEligible = allCandidates.filter((c) => c.eligible && c.weeklyTrendBullish !== false);

  const bestPerSymbolEligible = new Map();
  for (const c of fullyEligible) {
    const existing = bestPerSymbolEligible.get(c.symbol);
    if (!existing || (c.riskReward ?? 0) > (existing.riskReward ?? 0)) bestPerSymbolEligible.set(c.symbol, c);
  }
  const rankedEligible = [...bestPerSymbolEligible.values()].sort((a, b) => (b.riskReward ?? 0) - (a.riskReward ?? 0));
  const actionable = rankedEligible.slice(0, 2);

  let conditionalWatch = [];
  if (actionable.length < 2) {
    const remaining = 2 - actionable.length;
    const actionableSymbols = new Set(actionable.map((c) => c.symbol));
    const watchPool = allCandidates.filter((c) => {
      if (actionableSymbols.has(c.symbol)) return false;
      if (c.eligible) return false;
      if (c.weeklyTrendBullish === false) return false;
      if (!c.gates || c.riskReward == null) return false;
      const triggerKey = v3TriggerGateKey(c.setupType);
      if (c.gates[triggerKey] !== false) return false; // must specifically be the trigger that's missing
      return Object.entries(c.gates).every(([k, v]) => k === triggerKey || v === true);
    });
    const bestPerSymbolWatch = new Map();
    for (const c of watchPool) {
      const existing = bestPerSymbolWatch.get(c.symbol);
      if (!existing || (c.riskReward ?? 0) > (existing.riskReward ?? 0)) bestPerSymbolWatch.set(c.symbol, c);
    }
    conditionalWatch = [...bestPerSymbolWatch.values()].sort((a, b) => (b.riskReward ?? 0) - (a.riskReward ?? 0)).slice(0, remaining);
  }

  // 2026-08-11 (Codex review CHANGE 1/2) -- this function no longer
  // sends Telegram itself. It picks and records; runV3SwingLabMorningReport
  // (8:25-8:35am ET) reads v3:swing:masterSelections:{date} below, does
  // the real pre-market revalidation, and is the only place that
  // actually calls v3SendTelegram for a setup now. optionsInfo is kept
  // in the summary record (not re-fetched at send time) since long-dated
  // options availability doesn't meaningfully change over a 5-15 minute
  // gap; sentLive is still recorded here as a diagnostic ("would this
  // mode ever actually deliver") even though delivery itself now happens
  // downstream.
  const selections = [];
  for (const c of actionable) {
    const optionsInfo = await v3VerifyOptionsEligibility(c.symbol);
    selections.push({ ...c, statusMode: "actionable", optionsInfo, ...v3SessionDateFields(dateET, c) });
  }
  for (const c of conditionalWatch) {
    const optionsInfo = await v3VerifyOptionsEligibility(c.symbol);
    selections.push({ ...c, statusMode: "watch", optionsInfo, ...v3SessionDateFields(dateET, c) });
  }

  const scanDuration = Date.now() - startTime;
  await kvSet(`v3:swing:masterSelections:${dateET}`, {
    dateET,
    symbolsScanned: universe.symbols.length,
    candidatesEvaluated: allCandidates.length,
    fullyEligibleCount: fullyEligible.length,
    actionableCount: actionable.length,
    conditionalWatchCount: conditionalWatch.length,
    willDeliver: isSwingLiveAdminActive(),
    selections: selections.map((s) => ({
      symbol: s.symbol, setupType: s.setupType, patternLabel: s.patternLabel, statusMode: s.statusMode,
      riskReward: s.riskReward, entryReference: s.entryReference, stop: s.stop, target1: s.target1, target2: s.target2,
      weeklyTrendBullish: s.weeklyTrendBullish, supportLevel: s.supportLevel ?? null, pullbackLevel: s.pullbackLevel ?? null, pivotPrice: s.pivotPrice ?? null,
      volumeRatio: s.volumeRatio, eligible: s.eligible, optionsInfo: s.optionsInfo,
      asOfSessionDate: s.asOfSessionDate, deliveryDate: s.deliveryDate, patternFormedAt: s.patternFormedAt,
      // STEP 1 (2026-08-17) -- carried through so runV3SwingLabMorningReport
      // (a separate function call, reads this KV record fresh) can write
      // the true final outcome record once it knows whether this pick
      // actually got sent.
      gateResults: s.gateResults ?? null, failedGates: s.failedGates ?? null, lastGatePassed: s.lastGatePassed ?? null, barDate: s.barDate ?? null,
    })),
    scanDuration,
    completedAt: new Date().toISOString(),
  });

  console.log(`v3 MASTER SWING AGENT: complete — selected ${selections.length} setup(s) (${actionable.length} actionable, ${conditionalWatch.length} watch) for the 8:25am morning report to revalidate and ${isSwingLiveAdminActive() ? "send" : "log (shadow mode)"}.`);

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- pullback
  // and breakout outcome records for every symbol NOT going downstream
  // to runV3SwingLabMorningReport (that function writes the ~1-4
  // selected picks' true final record once it knows if they actually
  // sent). Channel-type candidates in allCandidates are skipped here
  // (see header comment above the loop). Symbols with no pullback/
  // breakout entry in allCandidates at all (early data-check continue)
  // get skipped_data for both engines.
  const selectedKeys = new Set(selections.map((s) => `${s.symbol}:${s.setupType}`));
  const pullbackSeen = new Set(), breakoutSeen = new Set();
  for (const c of allCandidates) {
    if (c.setupType !== "TREND_PULLBACK_LONG" && c.setupType !== "BASE_BREAKOUT_LONG") continue;
    const engine = c.setupType === "TREND_PULLBACK_LONG" ? "pullback" : "breakout";
    (engine === "pullback" ? pullbackSeen : breakoutSeen).add(c.symbol);
    if (selectedKeys.has(`${c.symbol}:${c.setupType}`)) continue; // downstream will write this one
    const { intradayMovePct, isMaterialMover } = v3MoveContextFromSnapshot(stepOneSnapshots[c.symbol]);
    const outcomeState = c.eligible ? "eligible_capped" : "rejected";
    await v3WriteOutcomeRecord(engine, dateET, c.symbol, outcomeState, {
      gateResults: c.gateResults ?? null, failedGates: c.failedGates ?? null, lastGatePassed: c.lastGatePassed ?? null,
      setup: c.eligible ? { direction: "bullish", entry: c.entryReference, stop: c.stop, target1: c.target1, target2: c.target2, riskReward: c.riskReward, dataTimestamp: c.barDate, ruleVersion: engine === "pullback" ? "trend_pullback_v1" : "base_breakout_v1" } : null,
      intradayMovePct, isMaterialMover,
    });
  }
  for (const symbol of universe.symbols) {
    const { intradayMovePct, isMaterialMover } = v3MoveContextFromSnapshot(stepOneSnapshots[symbol]);
    if (!pullbackSeen.has(symbol)) await v3WriteOutcomeRecord("pullback", dateET, symbol, "skipped_data", { intradayMovePct, isMaterialMover });
    if (!breakoutSeen.has(symbol)) await v3WriteOutcomeRecord("breakout", dateET, symbol, "skipped_data", { intradayMovePct, isMaterialMover });
  }

  v3MasterSwingAgentDone = true;
  const businessWorkCompletedAt = new Date().toISOString();
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt };
}

// ============================================================
// SWING LAB MORNING REPORT (2026-08-11, Codex review CHANGE 2/3) --
// 8:25-8:35am ET, after Master Swing Agent (8:20-8:30). Reads
// v3:swing:masterSelections:{date}, does a real pre-market revalidation
// against a fresh Alpaca quote for every ACTIONABLE pick (never
// substitutes a stale/missing quote as current price -- "fresh" means a
// real trade printed on TODAY's ET calendar date), and is now the ONLY
// place that sends a real setup message. Watch picks are not
// revalidated -- they were already conditional/not-a-trade before this
// step, per the original design; this step's revalidation logic is
// specifically about setups that would otherwise be sent as actionable.
// ============================================================

// Target1/target2 source labels per pattern, for the morning message
// template's "({source})" fields -- matches each detector's own real
// target formula (see v3EvaluateChannelSetup/v3EvaluateTrendPullback/
// v3EvaluateBaseBreakout above), not a generic placeholder.
function v3TargetSourceLabels(setupType) {
  if (setupType === "CHANNEL_BOUNCE_LONG") return { target1: "channel upper line", target2: "weekly resistance level" };
  if (setupType === "TREND_PULLBACK_LONG") return { target1: "recent swing high, 40-day", target2: "weekly resistance level" };
  if (setupType === "BASE_BREAKOUT_LONG") return { target1: "measured move (pivot + base height)", target2: "weekly resistance level" };
  return { target1: "n/a", target2: "n/a" };
}

// MORNING-SEND QUOTE-FRESHNESS RULE (2026-08-18, presentation/safety
// only -- no swing formula, gate, or threshold changed by this constant
// or the functions below it; it only governs WHEN/WHETHER an already-
// qualified setup is allowed to send). Explicit "fresh quote" definition:
//   1. Same ET trading day as "now" (unchanged from the prior check), AND
//   2. No older than V3_FRESH_QUOTE_MAX_AGE_MINUTES at the moment it's
//      evaluated.
// 15 minutes is an engineering data-freshness default sized to this
// job's own ~10-minute send window (8:25-8:35am ET) plus a small
// buffer -- NOT an independently sourced trading standard, disclosed
// per CLAUDE.md's threshold rule the same way this codebase already
// discloses its other uncited-but-reasonable operational timings (e.g.
// the 20s Telegram request timeout). This is a data-quality bar, not a
// trading criterion.
const V3_FRESH_QUOTE_MAX_AGE_MINUTES = 15;
function v3QuoteAgeMinutes(quote) {
  if (!quote?.timestamp) return null;
  return (Date.now() - quote.timestamp) / 60000;
}
// requireRegularSession=true (used by the post-open recheck) also
// requires the quote's own timestamp to be at/after 9:30am ET today --
// guards against a stale pre-market print left over from before the
// open being mistaken for genuine regular-session confirmation.
function v3IsFreshQuote(quote, dateET, requireRegularSession = false) {
  if (!quote?.timestamp) return false;
  if (v3TradingDateET(new Date(quote.timestamp)) !== dateET) return false;
  const ageMinutes = v3QuoteAgeMinutes(quote);
  if (ageMinutes == null || ageMinutes > V3_FRESH_QUOTE_MAX_AGE_MINUTES) return false;
  if (requireRegularSession) {
    const et = new Date(quote.timestamp).toLocaleString("en-US", { timeZone: "America/New_York", hour12: false, hour: "2-digit", minute: "2-digit" });
    const [h, m] = et.split(":").map(Number);
    if (h * 60 + m < 570) return false; // 9:30am ET
  }
  return true;
}

// Pre-market revalidation for one actionable pick (2026-08-11, Codex
// review CHANGE 2). The 3% gap figure was given directly in the
// instruction (not invented here); the >=2.0 recomputed R:R bar reuses
// the SAME standard every v3 pattern detector already requires -- no
// new/uncited threshold, per CLAUDE.md's THRESHOLD/CONDITION CHANGE RULE.
//
// MORNING-SEND QUOTE-FRESHNESS RULE (2026-08-18) -- the stale/missing-
// quote branch below used to return revalidationStatus:"valid" (send
// anyway, labeled "confirm after open"). It now returns "pending_quote"
// -- nothing sends from this pass; runV3SwingMorningQuoteRecheck
// (9:35-9:50am ET, after the open) re-evaluates using a fresh REGULAR-
// SESSION quote and either sends then or suppresses with a specific,
// logged reason. See that function for stages 2-4 of the new rule.
async function v3RevalidateMorningPick(pick) {
  const revalidatedAt = new Date().toISOString();
  let quote = null;
  let quoteFetchFailed = false;
  try {
    quote = await v2GetAlpacaLatestPrice(pick.symbol);
    if (quote == null) quoteFetchFailed = true;
  } catch (e) {
    console.error(`v3RevalidateMorningPick: quote fetch failed for ${pick.symbol} —`, e.message);
    quoteFetchFailed = true;
  }

  const todayET = v3TradingDateET();
  const quoteIsFresh = v3IsFreshQuote(quote, todayET, false);

  if (!quoteIsFresh) {
    return { revalidationStatus: "pending_quote", freshQuoteAvailable: false, currentPrice: null, gapPct: null, recomputedRiskReward: null, suppressionReason: "pending_quote", quoteFetchFailed, revalidatedAt };
  }

  const currentPrice = quote.price;
  const gapPct = pick.entryReference > 0 ? (currentPrice - pick.entryReference) / pick.entryReference : null;

  // All current pattern types in this pipeline are long-only
  // (CHANNEL_BOUNCE_LONG/TREND_PULLBACK_LONG/BASE_BREAKOUT_LONG) -- kept
  // explicit rather than hardcoded so a future short-side type doesn't
  // silently get the wrong comparison direction here.
  const isLong = !pick.setupType?.endsWith("_SHORT");

  const stoppedOut = isLong ? currentPrice <= pick.stop : currentPrice >= pick.stop;
  if (stoppedOut) {
    return { revalidationStatus: "suppressed", freshQuoteAvailable: true, currentPrice, gapPct, recomputedRiskReward: null, suppressionReason: `pre-market price $${currentPrice.toFixed(2)} already through stop $${pick.stop.toFixed(2)} before the open`, revalidatedAt };
  }

  const throughTarget1 = pick.target1 != null && (isLong ? currentPrice >= pick.target1 : currentPrice <= pick.target1);
  if (throughTarget1) {
    return { revalidationStatus: "suppressed", freshQuoteAvailable: true, currentPrice, gapPct, recomputedRiskReward: null, suppressionReason: `pre-market price $${currentPrice.toFixed(2)} already through target 1 $${pick.target1.toFixed(2)} before the open -- reward no longer available`, revalidatedAt };
  }

  if (gapPct != null && Math.abs(gapPct) > 0.03) {
    const risk = isLong ? currentPrice - pick.stop : pick.stop - currentPrice;
    const reward = pick.target1 != null ? (isLong ? pick.target1 - currentPrice : currentPrice - pick.target1) : null;
    const recomputedRiskReward = risk > 0 && reward != null && reward > 0 ? reward / risk : null;
    if (recomputedRiskReward == null || recomputedRiskReward < 2.0) {
      return { revalidationStatus: "conditional", freshQuoteAvailable: true, currentPrice, gapPct, recomputedRiskReward, suppressionReason: null, revalidatedAt };
    }
    return { revalidationStatus: "valid", freshQuoteAvailable: true, currentPrice, gapPct, recomputedRiskReward, suppressionReason: null, revalidatedAt, gapFlag: true };
  }

  return { revalidationStatus: "valid", freshQuoteAvailable: true, currentPrice, gapPct, recomputedRiskReward: null, suppressionReason: null, revalidatedAt };
}

// Real morning setup-plan message, per explicit format (2026-08-11).
function v3BuildMorningSwingMessage(pick, revalidation, dateET) {
  const sources = v3TargetSourceLabels(pick.setupType);
  const rr = pick.riskReward != null ? pick.riskReward.toFixed(1) : "n/a";
  const timeStr = new Date(revalidation.revalidatedAt).toLocaleTimeString("en-US", { timeZone: "America/New_York", hour: "numeric", minute: "2-digit" });

  // FIX 3 (2026-08-11, Codex review) -- exact wording per instruction.
  // Never shows "Valid at open: YES" without a fresh, verified
  // pre-market quote (freshQuoteAvailable===true is the only path to
  // that line), and never presents the prior-close price as if it were
  // a live pre-market quote -- the fallback line names it explicitly as
  // the CLOSE, not a current price, and is unambiguous that this is not
  // yet actionable.
  const premarketLine = revalidation.freshQuoteAvailable
    ? `Pre-market: $${revalidation.currentPrice.toFixed(2)} as of ${timeStr} ET ✅${revalidation.gapFlag ? ` (${(revalidation.gapPct * 100).toFixed(1)}% gap from formation close -- still valid, R:R re-checked)` : ""}`
    : `Plan based on ${pick.asOfSessionDate} close — pre-market quote unavailable`;

  const validLine = revalidation.freshQuoteAvailable ? "Valid at open: YES" : "Confirm entry after open — NOT valid at open";

  return `🎯 SWING SETUP — ${pick.symbol} — ${dateET}
Pattern: ${v3PatternDisplayName(pick.setupType)}
Formed: ${pick.asOfSessionDate}
${premarketLine}

Entry above: $${pick.entryReference.toFixed(2)}
Stop: $${pick.stop.toFixed(2)}
Target 1: ${pick.target1 != null ? "$" + pick.target1.toFixed(2) : "n/a"} (${sources.target1})
Target 2: ${pick.target2 != null ? "$" + pick.target2.toFixed(2) : "n/a"} (${sources.target2})
R:R: ${rr}:1
${validLine}
⚠️ Not financial advice`;
}

function v3BuildNoSetupMessage(dateET, reason) {
  // FIX 4 (2026-08-11, Codex review) -- Channel Scanner (the first real
  // step in the morning chain) actually starts at 8:15am ET, not 8:20am
  // (8:20am is Master Swing Agent's window) -- was pointing at the
  // wrong job's start time.
  return `📊 SWING LAB — ${dateET}
No qualified setup today.
Reason: ${reason}
Next scan: tomorrow morning 8:15am ET`;
}

async function runV3SwingLabMorningReport(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3SwingLabMorningReportDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  if (total < 505 || total >= 515) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 8:25-8:35am ET window" };

  const businessWorkStartedAt = new Date().toISOString();
  // FIX 2 (2026-08-11, Codex review) -- same strict-chain manifest check
  // as Master's own Scanner dependency: Report must not read a partial
  // Master run. Checks Master's JOB MANIFEST, not just presence of
  // masterSelections (belt-and-suspenders -- Master only ever writes
  // that key right before marking itself done, so this rarely
  // disagrees with the presence check, but the manifest is the actual
  // authoritative "did real work genuinely complete" signal).
  const masterManifestResult = await kvGet(`v3:jobs:masterSwingAgent:${dateET}`);
  const masterManifest = masterManifestResult.ok ? masterManifestResult.value : null;
  if (!(masterManifest?.status === "completed" && masterManifest?.didWork === true)) {
    console.log(`v3 SWING LAB MORNING REPORT: Master Swing Agent not complete yet (status=${masterManifest?.status}, didWork=${masterManifest?.didWork}) — waiting. Will retry later in this window.`);
    return { didWork: false, status: "blocked_dependency", skipReason: `Master Swing Agent not complete (status=${masterManifest?.status ?? "missing"}, didWork=${masterManifest?.didWork ?? "missing"})` };
  }
  const masterResult = await kvGet(`v3:swing:masterSelections:${dateET}`);
  const master = masterResult.ok ? masterResult.value : null;
  if (!master) {
    console.log("v3 SWING LAB MORNING REPORT: masterSelections missing despite a completed manifest -- treating as blocked.");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:swing:masterSelections:{date} missing despite Master Swing Agent manifest showing completed" };
  }
  // FIX 1 -- claimed after both retryable gates above.
  if (!(await v3ClaimJobStart("swingLabMorningReport", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };

  const selections = Array.isArray(master.selections) ? master.selections : [];
  const actionablePicks = selections.filter((s) => s.statusMode === "actionable");
  const watchPicks = selections.filter((s) => s.statusMode === "watch");
  const canSend = isSwingLiveAdminActive();
  const revalidatedRecords = [];
  let sentCount = 0;
  const newlyPending = [];
  // MORNING-SEND QUOTE-FRESHNESS RULE (2026-08-18) -- data-health
  // tracking, separate from the per-symbol pending_quote path below.
  // quoteCheckedCount/quoteFetchFailedCount distinguish "this specific
  // pick just doesn't have a fresh trade yet" (normal, expected some
  // mornings, thin pre-market liquidity) from "the quote SOURCE itself
  // is down" (every single fetch outright failing/returning nothing) --
  // only the latter raises an admin incident, so a quiet pre-market
  // morning can never look identical to a real Alpaca outage.
  let quoteCheckedCount = 0, quoteFetchFailedCount = 0;

  if (actionablePicks.length === 0 && watchPicks.length === 0) {
    // 2026-08-13 (Codex review) -- "no qualified setup" is now KV-only
    // for this pipeline too, matching the new Master Decision Agent's
    // behavior (v3RecordNoQualifiedSetup) -- never sent to Telegram.
    // Written unconditionally (not gated by canSend) so the admin
    // diagnostic is always available for review regardless of live-
    // admin status.
    await kvSet(`v3:swing:noSetup:${dateET}`, { dateET, message: v3BuildNoSetupMessage(dateET, "no valid channel/trend/breakout patterns qualified today"), telegramSent: false, recordedAt: new Date().toISOString() });
  } else {
    for (const pick of actionablePicks) {
      const revalidation = await v3RevalidateMorningPick(pick);
      revalidatedRecords.push({ ...pick, ...revalidation });
      // STEP 1 (2026-08-17) -- this pick's engine (skip channel-type
      // picks -- v3ChannelScannerCore is the single source of truth for
      // "channel" outcome capture, see runV3MasterSwingAgent's own
      // comment on why).
      const stepOneEngine = pick.setupType === "TREND_PULLBACK_LONG" ? "pullback" : pick.setupType === "BASE_BREAKOUT_LONG" ? "breakout" : null;
      const stepOneSetup = { direction: "bullish", entry: pick.entryReference, stop: pick.stop, target1: pick.target1, target2: pick.target2, riskReward: pick.riskReward, dataTimestamp: pick.barDate ?? null, ruleVersion: stepOneEngine === "pullback" ? "trend_pullback_v1" : "base_breakout_v1" };
      if (revalidation.revalidationStatus === "suppressed") {
        console.log(`v3 SWING LAB MORNING REPORT: suppressed ${pick.symbol} ${pick.setupType} — ${revalidation.suppressionReason}`);
        // Passed every real gate upstream, suppressed here by a live
        // pipeline check (pre-market gap/revalidation) -- not a shadow
        // lock, so eligible_capped, same bucket as losing the ranking.
        if (stepOneEngine) await v3WriteOutcomeRecord(stepOneEngine, dateET, pick.symbol, "eligible_capped", { gateResults: pick.gateResults, failedGates: pick.failedGates, lastGatePassed: pick.lastGatePassed, setup: stepOneSetup });
        continue;
      }
      // MORNING-SEND QUOTE-FRESHNESS RULE (2026-08-18) -- rules 1+2: no
      // fresh pre-market quote by this window's deadline -> hold
      // internally as pending_quote, send NOTHING, recheck after the
      // open (runV3SwingMorningQuoteRecheck). Not counted as
      // eligible_capped for STEP 1 purposes -- this pick hasn't been
      // resolved one way or the other yet, capped/sent get decided by
      // the recheck.
      quoteCheckedCount++;
      if (revalidation.quoteFetchFailed) quoteFetchFailedCount++;
      if (revalidation.revalidationStatus === "pending_quote") {
        console.log(`v3 SWING LAB MORNING REPORT: ${pick.symbol} ${pick.setupType} held as pending_quote -- no fresh pre-market quote by the 8:35am deadline.`);
        await kvSet(`v3:swing:pendingQuote:${dateET}:${pick.symbol}:${pick.setupType}`, {
          dateET, symbol: pick.symbol, setupType: pick.setupType, statusMode: "actionable",
          pick, reason: "pending_quote", heldAt: new Date().toISOString(), resolved: false,
        });
        // No KV LIST/SCAN primitive in this codebase (established
        // pattern -- see v3:master:scanIdsToday:{date} for the same
        // index-alongside-the-record approach) -- this index is how
        // runV3SwingMorningQuoteRecheck finds today's pending picks
        // without needing to enumerate keys.
        const indexResult = await kvGet(`v3:swing:pendingQuoteIndex:${dateET}`);
        const index = indexResult.ok && Array.isArray(indexResult.value) ? indexResult.value : [];
        index.push({ symbol: pick.symbol, setupType: pick.setupType });
        await kvSet(`v3:swing:pendingQuoteIndex:${dateET}`, index);
        continue;
      }
      const message = revalidation.revalidationStatus === "conditional"
        ? v3BuildSwingSetupMessage(pick, pick.optionsInfo, "watch") + `\n\n(Downgraded from actionable: pre-market gap ${(revalidation.gapPct * 100).toFixed(1)}% dropped recomputed R:R to ${revalidation.recomputedRiskReward != null ? revalidation.recomputedRiskReward.toFixed(1) : "n/a"}:1)`
        : v3BuildMorningSwingMessage(pick, revalidation, dateET);
      let stepOneSent = false;
      if (canSend) {
        const sent = await v3SendTelegram(message, "runV3SwingLabMorningReport");
        if (sent) {
          stepOneSent = true;
          sentCount++;
          const effectiveStatusMode = revalidation.revalidationStatus === "conditional" ? "watch" : "actionable";
          await kvSet(`v3:swing:sentAlert:${dateET}:${pick.symbol}:${pick.setupType}`, {
            symbol: pick.symbol, setupType: pick.setupType, statusMode: effectiveStatusMode,
            entryReference: pick.entryReference, stop: pick.stop, target1: pick.target1, target2: pick.target2,
            riskReward: pick.riskReward, sentAt: new Date().toISOString(), dateET, graded: false,
            asOfSessionDate: pick.asOfSessionDate, deliveryDate: pick.deliveryDate, patternFormedAt: pick.patternFormedAt,
            deliveredAt: new Date().toISOString(), revalidatedAt: revalidation.revalidatedAt,
            revalidationStatus: revalidation.revalidationStatus, suppressionReason: revalidation.suppressionReason,
          });
          // Only genuinely-actionable (not downgraded) sends get graded
          // against target/stop -- same "watch is never a confirmed
          // entry" rule the original design already established.
          if (effectiveStatusMode === "actionable") newlyPending.push({ dateET, symbol: pick.symbol, setupType: pick.setupType });
        }
      }
      if (stepOneEngine) await v3WriteOutcomeRecord(stepOneEngine, dateET, pick.symbol, stepOneSent ? "sent" : (canSend ? "eligible_capped" : "eligible_shadow_blocked"), { gateResults: pick.gateResults, failedGates: pick.failedGates, lastGatePassed: pick.lastGatePassed, setup: stepOneSetup });
    }
    // MORNING-SEND QUOTE-FRESHNESS RULE (2026-08-18) -- data-health
    // guardrail. Every single quote fetch failing outright (not just
    // being stale) across every pick checked this morning is the signal
    // that the quote SOURCE itself is down, not that these specific
    // names lack pre-market prints -- raises one real admin incident
    // instead of silently holding everything as pending_quote, which
    // would look identical to a normal quiet morning otherwise.
    if (quoteCheckedCount > 0 && quoteFetchFailedCount === quoteCheckedCount) {
      const claim = await kvSetNX(`v3:swing:quoteOutageIncident:${dateET}`, { sentAt: new Date().toISOString(), quoteCheckedCount }, 86400);
      if (claim.acquired) {
        await v3SendTelegram(`⚠️ SWING MORNING QUOTE OUTAGE — ${dateET}\n${quoteCheckedCount}/${quoteCheckedCount} pre-market quote fetches failed outright (not just stale) — Alpaca latest-trade endpoint may be down.\nAll actionable picks held as pending_quote; will retry with a regular-session quote after the open.`, "runV3SwingLabMorningReport");
      }
    }
    for (const pick of watchPicks) {
      revalidatedRecords.push({ ...pick, revalidationStatus: "not_applicable_watch", revalidatedAt: new Date().toISOString() });
      const stepOneEngine = pick.setupType === "TREND_PULLBACK_LONG" ? "pullback" : pick.setupType === "BASE_BREAKOUT_LONG" ? "breakout" : null;
      let stepOneSent = false;
      if (canSend) {
        const sent = await v3SendTelegram(v3BuildSwingSetupMessage(pick, pick.optionsInfo, "watch"), "runV3SwingLabMorningReport");
        if (sent) {
          stepOneSent = true;
          sentCount++;
          await kvSet(`v3:swing:sentAlert:${dateET}:${pick.symbol}:${pick.setupType}`, {
            symbol: pick.symbol, setupType: pick.setupType, statusMode: "watch",
            entryReference: pick.entryReference, stop: pick.stop, target1: pick.target1, target2: pick.target2,
            riskReward: pick.riskReward, sentAt: new Date().toISOString(), dateET, graded: false,
            asOfSessionDate: pick.asOfSessionDate, deliveryDate: pick.deliveryDate, patternFormedAt: pick.patternFormedAt,
            deliveredAt: new Date().toISOString(), revalidatedAt: new Date().toISOString(),
            revalidationStatus: "not_applicable_watch", suppressionReason: null,
          });
        }
      }
      // Watch picks are never eligible=true by construction (the
      // watchPool filter in runV3MasterSwingAgent explicitly excludes
      // already-eligible candidates -- they're missing exactly the
      // trigger gate) -- so outside of an actual send, "rejected" is the
      // honest state, not eligible_capped/shadow_blocked (those imply
      // "passed every gate").
      if (stepOneEngine) await v3WriteOutcomeRecord(stepOneEngine, dateET, pick.symbol, stepOneSent ? "sent" : "rejected", { gateResults: pick.gateResults, failedGates: pick.failedGates, lastGatePassed: pick.lastGatePassed, setup: stepOneSent ? { direction: "bullish", entry: pick.entryReference, stop: pick.stop, target1: pick.target1, target2: pick.target2, riskReward: pick.riskReward, dataTimestamp: pick.barDate ?? null, ruleVersion: stepOneEngine === "pullback" ? "trend_pullback_v1" : "base_breakout_v1" } : null });
    }
    // Every actionable pick got suppressed and nothing else qualified --
    // 2026-08-13 (Codex review) -- KV-only here too, same as the other
    // no-setup path above; never sent to Telegram. Unconditional (not
    // gated by canSend), and no longer counted toward sentCount since
    // nothing was actually sent.
    if (sentCount === 0) {
      await kvSet(`v3:swing:noSetup:${dateET}`, { dateET, message: v3BuildNoSetupMessage(dateET, "setups invalidated overnight (pre-market gap or already through stop/target before the open)"), telegramSent: false, recordedAt: new Date().toISOString() });
    }
  }

  if (newlyPending.length > 0) {
    const existingIndexResult = await kvGet("v3:swing:pendingGradeIndex");
    const existingIndex = existingIndexResult.ok && Array.isArray(existingIndexResult.value) ? existingIndexResult.value : [];
    await kvSet("v3:swing:pendingGradeIndex", existingIndex.concat(newlyPending));
  }

  await kvSet(`v3:swing:morningReport:${dateET}`, {
    dateET, actionableCount: actionablePicks.length, watchCount: watchPicks.length, sentCount,
    canSend, revalidations: revalidatedRecords.map((r) => ({ symbol: r.symbol, setupType: r.setupType, revalidationStatus: r.revalidationStatus, currentPrice: r.currentPrice ?? null, gapPct: r.gapPct ?? null, suppressionReason: r.suppressionReason ?? null })),
    completedAt: new Date().toISOString(),
  });

  console.log(`v3 SWING LAB MORNING REPORT: complete — ${actionablePicks.length} actionable, ${watchPicks.length} watch, sent=${sentCount}, canSend=${canSend}.`);

  v3SwingLabMorningReportDone = true;
  const businessWorkCompletedAt = new Date().toISOString();
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt };
}

// MORNING-SEND QUOTE-FRESHNESS RULE (2026-08-18) -- stages 3+4: rechecks
// every pick still held pending_quote from this morning's 8:25-8:35am
// pass, using a fresh REGULAR-SESSION quote (v3IsFreshQuote with
// requireRegularSession=true -- must be timestamped at/after 9:30am ET,
// not a stale pre-market print). Sends THEN (full "SWING SETUP", same
// message builder as the normal path) only if price hasn't already
// crossed entry, stop, or target1; otherwise suppresses with an exact,
// logged reason. No swing formula/gate/threshold touched here -- same
// stop/target1 crossing checks and the same 3%-gap/2.0-R:R figures
// v3RevalidateMorningPick already used, reused rather than reinvented.
async function runV3SwingMorningQuoteRecheck(dateET) {
  const indexResult = await kvGet(`v3:swing:pendingQuoteIndex:${dateET}`);
  const index = indexResult.ok && Array.isArray(indexResult.value) ? indexResult.value : [];
  if (index.length === 0) return { didWork: true, status: "completed", skipReason: null, checked: 0, sent: 0, suppressed: 0, stillPending: 0 };

  const canSend = isSwingLiveAdminActive();
  let sentCount = 0, suppressedCount = 0, stillPendingCount = 0;
  let quoteCheckedCount = 0, quoteFetchFailedCount = 0;

  for (const ref of index) {
    const pendingResult = await kvGet(`v3:swing:pendingQuote:${dateET}:${ref.symbol}:${ref.setupType}`);
    const pending = pendingResult.ok ? pendingResult.value : null;
    if (!pending || pending.resolved) continue; // already handled by an earlier tick this same window
    const pick = pending.pick;

    let quote = null, quoteFetchFailed = false;
    try {
      quote = await v2GetAlpacaLatestPrice(pick.symbol);
      if (quote == null) quoteFetchFailed = true;
    } catch (e) {
      console.error(`runV3SwingMorningQuoteRecheck: quote fetch failed for ${pick.symbol} —`, e.message);
      quoteFetchFailed = true;
    }
    quoteCheckedCount++;
    if (quoteFetchFailed) quoteFetchFailedCount++;

    const isFresh = v3IsFreshQuote(quote, dateET, true);
    if (!isFresh) {
      stillPendingCount++;
      continue; // leave it pending -- resolved stays false, next tick in this window retries
    }

    const isLong = !pick.setupType?.endsWith("_SHORT");
    const currentPrice = quote.price;
    const revalidatedAt = new Date().toISOString();
    let outcome = null, reason = null;

    const stoppedOut = isLong ? currentPrice <= pick.stop : currentPrice >= pick.stop;
    const throughTarget1 = pick.target1 != null && (isLong ? currentPrice >= pick.target1 : currentPrice <= pick.target1);
    const gapPct = pick.entryReference > 0 ? (currentPrice - pick.entryReference) / pick.entryReference : null;
    // Same 3% gap figure v3RevalidateMorningPick already uses -- reused,
    // not a new threshold. Only fires the "gapped_through_entry" reason
    // when the gap ALSO breaks the setup's own >=2.0 R:R requirement
    // (same standard every v3 pattern already requires), so a small,
    // harmless gap that keeps R:R intact doesn't wrongly suppress.
    let recomputedRiskReward = null;
    if (gapPct != null && Math.abs(gapPct) > 0.03) {
      const risk = isLong ? currentPrice - pick.stop : pick.stop - currentPrice;
      const reward = pick.target1 != null ? (isLong ? pick.target1 - currentPrice : currentPrice - pick.target1) : null;
      recomputedRiskReward = risk > 0 && reward != null && reward > 0 ? reward / risk : null;
    }
    const gappedThroughEntry = gapPct != null && Math.abs(gapPct) > 0.03 && (recomputedRiskReward == null || recomputedRiskReward < 2.0);

    if (stoppedOut) { outcome = "suppressed"; reason = "gapped_through_stop"; }
    else if (throughTarget1) { outcome = "suppressed"; reason = "gapped_through_target1"; }
    else if (gappedThroughEntry) { outcome = "suppressed"; reason = "gapped_through_entry"; }
    else { outcome = "sent"; }

    if (outcome === "suppressed") {
      suppressedCount++;
      console.log(`v3 SWING MORNING QUOTE RECHECK: suppressed ${pick.symbol} ${pick.setupType} — ${reason} (post-open price $${currentPrice.toFixed(2)})`);
    } else {
      const revalidation = { revalidationStatus: "valid", freshQuoteAvailable: true, currentPrice, gapPct, recomputedRiskReward, suppressionReason: null, revalidatedAt };
      const message = v3BuildMorningSwingMessage(pick, revalidation, dateET);
      let sent = false;
      if (canSend) sent = await v3SendTelegram(message, "runV3SwingMorningQuoteRecheck");
      if (sent) {
        sentCount++;
        await kvSet(`v3:swing:sentAlert:${dateET}:${pick.symbol}:${pick.setupType}`, {
          symbol: pick.symbol, setupType: pick.setupType, statusMode: "actionable",
          entryReference: pick.entryReference, stop: pick.stop, target1: pick.target1, target2: pick.target2,
          riskReward: pick.riskReward, sentAt: new Date().toISOString(), dateET, graded: false,
          asOfSessionDate: pick.asOfSessionDate, deliveryDate: pick.deliveryDate, patternFormedAt: pick.patternFormedAt,
          deliveredAt: new Date().toISOString(), revalidatedAt, revalidationStatus: "valid_post_open_recheck", suppressionReason: null,
        });
        const existingIndexResult = await kvGet("v3:swing:pendingGradeIndex");
        const existingIndex = existingIndexResult.ok && Array.isArray(existingIndexResult.value) ? existingIndexResult.value : [];
        await kvSet("v3:swing:pendingGradeIndex", existingIndex.concat([{ dateET, symbol: pick.symbol, setupType: pick.setupType }]));
      } else {
        outcome = "suppressed"; reason = "canSend_false_or_send_failed"; suppressedCount++;
      }
    }

    // Rule 4 -- admin diagnostics only, one record per pick, whatever
    // the final outcome. Never a Telegram send by itself.
    await kvSet(`v3:swing:morningQuoteDiagnostic:${dateET}:${pick.symbol}:${pick.setupType}`, {
      dateET, symbol: pick.symbol, setupType: pick.setupType, outcome, reason,
      currentPrice, gapPct, recomputedRiskReward, checkedAt: revalidatedAt,
    });
    // STEP 1 (System vs. Market) -- resolve the outcome record this
    // pick's original stage-1 pass deliberately deferred (see the
    // pending_quote continue in runV3SwingLabMorningReport).
    const stepOneEngine = pick.setupType === "TREND_PULLBACK_LONG" ? "pullback" : pick.setupType === "BASE_BREAKOUT_LONG" ? "breakout" : null;
    if (stepOneEngine) {
      const stepOneState = outcome === "sent" ? "sent" : (canSend ? "eligible_capped" : "eligible_shadow_blocked");
      await v3WriteOutcomeRecord(stepOneEngine, dateET, pick.symbol, stepOneState, {
        gateResults: pick.gateResults, failedGates: pick.failedGates, lastGatePassed: pick.lastGatePassed,
        setup: { direction: "bullish", entry: pick.entryReference, stop: pick.stop, target1: pick.target1, target2: pick.target2, riskReward: pick.riskReward, dataTimestamp: pick.barDate ?? null, ruleVersion: stepOneEngine === "pullback" ? "trend_pullback_v1" : "base_breakout_v1" },
      });
    }

    await kvSet(`v3:swing:pendingQuote:${dateET}:${pick.symbol}:${pick.setupType}`, { ...pending, resolved: true, resolvedAt: revalidatedAt, outcome, reason });
  }

  // Same data-health guardrail as stage 1 -- every quote fetch failing
  // outright (not just still-not-fresh) across everything checked this
  // recheck pass is the quote-SOURCE-down signal, not "these are just
  // thin post-open prints" (which would be unusual right after the open
  // for this universe's liquid names, but isFresh failing for a
  // present-but-stale reason is handled separately as stillPending,
  // never counted here).
  if (quoteCheckedCount > 0 && quoteFetchFailedCount === quoteCheckedCount) {
    const claim = await kvSetNX(`v3:swing:quoteOutageIncident:${dateET}:recheck`, { sentAt: new Date().toISOString(), quoteCheckedCount }, 86400);
    if (claim.acquired) {
      await v3SendTelegram(`⚠️ SWING MORNING QUOTE OUTAGE (post-open recheck) — ${dateET}\n${quoteCheckedCount}/${quoteCheckedCount} regular-session quote fetches failed outright — Alpaca latest-trade endpoint may still be down.\n${stillPendingCount} pick(s) still held as pending_quote.`, "runV3SwingMorningQuoteRecheck");
    }
  }

  await kvSet(`v3:swing:quoteRecheck:${dateET}`, {
    dateET, checked: index.length, sent: sentCount, suppressed: suppressedCount, stillPending: stillPendingCount,
    completedAt: new Date().toISOString(),
  });
  console.log(`v3 SWING MORNING QUOTE RECHECK: complete — checked=${index.length}, sent=${sentCount}, suppressed=${suppressedCount}, stillPending=${stillPendingCount}.`);
  return { didWork: true, status: "completed", skipReason: null, checked: index.length, sent: sentCount, suppressed: suppressedCount, stillPending: stillPendingCount };
}

let v3SwingMorningQuoteRecheckDone = false;
async function runV3SwingMorningQuoteRecheckJob(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3SwingMorningQuoteRecheckDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  // 9:35-9:50am ET -- opens 5 min after the 9:30 bell (gives the first
  // real regular-session prints a moment to exist at all), stays open
  // 15 min so a missed tick or two doesn't lose the whole recheck the
  // way the old single-10-min-window pattern could (same reasoning as
  // this session's earlier durable-scheduling work).
  if (total < 575 || total >= 590) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 9:35-9:50am ET window" };
  if (!(await v3ClaimJobStart("swingMorningQuoteRecheck", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };
  const businessWorkStartedAt = new Date().toISOString();
  const result = await runV3SwingMorningQuoteRecheck(dateET);
  v3SwingMorningQuoteRecheckDone = true;
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt: new Date().toISOString() };
}

// ============================================================
// QUALITY AGENT (2026-08-10) -- grades every REAL sent setup against
// subsequent price action. Reads v3:swing:sentAlert:* records (written
// only for real swing_live_admin sends, never shadow selections).
// Grading horizon: up to 20 trading days per setup, checked once daily
// until a setup resolves (hits target1, hits stop, or expires
// unresolved past the horizon) or is already graded=true (skipped).
// NEVER changes any threshold/rule automatically -- purely reports,
// same "propose/report only, never auto-deploy" boundary this project
// already established for LEAP/SWING/DAILY's self-improvement systems.
// ============================================================
// 2026-08-12 (Codex review, critical fix) -- structured return at every
// exit point, same contract as the other v3 jobs above. "Nothing
// pending to grade" is treated as didWork:true/status:"completed" --
// the agent genuinely ran and checked, it's not a skip; there's just
// nothing to report.
async function runV3QualityAgent(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3QualityAgentDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  if (total < 1095 || total >= 1105) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 6:15-6:25pm ET window" }; // 6:15-6:25pm ET, after the 6:00-6:10pm Swing Lab report
  if (!(await v3ClaimJobStart("qualityAgent", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };

  console.log("=== v3 QUALITY AGENT starting ===");
  const businessWorkStartedAt = new Date().toISOString();

  // OUTSIDE UNIVERSE TRACKING (2026-08-12, Codex review) -- checked
  // regardless of whether there's anything pending to grade below (real
  // coverage-loss information shouldn't be silently skipped just
  // because no setup happened to fire that day). Reads the reserve list
  // v3BuildUniverseV2 writes (v3:universe:swing:v2:reserve, the bottom
  // 23 of the 123-symbol universe by 20-session median dollar volume)
  // -- skips gracefully (empty list, not an error) if v2 hasn't been
  // built yet, since v1 is still the only universe actually wired into
  // the live scanners. Uses completed SIP daily bars (never a raw
  // intraday snapshot's latestTrade) -- by 6:15pm ET today's daily bar
  // is already final, and every other v3 function already standardizes
  // on this same source for exactly that reason.
  const outsideUniverseMoves = [];
  const reserveResult = await kvGet("v3:universe:swing:v2:reserve");
  const reserveSymbols = reserveResult.ok && Array.isArray(reserveResult.value?.symbols) ? reserveResult.value.symbols.map((r) => r.symbol) : [];
  for (const symbol of reserveSymbols) {
    try {
      const sipResult = (await v3GetCompletedDailySipBars([symbol], 10))[symbol];
      if (!sipResult.ok || sipResult.barCount < 2) continue;
      const bars = sipResult.bars;
      const today = bars[bars.length - 1];
      const prior = bars[bars.length - 2];
      if (!today || !prior || prior.c <= 0) continue;
      const percentMove = (today.c - prior.c) / prior.c;
      if (Math.abs(percentMove) > 0.05) {
        const record = {
          symbol,
          percentMove: Math.round(percentMove * 100000) / 1000,
          dollarMove: Math.round((today.c - prior.c) * 100) / 100,
          universeVersion: "v2",
          note: "outside_active_universe",
        };
        await kvSet(`v3:outside_universe:${dateET}:${symbol}`, record);
        outsideUniverseMoves.push(record);
      }
      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      console.error(`v3 QUALITY AGENT: outside-universe check failed for ${symbol} —`, e.message);
    }
  }
  if (reserveSymbols.length > 0) console.log(`v3 QUALITY AGENT: outside-universe check complete — ${reserveSymbols.length} reserve symbols checked, ${outsideUniverseMoves.length} moved >5%.`);

  // No KV LIST/SCAN primitive is available through this file's minimal
  // REST-based kv helpers (kvGet/kvSet/kvSetNX only) -- so rather than
  // trying to enumerate all historical v3:swing:sentAlert:* keys blindly,
  // this agent maintains its own small rolling index of "sent, not yet
  // fully graded" setups, appended to whenever the Master Agent sends a
  // real alert, and consulted (and pruned) here.
  const indexResult = await kvGet("v3:swing:pendingGradeIndex");
  const pending = indexResult.ok && Array.isArray(indexResult.value) ? indexResult.value : [];

  if (pending.length === 0) {
    console.log("v3 QUALITY AGENT: no pending sent setups to grade.");
    if (outsideUniverseMoves.length > 0) {
      const lines = outsideUniverseMoves.map((m) => `${m.symbol}: ${m.percentMove > 0 ? "+" : ""}${m.percentMove}% ($${m.dollarMove > 0 ? "+" : ""}${m.dollarMove})`).join("\n");
      await v3SendTelegram(`📊 SWING QUALITY REPORT — ${dateET}\n\nNo setups graded today.\n\nCoverage loss — reserve-list symbols that moved >5% outside the active universe:\n${lines}\n\nThis is a report only — no rules or thresholds are changed automatically.\n⚠️ Not financial advice`, "runV3QualityAgent", "system.qualitySummary", "SUMMARY");
    }
    v3QualityAgentDone = true;
    return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt: new Date().toISOString() };
  }

  const stillPending = [];
  const gradedToday = [];

  for (const entry of pending) {
    try {
      const key = `v3:swing:sentAlert:${entry.dateET}:${entry.symbol}:${entry.setupType}`;
      const alertResult = await kvGet(key);
      const alert = alertResult.ok ? alertResult.value : null;
      if (!alert || alert.graded) continue; // already graded or gone -- drop from pending

      const sipResult = (await v3GetCompletedDailySipBars([entry.symbol], 60))[entry.symbol];
      if (!sipResult.ok) { stillPending.push(entry); continue; }
      const barsSinceSend = sipResult.bars.filter((b) => v3BarDateStr(b) > entry.dateET);
      const tradingDaysSinceSend = barsSinceSend.length;

      let outcome = "pending";
      let resolvedAt = null;
      for (const b of barsSinceSend) {
        const hitTarget = alert.target1 != null && b.h >= alert.target1;
        const hitStop = b.l <= alert.stop;
        // Conservative: if both could have been hit the same bar, count
        // the stop first (can't know real intraday sequencing from a
        // daily bar) -- a disclosed, deliberately conservative tie-break.
        if (hitStop) { outcome = "stopped_out"; resolvedAt = v3BarDateStr(b); break; }
        if (hitTarget) { outcome = "hit_target1"; resolvedAt = v3BarDateStr(b); break; }
      }
      if (outcome === "pending" && tradingDaysSinceSend >= 20) outcome = "expired_unresolved_20d";

      if (outcome !== "pending") {
        await kvSet(key, { ...alert, graded: true, outcome, resolvedAt, gradedAt: new Date().toISOString() });
        gradedToday.push({ symbol: entry.symbol, setupType: entry.setupType, outcome, riskReward: alert.riskReward });
      } else {
        stillPending.push(entry);
      }
      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      console.error(`v3 QUALITY AGENT: error grading ${entry.symbol} —`, e.message);
      stillPending.push(entry);
    }
  }

  await kvSet("v3:swing:pendingGradeIndex", stillPending);

  if (gradedToday.length > 0 || outsideUniverseMoves.length > 0) {
    const wins = gradedToday.filter((g) => g.outcome === "hit_target1").length;
    const losses = gradedToday.filter((g) => g.outcome === "stopped_out").length;
    const expired = gradedToday.filter((g) => g.outcome === "expired_unresolved_20d").length;
    const lines = gradedToday.map((g) => `${g.symbol} (${g.setupType}) — ${g.outcome.replace(/_/g, " ")}`).join("\n");
    const gradedSection = gradedToday.length > 0
      ? `Setups graded today: ${gradedToday.length}\nHit target 1: ${wins}\nStopped out: ${losses}\nExpired unresolved (20d): ${expired}\n\n${lines}`
      : "No setups graded today.";
    const coverageSection = outsideUniverseMoves.length > 0
      ? `\n\nCoverage loss — reserve-list symbols that moved >5% outside the active universe:\n${outsideUniverseMoves.map((m) => `${m.symbol}: ${m.percentMove > 0 ? "+" : ""}${m.percentMove}% ($${m.dollarMove > 0 ? "+" : ""}${m.dollarMove})`).join("\n")}`
      : "";
    const message = `📊 SWING QUALITY REPORT — ${dateET}

${gradedSection}${coverageSection}

This is a report only — no rules or thresholds are changed automatically.
⚠️ Not financial advice`;
    await v3SendTelegram(message, "runV3QualityAgent", "system.qualitySummary", "SUMMARY");
  }

  v3QualityAgentDone = true;
  console.log(`v3 QUALITY AGENT: complete — graded ${gradedToday.length}, still pending ${stillPending.length}.`);
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt: new Date().toISOString() };
}

// ============================================================
// MASTER DECISION AGENT (2026-08-12) -- unifies morning swing selection
// and a NEW intraday 1-hour momentum engine under one hard-gate +
// scoring framework, per explicit 4-correction instruction. Runs
// ALONGSIDE the existing masterSwingAgent/swingLabMorningReport
// pipeline, which is untouched and stays live exactly as it is today --
// this entire new system starts in SHADOW MODE and never sends a real
// Telegram message until manually promoted, regardless of FLEXAI_MODE.
// ============================================================

// SHADOW MODE -- gates ALL real sends from this system, independent of
// FLEXAI_MODE/isSwingLiveAdminActive(). Read fresh from KV every call
// (never cached) so promotion is a single KV write, not a redeploy.
// Defaults to "stage1_mechanics". Per explicit instruction, "member-
// facing activation" requires Stage 1 (3 sessions, mechanics only) AND
// Stage 2 (10+ sessions, 20+ momentum candidates, quality review) to
// complete AND be reviewed by a human -- this function never
// auto-advances the stage on elapsed time or session count; only a
// manual kvSet("v3:master:shadowStage", ...) does. Note: this whole v3
// system already only ever sends to the admin-only Swing Lab chat,
// never a real subscriber-facing channel (see CLAUDE.md) -- no
// subscriber bridge exists for this system at all, so true "member-
// facing" activation is out of this build's scope entirely; "live" here
// only ever means "sends to Swing Lab like everything else in v3 does."
async function v3GetMasterDecisionShadowStage() {
  const result = await kvGet("v3:master:shadowStage");
  return result.ok && typeof result.value === "string" ? result.value : "stage1_mechanics";
}

// ---- CORRECTION 1 -- immutable, scan-id'd KV keys that never
// overwrite. Every engine writes exactly one outcome per symbol per
// scan (eligible / rejected-with-all-reasons / skipped_data-with-exact-
// failed-input) -- no symbol may silently disappear.
function v3MasterDecisionScanId() {
  return new Date().toISOString().replace(/[:.]/g, "-");
}
// KV-BLOAT FIX (2026-09-09) -- confirmed via grep: zero reads of
// v3:signals:* anywhere in either repo (this key shape requires already
// knowing the exact barCloseTimestamp to look up, so nothing in this
// codebase actually does). Same 7-day retention as v3:jobs:attempt,
// same reasoning -- diagnostic trail, not the graded track record. This
// single pattern (momentum30m + masterMorning + masterMomentum
// combined) was 39,074 + 7,292 = 46,366 of the ~289,000 keys found via
// a real SCAN of the store.
const V3_SIGNALS_TTL_SECONDS = 7 * 24 * 60 * 60;
async function v3WriteSignal(engine, deliveryDate, symbol, direction, barCloseTimestamp, outcome) {
  const safeTimestamp = String(barCloseTimestamp).replace(/[:.]/g, "-");
  const key = `v3:signals:${engine}:${deliveryDate}:${symbol}:${direction}:${safeTimestamp}`;
  await kvSetEx(key, outcome, V3_SIGNALS_TTL_SECONDS);
  return key;
}
async function v3WriteScanRecord(engine, deliveryDate, scanId, summary) {
  const key = `v3:scans:${engine}:${deliveryDate}:${scanId}`;
  await kvSet(key, summary);
  return key;
}

// FIX 1 (2026-08-12, Codex review) -- deterministic, predictable
// per-symbol-per-scan key (no direction or real bar timestamp baked
// into the key itself, unlike v3WriteSignal above) so 100% symbol
// accounting is actually AUDITABLE from within this codebase's own
// kvGet -- this file's KV helpers have no LIST/SCAN primitive, so a key
// shape that requires already knowing an exact timestamp to look up
// (v3WriteSignal's shape) can't be enumerated per-symbol without one.
// Called once per symbol per scan, combining every direction/setupType
// that engine evaluated for that symbol into ONE record: "eligible" if
// ANY evaluated variant was eligible, else "rejected" (reasons unioned
// across every rejected variant) if at least one was evaluated, else
// "skipped_data" if a data-level failure blocked evaluation entirely.
// 2026-08-13 (30-minute engine) -- extended with impulseDetail and the
// entry/stop/target/R:R fields the new engine's outcome schema requires
// (all optional, default null, so the two existing 1-hour-engine/
// morning-path call sites -- which never pass them -- are unaffected).
// 2026-08-13 (Codex review FIX 1/2) -- added trailing `extraFields`
// (optional object, spread into the record) instead of yet more
// positional params, specifically so the 30-min engine can attach
// rvolThreshold/consolidationWidth/consolidationMaxAllowed/
// impulseSource/impulseSize/dailyTrendValues/allFailedGates without
// touching this function's existing positional contract or any other
// call site.
// KV-BLOAT FIX (2026-09-09) -- confirmed both real read sites
// (v3GatherGateBreakdown, the missed-mover audit) only ever look up
// THIS SAME dateET's own records, same-tick or same-day, never a past
// date -- so a short TTL cannot break either consumer. 3 days (not 1)
// as a disclosed engineering margin: covers same-day use plus a
// following-morning admin double-check, still bounded. This pattern was
// 21,754 of the ~289,000 keys found via a real SCAN of the store.
const V3_SCANS_OUTCOME_TTL_SECONDS = 3 * 24 * 60 * 60;
async function v3WriteScanOutcome(engine, dateET, scanId, symbol, outcome, rejectionReasons, skippedReason, barCloseTimestamp, rvolDetail, impulseDetail, entryReference, stop, target1, target2, riskReward, extraFields) {
  const key = `v3:scans:outcome:${engine}:${dateET}:${scanId}:${symbol}`;
  await kvSetEx(key, {
    symbol, scanId, engine, barCloseTimestamp: barCloseTimestamp ?? null,
    outcome, rejectionReasons: rejectionReasons ?? [], skippedReason: skippedReason ?? null,
    rvolDetail: rvolDetail ?? null,
    impulseDetail: impulseDetail ?? null,
    entryReference: entryReference ?? null, stop: stop ?? null, target1: target1 ?? null, target2: target2 ?? null, riskReward: riskReward ?? null,
    ...(extraFields ?? {}),
    evaluatedAt: new Date().toISOString(),
  }, V3_SCANS_OUTCOME_TTL_SECONDS);
  return key;
}

// STEP 1 (2026-08-17, System vs. Market outcome capture, additive only
// -- no threshold/gate-logic changes, this is a new recording layer on
// top of each engine's existing writes) -- standardized per-symbol
// outcome record, one of six states: the five specified
// (not_evaluated/skipped_data/rejected/eligible_shadow_blocked/sent)
// plus eligible_capped (added per explicit decision 2026-08-17, for
// engines that pass all gates but lose a daily selection cap that isn't
// a shadow lock -- see channel/pullback/breakout below). Never put a
// setup-type or direction string in a `gate` field -- only real gate
// names (rvol, impulse, consolidation_depth, etc.), enforced by every
// caller below using the gateResults arrays the evaluators themselves
// now return.
async function v3WriteOutcomeRecord(engine, dateET, symbol, outcomeState, opts = {}) {
  const {
    gateResults = null,
    failedGates = null,
    lastGatePassed = null,
    setup = null,
    intradayMovePct = null,
    isMaterialMover = null,
    extraFields = null,
  } = opts;
  const key = `v3:outcome:${engine}:${dateET}:${symbol}`;
  await kvSet(key, {
    symbol, engine, date: dateET, outcomeState,
    evaluatedAt: new Date().toISOString(),
    universeKey: "v3:universe:swing:v2",
    gateResults, failedGates, lastGatePassed,
    setup, intradayMovePct, isMaterialMover,
    ...(extraFields ?? {}),
  });
  return key;
}

// Real market-context helper (today's move %) shared by all four
// engines' outcome records -- reads from an already-fetched snapshots
// batch (never refetches per symbol). Same 3% material-mover threshold
// runV3MasterMissedMoverAudit already uses (Math.abs(move) > 0.05 there
// is a DIFFERENT, wider 5% threshold for THAT audit's own purpose --
// this uses the 3% figure named explicitly in this instruction; two
// different real thresholds for two different real uses, not a
// contradiction).
function v3MoveContextFromSnapshot(snap) {
  const price = snap?.latestTrade?.p;
  const prevClose = snap?.prevDailyBar?.c;
  if (typeof price !== "number" || typeof prevClose !== "number" || prevClose <= 0) {
    return { intradayMovePct: null, isMaterialMover: null };
  }
  const movePct = (price - prevClose) / prevClose;
  return { intradayMovePct: Math.round(movePct * 100000) / 1000, isMaterialMover: Math.abs(movePct) >= 0.03 };
}

// ============================================================
// BOUNDED VALIDATION SYSTEM (2026-08-18, Codex-approved spec) -- STEP 1
// (strategy contracts) + STEP 2 (shared outcome ledger) ONLY. No engine
// logic here -- nothing in this section is called by any scanner yet.
// The paused engines (ORB, channel, VCP, momentum, 1-hour) are
// completely untouched by this section; this is new, additive
// infrastructure only.
// ============================================================

// ---- STEP 1: STRATEGY CONTRACTS ----
// Objective config, no vague words -- every number/rule here is exactly
// what was specified, nothing tuned or invented. Frozen for the
// validation sample per each config's own "note" field -- no mid-sample
// tuning, same versioned-immutable-config pattern as
// V3_MOMENTUM_ENGINE_CONFIG/v3EnsureMomentumEngineConfig above (existing
// record preserved if the version already matches; a version bump is
// the only way this ever changes, and that's a new, visible record, not
// a silent overwrite).
const V3_STRATEGY_SWING_PULLBACK_CONFIG_V1 = {
  version: "v1",
  emaFast: 20, emaSlow: 50, emaLong: 200, emaMomentum: 9,
  trendRequirement: "ema20 > ema50",
  pullbackWindowSessions: [1, 10],
  reclaimRule: "daily close back above 20 EMA after touching 20 EMA zone",
  confirmationRule: "next daily candle closes above reclaim candle high",
  rrMin: 2.0,
  leapsLabelRule: "price above not-falling 200 EMA AND long-dated options available",
  note: "200 EMA is LEAPS label only, NOT a swing gate. frozen for sample.",
};
async function v3EnsureSwingPullbackConfig() {
  const existingResult = await kvGet("v3:strategy:swingPullback:config:v1");
  const existing = existingResult.ok ? existingResult.value : null;
  if (existing && existing.version === V3_STRATEGY_SWING_PULLBACK_CONFIG_V1.version) return existing;
  const config = { ...V3_STRATEGY_SWING_PULLBACK_CONFIG_V1, createdAt: new Date().toISOString() };
  await kvSet("v3:strategy:swingPullback:config:v1", config);
  return config;
}

// is independently verifiable against exactly which config produced
// each historical evaluation, not just which version NUMBER it claims.
function v3ConfigHash(config) {
  const crypto = require("crypto");
  return crypto.createHash("sha256").update(JSON.stringify(config)).digest("hex").slice(0, 16);
}

// ---- STEP 2: SHARED OUTCOME LEDGER ----
// One immutable summary record per engine+date+scanId+symbol. Callers
// MUST supply a fresh, real scanId per real scan (same
// v3MasterDecisionScanId()-style uniqueness every other v3 scan record
// already relies on) -- this function does not itself enforce
// immutability (no kvSetNX; matches the existing v3WriteScanOutcome/
// v3WriteOutcomeRecord convention elsewhere in this file), but a
// correctly-unique scanId makes every real key write-once in practice.
// "evaluated" can never be claimed anywhere in this system unless one
// of these records exists -- that is the entire point of this ledger.
async function v3WriteLedgerRecord(engine, dateET, scanId, symbol, record) {
  const key = v3TestSafeKey(scanId, `v3:ledger:${engine}:${dateET}:${scanId}:${symbol}`);
  await v3KvSetTestAware(key, {
    symbol, engine, date: dateET, scanId,
    strategyVersion: record.strategyVersion ?? null,
    configHash: record.configHash ?? null,
    codeCommit: WORKER_COMMIT_HASH,
    etSessionDate: record.etSessionDate ?? dateET,
    barTimestamps: record.barTimestamps ?? [],
    provider: "alpaca",
    feed: record.feed ?? "sip",
    // evaluationState and deliveryState are deliberately separate axes
    // -- a setup can be evaluationState:"eligible" and still be
    // deliveryState:"held_for_fresh_quote"/"deduped"/
    // "subscriber_prohibited"; a rejected/skipped_data/system_failure
    // record is always deliveryState:"not_applicable".
    evaluationState: record.evaluationState,
    deliveryState: record.deliveryState ?? "not_applicable",
    // A symbol can test more than one level in the same scan (e.g. both
    // PDH and VWAP) -- each attempt recorded separately, in evaluation
    // order, real required/actual/passed per gate (same shape STEP 1's
    // outcome-capture gateResults already established, extended with a
    // levelId/direction wrapper here since this ledger can hold
    // multiple level attempts per symbol where the older per-engine
    // outcome record only ever held one).
    levelAttempts: Array.isArray(record.levelAttempts) ? record.levelAttempts : [],
    setup: record.setup ?? null,
    // Shown for context, never a gate -- contextSignals values must
    // never appear inside any levelAttempts[].failedGates entry; that
    // would be a rejection driven by an unlisted, unenforced criterion,
    // exactly what this ledger's "objective config, no vague words"
    // premise exists to prevent.
    contextSignals: record.contextSignals ?? null,
    // FIX 1 (2026-08-19) -- optional, additive; { available: [...],
    // unavailable: [{level, reason}] } from v3BuildSweepReclaimLevels
    // when levels were built for this symbol. null for records written
    // before levels exist (e.g. skipped_data on the bars fetch itself)
    // or for any other ledger user that doesn't supply it.
    levelsAvailability: record.levelsAvailability ?? null,
    // Quality Profile (2026-08-20) -- optional, additive; display/
    // analysis only, written once and immutable alongside every
    // eligible observation. Never read by any gate, delivery, or
    // grading logic in this file.
    qualityProfile: record.qualityProfile ?? null,
    // Reporting FIX 1 (2026-08-21) -- optional, additive; only
    // meaningful when evaluationState is "skipped_data". One of
    // stale_missing_bars / missing_predefined_level /
    // insufficient_volume_baseline / no_valid_levels / other.
    dataSkipReason: record.dataSkipReason ?? null,
    // Observability FIX (2026-08-19, Codex-approved) -- optional,
    // additive, only meaningful when evaluationState is
    // "system_failure". failureReason distinguishes the three real
    // causes (scan_timeout: never dispatched before the scan deadline;
    // symbol_timeout: this symbol's own processing exceeded its
    // per-symbol timeout; exception: a real thrown error) -- previously
    // all three were indistinguishable in the stored record, visible
    // only in ephemeral console logs. errorSummary is pre-sanitized by
    // the caller via v3SanitizeErrorSummary before it ever reaches this
    // function.
    failureReason: record.failureReason ?? null,
    errorSummary: record.errorSummary ?? null,
    failedAt: record.failedAt ?? null,
    // RTH Reclaim (2026-08-26) -- optional, additive, only meaningful
    // for engine="rthReclaim" (two evaluation points per day). null for
    // every other engine's records, unchanged shape otherwise. rthHalf
    // is "AM"|"PM"; supersession describes whether a PM-eligible result
    // was compared against that same day's AM result and found to be
    // the same underlying structure (never affects evaluationState --
    // a superseded observation is still recorded and graded identically
    // to any other eligible one, only its Telegram delivery differs,
    // same "presentation only" principle as every other conflict/
    // dedup-style field already in this schema).
    rthHalf: record.rthHalf ?? null,
    supersession: record.supersession ?? null,
    // Research instrumentation (2026-09-02, Codex-approved, swingEma20
    // only) -- optional, additive, same convention as qualityProfile
    // above: display/analysis only, NEVER read by any gate, delivery, or
    // grading logic. Specifically NOT read by v3DiscoverSwingEma20NewEligible
    // (which structurally requires evaluationState==="eligible" before it
    // will ever look at a record -- a "rejected" near-miss record carrying
    // this field is invisible to that pipeline regardless of what's in
    // here). null for every engine/record that doesn't supply it.
    research: record.research ?? null,
    // LEDGER-DROP FIX (2026-09-07, real bug found during the finnhubOrCont
    // audit) -- gateResults/failedGates/feedState/sampleEligible/cohortId
    // were computed by callers (v3EvaluateOrContinuation,
    // runV3FinnhubOrContinuationScanJob) and passed into this function's
    // `record` param, but this fixed schema had no matching key for any
    // of them -- they were silently dropped, never reached KV. Confirmed
    // concrete downstream breakage: runV3FinnhubOrContinuationGradingJob
    // read `ledger.sampleEligible` back as permanently undefined, and
    // runV3FinnhubOrContinuationDailyReportJob's `byState[ledger.feedState]`
    // bucketing fell through to "pre_cert" for EVERY observation forever
    // (even post-certification, when observations should show as
    // clean/reconnected/gap_detected) because the key it was looking up
    // never existed. Purely additive -- every other engine that doesn't
    // supply these fields gets the same null/[] default it always
    // implicitly got, so this cannot change any existing engine's
    // behavior, only stop discarding data finnhubOrContinuation (and any
    // future caller) already computes and expects to be durable.
    gateResults: Array.isArray(record.gateResults) ? record.gateResults : [],
    failedGates: Array.isArray(record.failedGates) ? record.failedGates : [],
    feedState: record.feedState ?? null,
    sampleEligible: record.sampleEligible ?? null,
    cohortId: record.cohortId ?? null,
    // Market-structure lens (2026-09-07, swingEma20 only) -- additive,
    // display/analysis only, same convention as qualityProfile/research
    // above. Never read by any gate, delivery, or grading logic. null
    // for every engine/record that doesn't supply it -- learned this
    // exact lesson from the ledger-drop bug just above (gateResults/
    // feedState/sampleEligible/cohortId): a new computed field is worth
    // nothing if this function has no key for it.
    marketStructureContext: record.marketStructureContext ?? null,
    writtenAt: new Date().toISOString(),
  });
  return key;
}

// Per-scan data-health summary -- separate from the per-symbol ledger,
// one record per engine+date+scanId. missedWindow lets a scan that
// never got a real tick land in its trading window (same durable-
// scheduling class of gap this codebase has fixed elsewhere) show up
// here as an honest, visible fact rather than just an absent ledger.
async function v3WriteDataHealthRecord(engine, dateET, scanId, record) {
  const key = v3TestSafeKey(scanId, `v3:datahealth:${engine}:${dateET}:${scanId}`);
  await v3KvSetTestAware(key, {
    expectedSymbols: record.expectedSymbols ?? null,
    actualEvaluated: record.actualEvaluated ?? null,
    // FIX 3 (2026-08-19) -- optional, additive; lets the proactive
    // coverage-summary jobs aggregate eligible counts across today's
    // scans from this record alone, without a second index.
    eligibleCount: record.eligibleCount ?? null,
    skippedData: record.skippedData ?? null,
    systemFailures: record.systemFailures ?? null,
    // Observability FIX (2026-08-19) -- optional, additive; the subset
    // of systemFailures specifically caused by an individual symbol's
    // own timeout, as opposed to scan_timeout or a thrown exception.
    symbolTimeouts: record.symbolTimeouts ?? null,
    // Reporting FIX 1 (2026-08-21) -- optional, additive; per-scan
    // breakdown of WHY each skipped_data outcome happened, so the
    // coverage summary can show a reason breakdown instead of a raw
    // count. See v3ProcessSweepReclaimSymbol's dataSkipReason values.
    skippedDataReasonCounts: record.skippedDataReasonCounts ?? null,
    missedWindow: record.missedWindow === true,
    sourceFreshness: record.sourceFreshness ?? null,
    configVersion: record.configVersion ?? null,
    writtenAt: new Date().toISOString(),
  });
  return key;
}





// Per-date index of every scanId Master Decision Agent generated today
// (across all engines/windows) -- feeds FIX 4's missed-mover audit,
// which needs to know which scanIds to check v3:scans:outcome:* against
// for a given symbol, since there's no way to enumerate them otherwise.
async function v3RecordScanId(dateET, engine, scanId, windowLabel) {
  // TEST ISOLATION (2026-08-19, post-incident hardening) -- this shared
  // index is exactly what got contaminated with real production writes
  // during earlier verification testing (see
  // v3:audit:contamination:2026-08-19:testDataIncident). A TEST-
  // prefixed scanId is REFUSED here outright -- it never enters the real
  // index at all, prevention rather than a downstream filter.
  if (String(scanId ?? "").startsWith(V3_TEST_SOURCE_PREFIX)) {
    console.log(`v3RecordScanId: scanId="${scanId}" is a test run -- not written to the real v3:master:scanIdsToday:${dateET} index.`);
    return;
  }
  const existingResult = await kvGet(`v3:master:scanIdsToday:${dateET}`);
  const existing = existingResult.ok && Array.isArray(existingResult.value) ? existingResult.value : [];
  existing.push({ engine, scanId, windowLabel, recordedAt: new Date().toISOString() });
  await kvSet(`v3:master:scanIdsToday:${dateET}`, existing);
}

// ---- CORRECTION 2 -- session-aligned hourly bars built from 5-minute
// SIP data, NOT Alpaca's native 1Hour timeframe (which aligns to
// top-of-hour UTC, not 9:30am ET -- see CLAUDE.md Common Problem #3,
// the same real bug getOpeningRangeCandle already sidesteps the same
// way for the opening range specifically). No v3CheckFinalDailyBarStatus
// gate here -- that gate is about whether TODAY's DAILY bar has
// published market-wide, a different question from "has this specific
// 5-minute bar's own window closed," which Alpaca's SIP feed reports
// near-real-time regardless of whether today's session has ended.
async function v3GetFiveMinuteSipBars(symbol, daysBack) {
  try {
    const fetch = (await import("node-fetch")).default;
    const startDate = new Date(Date.now() - Math.ceil(daysBack / 0.7) * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
    let allBars = [];
    let pageToken = null;
    let pageCount = 0;
    const MAX_PAGES = 20;
    do {
      const url = `https://data.alpaca.markets/v2/stocks/${symbol}/bars?timeframe=5Min&start=${encodeURIComponent(startDate)}&limit=10000&sort=asc&feed=sip${pageToken ? `&page_token=${encodeURIComponent(pageToken)}` : ""}`;
      const r = await fetch(url, { headers: { "APCA-API-KEY-ID": ALPACA_KEY_ID, "APCA-API-SECRET-KEY": ALPACA_SECRET } });
      if (!r.ok) {
        const body = await r.text().catch(() => "");
        return { ok: false, error: `HTTP ${r.status}: ${body.slice(0, 200)}`, bars: [] };
      }
      const d = await r.json();
      allBars = allBars.concat(d?.bars ?? []);
      pageToken = d?.next_page_token ?? null;
      pageCount++;
      if (pageToken && pageCount >= MAX_PAGES) break;
    } while (pageToken);
    return { ok: true, error: null, bars: allBars };
  } catch (e) {
    return { ok: false, error: e.message, bars: [] };
  }
}

// Daily bars strictly through the PRIOR completed session, safe to call
// at ANY time of day (including mid-session) -- unlike
// v3GetCompletedDailySipBars, which hard-requires the market to be
// closed (throws otherwise) because it's built to include TODAY's own
// just-finalized bar. The momentum engine needs daily-EMA/trend context
// DURING market hours (the 12:30/1:30/2:30/3:30pm scans) -- always safe
// since yesterday's bar is already final regardless of what today's
// market is doing right now. Filters out any bar dated today or later,
// defensively, in case Alpaca ever returns a partial in-progress bar.
async function v3GetPriorSessionDailyBars(symbol, lookbackDays) {
  try {
    const fetch = (await import("node-fetch")).default;
    const todayET = new Date().toLocaleDateString("en-CA", { timeZone: "America/New_York" });
    const startDate = new Date(Date.now() - Math.ceil(lookbackDays / 0.7) * 24 * 60 * 60 * 1000).toISOString().split("T")[0];
    let allBars = [];
    let pageToken = null;
    let pageCount = 0;
    const MAX_PAGES = 15;
    do {
      const url = `https://data.alpaca.markets/v2/stocks/${symbol}/bars?timeframe=1Day&start=${encodeURIComponent(startDate)}&limit=1000&sort=asc&feed=sip${pageToken ? `&page_token=${encodeURIComponent(pageToken)}` : ""}`;
      const r = await fetch(url, { headers: { "APCA-API-KEY-ID": ALPACA_KEY_ID, "APCA-API-SECRET-KEY": ALPACA_SECRET } });
      if (!r.ok) {
        const body = await r.text().catch(() => "");
        return { ok: false, error: `HTTP ${r.status}: ${body.slice(0, 200)}`, bars: [] };
      }
      const d = await r.json();
      allBars = allBars.concat(d?.bars ?? []);
      pageToken = d?.next_page_token ?? null;
      pageCount++;
      if (pageToken && pageCount >= MAX_PAGES) break;
    } while (pageToken);
    const bars = allBars.filter((b) => new Date(b.t).toLocaleDateString("en-CA", { timeZone: "America/New_York" }) < todayET);
    return { ok: true, error: null, bars, barCount: bars.length };
  } catch (e) {
    return { ok: false, error: e.message, bars: [] };
  }
}

// Buckets a day's 5-minute bars into 7 session-aligned windows starting
// 9:30am ET (570 min): [9:30-10:30),[10:30-11:30),[11:30-12:30),
// [12:30-1:30),[1:30-2:30),[2:30-3:30),[3:30-4:00) (last one a 30-min
// partial, the session's own close -- never actually referenced by any
// scheduled scan, since the last momentum window is 3:30pm). `complete`
// is true only once `nowMinutesET` is past the bucket's own end
// boundary -- pass null for historical (always-complete) days.
const V3_SESSION_HOUR_BOUNDARIES = [570, 630, 690, 750, 810, 870, 930, 960];
function v3BuildSessionAlignedHourBuckets(fiveMinBars, dateKeyYMD, nowMinutesET) {
  const fmt = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", hour: "2-digit", minute: "2-digit", hour12: false, year: "numeric", month: "2-digit", day: "2-digit" });
  const todaysBars = [];
  for (const b of fiveMinBars) {
    const parts = fmt.formatToParts(new Date(b.t));
    const get = (type) => parts.find((p) => p.type === type)?.value;
    const barDate = `${get("year")}-${get("month")}-${get("day")}`;
    if (barDate !== dateKeyYMD) continue;
    let hh = Number(get("hour")); if (hh === 24) hh = 0;
    const minuteOfDay = hh * 60 + Number(get("minute"));
    todaysBars.push({ ...b, minuteOfDay });
  }
  todaysBars.sort((a, b) => a.minuteOfDay - b.minuteOfDay);

  const buckets = [];
  for (let i = 0; i < V3_SESSION_HOUR_BOUNDARIES.length - 1; i++) {
    const startMin = V3_SESSION_HOUR_BOUNDARIES[i], endMin = V3_SESSION_HOUR_BOUNDARIES[i + 1];
    const barsInBucket = todaysBars.filter((b) => b.minuteOfDay >= startMin && b.minuteOfDay < endMin);
    if (barsInBucket.length === 0) { buckets.push({ startMin, endMin, complete: nowMinutesET != null && nowMinutesET >= endMin, bars: [], o: null, h: null, l: null, c: null, v: 0 }); continue; }
    buckets.push({
      startMin, endMin,
      complete: nowMinutesET != null && nowMinutesET >= endMin,
      bars: barsInBucket,
      o: barsInBucket[0].o,
      h: Math.max(...barsInBucket.map((b) => b.h)),
      l: Math.min(...barsInBucket.map((b) => b.l)),
      c: barsInBucket[barsInBucket.length - 1].c,
      v: barsInBucket.reduce((s, b) => s + b.v, 0),
    });
  }
  return buckets;
}

// Ascending (oldest-first) list of the `count` real NYSE trading days
// strictly before todayDateKey -- shares the v3GetNyseSessionInfo
// calendar (weekends/holidays correctly skipped).
function v3PriorTradingDayKeys(todayDateKey, count) {
  const keys = [];
  const [y0, m0, d0] = todayDateKey.split("-").map(Number);
  let cursor = new Date(Date.UTC(y0, m0 - 1, d0));
  let safety = 0;
  while (keys.length < count && safety < count * 3 + 20) {
    cursor = new Date(cursor.getTime() - 24 * 60 * 60 * 1000);
    safety++;
    const y = cursor.getUTCFullYear(), m = cursor.getUTCMonth() + 1, d = cursor.getUTCDate();
    const candidate = `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    if (v3GetNyseSessionInfo(candidate).didTrade) keys.push(candidate);
  }
  return keys.reverse();
}

// Concatenates the trailing sessions' hourly closes (6 full-hour
// buckets/day, index 0-5) with today's closes through breakoutIdx, for
// RSI(14)-on-hourly -- a single session has only ~6 bars, nowhere near
// RSI(14)'s 15-bar minimum. NOT independently specified by the
// instruction how multi-day hourly RSI should be assembled; disclosed
// judgment call, flagged in the momentum evaluator's own header too.
function v3FlattenHourlyCloseSeries(historicalBucketsByDate, todayBuckets, upToIndex) {
  const closes = [];
  for (const buckets of historicalBucketsByDate.values()) {
    for (let i = 0; i < 6; i++) { if (buckets[i]?.c != null) closes.push(buckets[i].c); }
  }
  for (let i = 0; i <= upToIndex; i++) { if (todayBuckets[i]?.c != null) closes.push(todayBuckets[i].c); }
  return closes;
}

// Mirror of v3CheckWeeklyTrendBullish for the bearish direction --
// same sourced Weinstein-style "price below declining 10/30-week EMA"
// logic, reversed.
function v3CheckWeeklyTrendDirection(weeklyBars, direction) {
  if (!weeklyBars || weeklyBars.length < 34) return { aligned: false, reason: "insufficient_weekly_bars" };
  const closes = weeklyBars.map((b) => b.c);
  const ema10 = v3EMASeries(closes, 10);
  const ema30 = v3EMASeries(closes, 30);
  const lastIdx = closes.length - 1;
  const ema10Now = ema10[lastIdx], ema30Now = ema30[lastIdx];
  const ema10Prior = ema10[lastIdx - 4], ema30Prior = ema30[lastIdx - 4];
  if (ema10Now == null || ema30Now == null || ema10Prior == null || ema30Prior == null) return { aligned: false, reason: "ema_not_computable" };
  const price = closes[lastIdx];
  if (direction === "bullish") {
    const aligned = price > ema10Now && price > ema30Now && ema10Now > ema10Prior && ema30Now > ema30Prior;
    return { aligned, reason: aligned ? "weekly_uptrend_confirmed" : "weekly_trend_not_bullish" };
  }
  const aligned = price < ema10Now && price < ema30Now && ema10Now < ema10Prior && ema30Now < ema30Prior;
  return { aligned, reason: aligned ? "weekly_downtrend_confirmed" : "weekly_trend_not_bearish" };
}

// ---- CORRECTION 3 -- bullish/bearish 1-hour momentum evaluator.
// consolidationIdx1/2 = the two completed hour-bucket indices forming
// the consolidation range; breakoutIdx = the current (just-completed)
// bar being checked for a break of that range -- a rolling pair, not
// fixed to the first two bars of the day (e.g. the 1:30pm scan uses
// buckets 1&2 as consolidation, bucket 3 as breakout). Entry/stop/
// target convention: breakout level as entry, opposite consolidation
// edge as stop, consolidation-range-height measured-move as target1/
// 2x as target2 -- the SAME measured-move convention
// v3EvaluateBaseBreakout already uses elsewhere in this file. Neither
// this convention nor the multi-day RSI assembly above is independently
// specified by the instruction for momentum; both are disclosed
// judgment calls.
async function v3EvaluateMomentum(symbol, direction, dailyBars, todayBuckets, historicalBucketsByDate, consolidationIdx1, consolidationIdx2, breakoutIdx, spyDirection) {
  const isLong = direction === "bullish";
  const detectedAt = new Date().toISOString();
  const base = { symbol, direction, setupType: isLong ? "MOMENTUM_BULLISH" : "MOMENTUM_BEARISH", detectedAt, dataSource: "alpaca_sip_5min_session_aligned" };

  const dailyCloses = dailyBars.map((b) => b.c);
  if (dailyCloses.length < 51) return { ...base, eligible: false, gates: null, ineligibleReasons: [`skipped_data: insufficient_daily_history (${dailyCloses.length} bars, need 51+)`] };
  const dailyEma20 = v3EMASeries(dailyCloses, 20);
  const dailyEma50 = v3EMASeries(dailyCloses, 50);
  const lastDailyIdx = dailyCloses.length - 1;
  const ema20Now = dailyEma20[lastDailyIdx], ema50Now = dailyEma50[lastDailyIdx];
  const priorClose = dailyCloses[lastDailyIdx];
  if (ema20Now == null || ema50Now == null) return { ...base, eligible: false, gates: null, ineligibleReasons: ["skipped_data: daily_ema_not_computable"] };

  const breakoutBar = todayBuckets[breakoutIdx];
  const bar1 = todayBuckets[consolidationIdx1], bar2 = todayBuckets[consolidationIdx2];
  if (!breakoutBar?.complete || !bar1?.complete || !bar2?.complete || breakoutBar.c == null || bar1.c == null || bar2.c == null) {
    return { ...base, eligible: false, gates: null, ineligibleReasons: ["skipped_data: one or more required hour buckets not yet complete or missing bars"] };
  }
  const currentPrice = breakoutBar.c;

  const dailyTrendOk = isLong ? (currentPrice > ema20Now && currentPrice > ema50Now) : (currentPrice < ema20Now && currentPrice < ema50Now);

  const movePct = priorClose > 0 ? (currentPrice - priorClose) / priorClose : null;
  const moveOk = movePct != null && (isLong ? movePct >= 0.02 : movePct <= -0.02);

  // FIX 2 (2026-08-12, Codex review) -- verified, not changed: compares
  // breakoutBar.v (today's specific completed session-aligned hour
  // bucket's OWN volume -- a per-bucket sum, never cumulative-since-open;
  // breakoutBar is only ever reached here after the earlier
  // `!breakoutBar?.complete` check, so it's never a forming bar) against
  // the SAME bucket index (same hour slot) across the trailing 20 real
  // prior sessions (v3PriorTradingDayKeys), also per-bucket sums, never
  // pre-market (bucket boundaries start at 570min/9:30am, pre-market
  // 5-min bars fall outside every bucket and are dropped by the
  // boundary filter in v3BuildSessionAlignedHourBuckets). Matches all 4
  // of the instruction's stated requirements -- the math itself is
  // unchanged by this fix, only rvolDetail's transparency fields are new.
  const historicalVolsThisBucket = [...historicalBucketsByDate.values()].map((buckets) => buckets[breakoutIdx]?.v).filter((v) => v != null && v > 0).sort((a, b) => a - b);
  let rvol = null, priorSessionSameHourMedian = null;
  if (historicalVolsThisBucket.length >= 10) {
    const mid = Math.floor(historicalVolsThisBucket.length / 2);
    priorSessionSameHourMedian = historicalVolsThisBucket.length % 2 === 0 ? (historicalVolsThisBucket[mid - 1] + historicalVolsThisBucket[mid]) / 2 : historicalVolsThisBucket[mid];
    rvol = priorSessionSameHourMedian > 0 ? breakoutBar.v / priorSessionSameHourMedian : null;
  }
  const rvolOk = rvol != null && rvol > 2.0;
  const currentBarHour = `${Math.floor(breakoutBar.startMin / 60)}:${String(breakoutBar.startMin % 60).padStart(2, "0")}`;
  const rvolDetail = {
    currentBarVolume: breakoutBar.v,
    currentBarHour,
    priorSessionSameHourMedian,
    rvolRatio: rvol,
    sessionsUsed: historicalVolsThisBucket.length,
  };

  const consolHigh = Math.max(bar1.h, bar2.h), consolLow = Math.min(bar1.l, bar2.l);
  const consolRangePct = consolHigh > 0 ? (consolHigh - consolLow) / consolHigh : 1;
  const consolidationOk = consolRangePct <= 0.015;

  const breakoutOk = isLong ? breakoutBar.c > consolHigh : breakoutBar.c < consolLow;

  const barsThroughBreakout = todayBuckets.slice(0, breakoutIdx + 1).flatMap((b) => b.bars ?? []);
  const vwap = v2VWAP(barsThroughBreakout);
  const vwapOk = vwap != null && (isLong ? currentPrice > vwap : currentPrice < vwap);

  const hourlyCloses = v3FlattenHourlyCloseSeries(historicalBucketsByDate, todayBuckets, breakoutIdx);
  const rsiSeries = v3RSISeries(hourlyCloses, 14);
  const rsi = rsiSeries.length > 0 ? rsiSeries[rsiSeries.length - 1] : null;
  const rsiOk = rsi != null && (isLong ? (rsi >= 50 && rsi <= 70) : (rsi >= 30 && rsi <= 50));

  const rangeHeight = consolHigh - consolLow;
  const entryReference = isLong ? consolHigh : consolLow;
  const stop = isLong ? consolLow : consolHigh;
  const target1 = isLong ? entryReference + rangeHeight : entryReference - rangeHeight;
  const target2 = isLong ? entryReference + 2 * rangeHeight : entryReference - 2 * rangeHeight;
  const risk = isLong ? entryReference - stop : stop - entryReference;
  const reward = isLong ? target1 - entryReference : entryReference - target1;
  const riskReward = risk > 0 && reward > 0 ? reward / risk : null;
  const rrOk = riskReward != null && riskReward >= 2.0;

  const gates = { dailyTrend: dailyTrendOk, move: moveOk, rvol: rvolOk, consolidation: consolidationOk, breakout: breakoutOk, vwap: vwapOk, rsi: rsiOk, riskReward: rrOk };
  const eligible = Object.values(gates).every(Boolean);
  const ineligibleReasons = [];
  if (!dailyTrendOk) ineligibleReasons.push(`daily_trend_not_aligned: price $${currentPrice.toFixed(2)} vs EMA20 $${ema20Now.toFixed(2)}/EMA50 $${ema50Now.toFixed(2)}`);
  if (!moveOk) ineligibleReasons.push(`insufficient_move: ${movePct != null ? (movePct * 100).toFixed(2) : "n/a"}% from prior close (need ${isLong ? ">=+2%" : "<=-2%"})`);
  if (!rvolOk) ineligibleReasons.push(`rvol_insufficient: ${rvol != null ? rvol.toFixed(2) : "n/a"}x same-hour 20-session median (need >2.0x)`);
  if (!consolidationOk) ineligibleReasons.push(`consolidation_too_wide: ${(consolRangePct * 100).toFixed(2)}% range (need <=1.5%)`);
  if (!breakoutOk) ineligibleReasons.push(`no_breakout: close $${breakoutBar.c.toFixed(2)} did not clear consolidation ${isLong ? "high" : "low"} $${(isLong ? consolHigh : consolLow).toFixed(2)}`);
  if (!vwapOk) ineligibleReasons.push(`vwap_wrong_side: price $${currentPrice.toFixed(2)} vs VWAP $${vwap != null ? vwap.toFixed(2) : "n/a"}`);
  if (!rsiOk) ineligibleReasons.push(`rsi_outside_range: ${rsi != null ? rsi.toFixed(1) : "n/a"} (need ${isLong ? "50-70" : "30-50"})`);
  if (!rrOk) ineligibleReasons.push(`insufficient_rr: ${riskReward != null ? riskReward.toFixed(2) : "n/a"} (need >=2.0)`);

  return {
    ...base, eligible, gates, ineligibleReasons,
    entryReference, stop, target1, target2, riskReward,
    currentPrice, priorClose, movePct, rvol, rvolDetail, rsi14: rsi, vwap,
    consolHigh, consolLow, barCloseTimestamp: breakoutBar.bars[breakoutBar.bars.length - 1]?.t ?? detectedAt,
    dailyEma20: ema20Now, dailyEma50: ema50Now,
    spyAligned: spyDirection === direction,
  };
}

// ---- CORRECTION 4 -- hard gates, checked FIRST, before any scoring.
// alertsSentToday: v3:master:alertsSentToday:{date} -- real sends AND
// shadow-mode "would-have-sent" entries are BOTH recorded here (see
// runV3MasterDecisionAgent's own header), since Stage 1's whole purpose
// is verifying dedup/cap mechanics actually work, which requires the
// gate to behave exactly as it would live even while sends are
// suppressed.
// FIX 3 (2026-08-12, Codex review) -- gate renamed to what it actually
// verifies. The original 8-gate list named a separate "not halted or
// halting" check; this account's trading-API access is 401'd (data-only
// tier, see CLAUDE.md's credentials table), so no real halt-status feed
// is available anywhere in this codebase -- there was never a second,
// independent check here, only ONE freshness check doing double duty.
// Renamed to "fresh_market_data" (was "no_fresh_quote") and the
// misleading "not halted" line removed from the numbered list entirely
// rather than left implying a safeguard that doesn't exist. This gate
// verifies data freshness ONLY -- it does not and cannot detect a real
// trading halt on this account tier.
async function v3CheckHardGates(candidate, alertsSentToday, freshQuote) {
  const reasons = [];
  // 1. fresh_market_data -- same "trade printed on today's ET date"
  // freshness definition already established for pre-market
  // revalidation (v3RevalidateMorningPick), applied to the current/
  // latest trade here instead of a pre-market one. Does NOT verify halt
  // status -- see header comment above.
  const todayET = v3TradingDateET();
  const freshOk = freshQuote != null && v3TradingDateET(new Date(freshQuote.timestamp)) === todayET;
  if (!freshOk) reasons.push("fresh_market_data_failed");
  // 2. Completed bar (not forming)
  if (!candidate.gates || candidate.eligible == null) reasons.push("candidate_not_evaluated_or_bar_still_forming");
  // 3. Valid stop AND target1
  if (candidate.stop == null || candidate.target1 == null) reasons.push("missing_stop_or_target1");
  // 4. R:R >= 2.0
  if (candidate.riskReward == null || candidate.riskReward < 2.0) reasons.push("rr_below_2");
  // 5. Not already alerted this symbol/direction today
  if (alertsSentToday.some((a) => a.symbol === candidate.symbol && a.direction === candidate.direction)) reasons.push("already_alerted_today_this_symbol_direction");
  // 6. Daily cap not exceeded (max 2 total, across ALL engines)
  if (alertsSentToday.length >= 2) reasons.push("daily_cap_reached");
  // 7. No active invalidation -- an unresolved (graded:false) prior
  // sentAlert on this symbol counts as an active position/alert.
  const pendingIndexResult = await kvGet("v3:swing:pendingGradeIndex");
  const pending = pendingIndexResult.ok && Array.isArray(pendingIndexResult.value) ? pendingIndexResult.value : [];
  if (pending.some((p) => p.symbol === candidate.symbol)) reasons.push("active_invalidation_pending_prior_alert");

  return { passed: reasons.length === 0, reasons };
}

// SCORING -- applied ONLY to candidates that already passed every hard
// gate above. Catalyst verification (+3) is NEVER awarded -- no
// catalyst/news-verification engine (earnings/FDA/M&A/upgrade) is wired
// into this codebase, so this always contributes 0, consistent with
// "no penalty for missing catalyst" (0 is the correct default, not a
// gap this build needs to fill). RVOL is deliberately not scored on its
// own -- it's already a hard gate for momentum; the momentum signal's
// own +2 is the only intraday-momentum contribution, capped combined
// with nothing else that could double it.
function v3ScoreCandidate(context) {
  let score = 0;
  const breakdown = [];
  const bump = (points, label) => { score += points; breakdown.push({ points, label }); };
  if (context.dailyTrendAligned) bump(2, "daily_trend_aligned");
  if (context.weeklyLevelConfluence) bump(2, "pattern_confluence_weekly_level");
  if (context.isMomentumSignal) bump(2, "1hr_momentum_signal");
  if (context.weeklyTrendAligned) bump(1, "weekly_trend_aligned");
  if (context.spyAligned) bump(1, "spy_aligned");
  if (context.counterTrend) bump(-2, "counter_trend_signal");
  if (context.fallbackDataUsed) bump(-2, "fallback_range_data_used");
  return { score, breakdown };
}

// Weekly swing-high/low pivots (2-bars-each-side local extrema, same
// shape this file already uses for swing-point detection elsewhere) --
// used only for the +2 "pattern confluence with prior day/weekly level"
// scoring input: true if entryReference sits within 1% of a real pivot.
function v3HasWeeklyLevelConfluence(weeklyBars, entryReference) {
  if (!weeklyBars || weeklyBars.length < 5 || entryReference == null) return false;
  for (let i = 2; i < weeklyBars.length - 2; i++) {
    const bar = weeklyBars[i];
    const isSwingHigh = bar.h >= weeklyBars[i - 1].h && bar.h >= weeklyBars[i - 2].h && bar.h >= weeklyBars[i + 1].h && bar.h >= weeklyBars[i + 2].h;
    const isSwingLow = bar.l <= weeklyBars[i - 1].l && bar.l <= weeklyBars[i - 2].l && bar.l <= weeklyBars[i + 1].l && bar.l <= weeklyBars[i + 2].l;
    if (isSwingHigh && Math.abs(bar.h - entryReference) / entryReference <= 0.01) return true;
    if (isSwingLow && Math.abs(bar.l - entryReference) / entryReference <= 0.01) return true;
  }
  return false;
}

function v3PatternDisplayNameMomentum(direction) {
  return direction === "bullish" ? "1-hour momentum breakout" : "1-hour momentum breakdown";
}

// ALERT LABELS -- required on every alert. Swing = "days to weeks",
// momentum = "same day to 2 days", never LEAPS.
function v3BuildMasterSwingMessage(pick, revalidation, dateET, trendLine) {
  const sources = v3TargetSourceLabels(pick.setupType);
  const rr = pick.riskReward != null ? pick.riskReward.toFixed(1) : "n/a";
  const timeStr = new Date(revalidation.revalidatedAt).toLocaleTimeString("en-US", { timeZone: "America/New_York", hour: "numeric", minute: "2-digit" });
  const premarketLine = revalidation.freshQuoteAvailable
    ? `Pre-market: $${revalidation.currentPrice.toFixed(2)} as of ${timeStr} ET`
    : `Plan based on ${pick.asOfSessionDate} close — pre-market quote unavailable`;
  const validLine = revalidation.freshQuoteAvailable ? "Valid at open: YES" : "Confirm entry after open — NOT valid at open";
  return `🎯 SWING SETUP — ${pick.symbol} — ${dateET}
Pattern: ${v3PatternDisplayName(pick.setupType)} | Holding: days to weeks
Formed: ${pick.asOfSessionDate}
${premarketLine}
Entry above: $${pick.entryReference.toFixed(2)}
Stop: $${pick.stop.toFixed(2)}
Target 1: ${pick.target1 != null ? "$" + pick.target1.toFixed(2) : "n/a"} (${sources.target1})
Target 2: ${pick.target2 != null ? "$" + pick.target2.toFixed(2) : "n/a"} (${sources.target2})
R:R: ${rr}:1
${trendLine}
${validLine}
⚠️ Not financial advice`;
}

function v3BuildMasterMomentumMessage(candidate) {
  const isLong = candidate.direction === "bullish";
  const rr = candidate.riskReward != null ? candidate.riskReward.toFixed(1) : "n/a";
  const impulseSign = candidate.movePct != null && candidate.movePct >= 0 ? "+" : "";
  return `⚡ MOMENTUM — ${candidate.symbol} $${candidate.currentPrice.toFixed(2)} | Holding: same day to 2 days
1-hour consolidation break ✅
Impulse: ${impulseSign}${candidate.movePct != null ? (candidate.movePct * 100).toFixed(2) : "n/a"}% from prior close
RVOL: ${candidate.rvol != null ? candidate.rvol.toFixed(1) : "n/a"}x ✅ | VWAP: ${isLong ? "above" : "below"} ✅ | RSI: ${candidate.rsi14 != null ? candidate.rsi14.toFixed(1) : "n/a"} ✅
Daily trend: ${isLong ? "bullish" : "bearish"} ✅

📍 ENTRY: $${candidate.entryReference.toFixed(2)}
🎯 TARGET 1: $${candidate.target1.toFixed(2)}
🎯 TARGET 2: $${candidate.target2.toFixed(2)}
⛔ STOP: $${candidate.stop.toFixed(2)}
R:R: ${rr}:1
⚠️ Not financial advice`;
}

// Shared daily alert log across ALL engines -- "max 2 alerts per day
// TOTAL", not per engine. Real sends AND shadow-mode "would-have-sent"
// entries are both appended (see v3CheckHardGates' own comment on why).
async function v3RecordMasterAlert(dateET, symbol, direction, setupType) {
  const existingResult = await kvGet(`v3:master:alertsSentToday:${dateET}`);
  const existing = existingResult.ok && Array.isArray(existingResult.value) ? existingResult.value : [];
  existing.push({ symbol, direction, setupType, recordedAt: new Date().toISOString() });
  await kvSet(`v3:master:alertsSentToday:${dateET}`, existing);
  return existing;
}

// 2026-08-13 (Codex review) -- "no qualified setup" is a KV-only admin
// diagnostic, NEVER a Telegram send, in stage1_mechanics (and this
// build never wires it to Telegram in ANY stage -- adding a live-stage
// send wasn't asked for here, so it isn't built). Telegram from this
// system is limited to exactly two paths: the coverage-gap/system-
// failure incident (runV3MasterMissedMoverAudit, unconditional) and a
// real setup alert once manually promoted (shadowStage==="live",
// existing `canSend` gate on the selections loop below). This function
// stores the same text a "no qualified setup" message would have
// carried, purely for admin review via kvGet -- it never touches
// v3SendTelegram.
async function v3RecordNoQualifiedSetup(dateET, engine, windowLabel, candidatesEvaluated) {
  const message = `📊 MASTER DECISION — ${engine} — ${dateET} ${windowLabel}\nNo qualified setup.\nCandidates evaluated: ${candidatesEvaluated}, none scored >=5 or none passed hard gates.\n(KV-only diagnostic -- never sent to Telegram in stage1_mechanics.)`;
  await kvSet(`v3:master:noSetup:${dateET}:${engine}:${windowLabel}`, {
    dateET, engine, windowLabel, candidatesEvaluated, message,
    telegramSent: false,
    recordedAt: new Date().toISOString(),
  });
}

// ---- Morning path (8:20am ET) -- reads TODAY's already-scanned swing
// candidates (Channel Bounce / Trend Pullback / Base Breakout, written
// by the EXISTING channelScanner/masterSwingAgent pipeline, untouched)
// across the full v1 universe, not just that pipeline's own pre-
// filtered top-2 -- hard gates + scoring need the full candidate pool,
// per Correction 4 ("Master checks these FIRST"). Only candidates whose
// OWN pattern-specific gates already passed (eligible:true) are fully
// hard-gate-checked -- re-running full checks on ~369 pattern-ineligible
// records would be wasted work, since a failed pattern gate already
// means no valid entry structure exists; disclosed scoping choice.
async function runV3MasterDecisionMorning(dateET) {
  const scanId = v3MasterDecisionScanId();
  await v3RecordScanId(dateET, "masterMorning", scanId, "morning");
  const shadowStage = await v3GetMasterDecisionShadowStage();
  const canSend = shadowStage === "live";

  // FIX 1 (2026-08-14) -- v2, not v1 (see channelScanner's own comment
  // for the full rationale).
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols)) {
    await v3SendUniverseUnavailableIncident(dateET, "masterDecisionMorning");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };
  }

  const spySnap = (await v2GetAlpacaSnapshotsBatch(["SPY"]))?.SPY;
  const spyMove = spySnap?.latestTrade?.p != null && spySnap?.prevDailyBar?.c > 0 ? (spySnap.latestTrade.p - spySnap.prevDailyBar.c) / spySnap.prevDailyBar.c : null;
  const spyDirection = spyMove == null ? null : spyMove >= 0 ? "bullish" : "bearish";

  const setupTypes = ["CHANNEL_BOUNCE_LONG", "CHANNEL_BOUNCE_SHORT", "TREND_PULLBACK_LONG", "BASE_BREAKOUT_LONG"];
  const alertsSentTodayResult = await kvGet(`v3:master:alertsSentToday:${dateET}`);
  let alertsSentToday = alertsSentTodayResult.ok && Array.isArray(alertsSentTodayResult.value) ? alertsSentTodayResult.value : [];

  // FIX 2 (2026-08-14, Codex review) -- same honest-accounting fix as
  // the 30-min momentum engine: pattern-level rejections used to fall
  // into no counter at all, and skipped_data was counted per-setupType
  // (up to 4x per symbol) rather than per-symbol -- both now fixed by
  // tallying ONCE per symbol after all 4 setupTypes are checked, based
  // on the symbol's final outcome/stage.
  let hardGateRejections = 0, patternGateRejections = 0, eligibleAfterGates = 0, skippedData = 0;
  const passedCandidates = [];

  for (const symbol of universe.symbols) {
    // FIX 1 (2026-08-12) -- exactly ONE v3:scans:outcome:* record per
    // symbol per scan, combining all 4 setupTypes' results.
    let symbolOutcome = "skipped_data";
    let symbolStage = null; // "pattern_gates" | "hard_gates" | null
    let symbolReasons = [];
    let symbolSkippedReason = null;
    let symbolBarCloseTimestamp = null;
    let anyRecordFound = false;
    for (const setupType of setupTypes) {
      const recordResult = await kvGet(`v3:swing:candidate:${dateET}:${symbol}:${setupType}`);
      const record = recordResult.ok ? recordResult.value : null;
      const direction = setupType === "CHANNEL_BOUNCE_SHORT" ? "bearish" : "bullish";
      const barCloseTimestamp = record?.detectedAt ?? new Date().toISOString();
      symbolBarCloseTimestamp = symbolBarCloseTimestamp ?? barCloseTimestamp;

      if (!record) {
        await v3WriteSignal("masterMorning", dateET, symbol, direction, barCloseTimestamp, { symbol, direction, setupType, outcome: "skipped_data", failedInput: "no candidate record found for today", scanId });
        symbolSkippedReason = symbolSkippedReason ?? `no ${setupType} candidate record found for today`;
        continue;
      }
      anyRecordFound = true;
      if (!record.eligible) {
        await v3WriteSignal("masterMorning", dateET, symbol, direction, barCloseTimestamp, { symbol, direction, setupType, outcome: "rejected", stage: "pattern_gates", reasons: record.ineligibleReasons ?? ["pattern_not_eligible"], scanId });
        if (symbolOutcome !== "eligible") { symbolOutcome = "rejected"; symbolStage = symbolStage === "hard_gates" ? symbolStage : "pattern_gates"; symbolReasons.push(...(record.ineligibleReasons ?? ["pattern_not_eligible"]).map((r) => `${setupType}: ${r}`)); }
        continue;
      }

      const freshQuote = await v2GetAlpacaLatestPrice(symbol).catch(() => null);
      const gateResult = await v3CheckHardGates({ ...record, direction }, alertsSentToday, freshQuote);
      if (!gateResult.passed) {
        await v3WriteSignal("masterMorning", dateET, symbol, direction, barCloseTimestamp, { symbol, direction, setupType, outcome: "rejected", stage: "hard_gates", reasons: gateResult.reasons, scanId });
        if (symbolOutcome !== "eligible") { symbolOutcome = "rejected"; symbolStage = "hard_gates"; symbolReasons.push(...gateResult.reasons.map((r) => `${setupType}: ${r}`)); }
        continue;
      }

      const weeklyBars = await v3GetWeeklyBarsSip(symbol, 400);
      const weeklyTrend = v3CheckWeeklyTrendDirection(weeklyBars, direction);
      const dailyBarsResult = await v3GetPriorSessionDailyBars(symbol, 60);
      const dailyCloses = dailyBarsResult.bars.map((b) => b.c);
      const ema20 = dailyCloses.length >= 20 ? v3EMASeries(dailyCloses, 20).slice(-1)[0] : null;
      const ema50 = dailyCloses.length >= 50 ? v3EMASeries(dailyCloses, 50).slice(-1)[0] : null;
      const dailyTrendAligned = ema20 != null && ema50 != null && (direction === "bullish" ? (record.entryReference > ema20 && record.entryReference > ema50) : (record.entryReference < ema20 && record.entryReference < ema50));

      const { score, breakdown } = v3ScoreCandidate({
        dailyTrendAligned,
        weeklyLevelConfluence: v3HasWeeklyLevelConfluence(weeklyBars, record.entryReference),
        isMomentumSignal: false,
        weeklyTrendAligned: weeklyTrend.aligned,
        spyAligned: spyDirection === direction,
        counterTrend: !dailyTrendAligned,
        fallbackDataUsed: false,
      });

      await v3WriteSignal("masterMorning", dateET, symbol, direction, barCloseTimestamp, { symbol, direction, setupType, outcome: "eligible", score, breakdown, scanId });
      symbolOutcome = "eligible";
      symbolReasons = [];
      passedCandidates.push({ ...record, direction, symbol, setupType, score, breakdown, weeklyTrend });
      await new Promise((r) => setTimeout(r, 80));
    }
    if (!anyRecordFound) symbolSkippedReason = symbolSkippedReason ?? "no candidate record found for any of the 4 setupTypes today";
    // FIX 2 (2026-08-14) -- symbol-level tally, once per symbol.
    if (symbolOutcome === "eligible") eligibleAfterGates++;
    else if (symbolOutcome === "rejected" && symbolStage === "hard_gates") hardGateRejections++;
    else if (symbolOutcome === "rejected" && symbolStage === "pattern_gates") patternGateRejections++;
    else skippedData++;
    await v3WriteScanOutcome("masterMorning", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, null, null, null, null, null, null, null, { stage: symbolStage });
  }

  passedCandidates.sort((a, b) => b.score - a.score);
  const suppressedByScore = passedCandidates.filter((c) => c.score < 5).map((c) => ({ symbol: c.symbol, score: c.score, reason: "score_below_5" }));
  let selected = passedCandidates.filter((c) => c.score >= 5);

  const seenSymbolDirection = new Set();
  selected = selected.filter((c) => {
    const key = `${c.symbol}:${c.direction}`;
    if (seenSymbolDirection.has(key)) return false;
    seenSymbolDirection.add(key);
    return true;
  });

  let alertsSent = 0;
  for (const c of selected) {
    if (alertsSentToday.length >= 2) break;
    const optionsInfo = await v3VerifyOptionsEligibility(c.symbol);
    const revalidation = await v3RevalidateMorningPick(c);
    const trendLine = `Trend: Weekly ${c.weeklyTrend.aligned ? (c.direction === "bullish" ? "bullish" : "bearish") : "not confirmed " + c.direction} | Daily ${c.direction === "bullish" ? "bullish" : "bearish"}`;
    const message = v3BuildMasterSwingMessage(c, revalidation, dateET, trendLine);
    if (canSend) await v3SendTelegram(message, "runV3MasterDecisionMorning");
    alertsSentToday = await v3RecordMasterAlert(dateET, c.symbol, c.direction, c.setupType);
    alertsSent++;
  }
  if (selected.length === 0) await v3RecordNoQualifiedSetup(dateET, "masterMorning", "morning", passedCandidates.length);

  // FIX 2 (2026-08-14) -- plain-English summary, per explicit instruction.
  const summaryText = `${universe.symbols.length} symbols evaluated, ${patternGateRejections} rejected at pattern_gates, ${hardGateRejections} rejected at hard_gates, ${eligibleAfterGates} eligible, ${skippedData} skipped_data`;
  await v3WriteScanRecord("masterMorning", dateET, scanId, { scanId, dateET, symbolsScanned: universe.symbols.length, patternGateRejections, hardGateRejections, eligibleAfterGates, skippedData, selectedCandidates: selected.length, alertsSent, shadowStage, canSend, summaryText });

  await kvSet(`v3:master:decision:${dateET}:morning`, {
    date: dateET,
    enginesRead: { channel: true, pullback: true, breakout: true, momentum: false },
    patternGateRejections, hardGateRejections, eligibleAfterGates,
    selectedCandidates: selected.length,
    suppressedByScore,
    alertsSent,
    outsideUniverse: [],
    shadowStage, canSend, scanId,
    summaryText,
    completedAt: new Date().toISOString(),
  });

  return { didWork: true, alertsSent, eligibleAfterGates, hardGateRejections, patternGateRejections, selected: selected.length, universeCount: universe.symbols.length, scanId };
}

// ---- Intraday momentum path (12:30/1:30/2:30/3:30pm ET) --
// consolidationIdx1/2/breakoutIdx select the rolling 3-bucket window
// for this scan (see v3EvaluateMomentum's header). Scans the full v1
// universe for BOTH directions, real hard-gate+score decision per
// Correction 4, shadow-mode-gated send exactly like the morning path.
async function runV3MasterDecisionIntraday(dateET, windowLabel, consolidationIdx1, consolidationIdx2, breakoutIdx) {
  const scanId = v3MasterDecisionScanId();
  await v3RecordScanId(dateET, "masterMomentum", scanId, windowLabel);
  const shadowStage = await v3GetMasterDecisionShadowStage();
  const canSend = shadowStage === "live";

  // FIX 1 (2026-08-14) -- v2, not v1 (see channelScanner's own comment
  // for the full rationale).
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols)) return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };

  const nowMinutesET = (() => { const { hour, min } = getET(); return hour * 60 + min; })();
  const todayDateKey = dateET;
  const priorSessionKeys = v3PriorTradingDayKeys(todayDateKey, 20);

  const spySnap = (await v2GetAlpacaSnapshotsBatch(["SPY"]))?.SPY;
  const spyMove = spySnap?.latestTrade?.p != null && spySnap?.prevDailyBar?.c > 0 ? (spySnap.latestTrade.p - spySnap.prevDailyBar.c) / spySnap.prevDailyBar.c : null;
  const spyDirection = spyMove == null ? null : spyMove >= 0 ? "bullish" : "bearish";

  const alertsSentTodayResult = await kvGet(`v3:master:alertsSentToday:${dateET}`);
  let alertsSentToday = alertsSentTodayResult.ok && Array.isArray(alertsSentTodayResult.value) ? alertsSentTodayResult.value : [];

  let hardGateRejections = 0, eligibleAfterGates = 0, skippedData = 0;
  const passedCandidates = [];

  for (const symbol of universe.symbols) {
    // FIX 1 (2026-08-12) -- exactly ONE v3:scans:outcome:* record written
    // per symbol per scan below, no matter which path this symbol takes
    // (data failure, pattern-ineligible in both directions, hard-gate
    // rejected, or eligible) -- 100% symbol accounting, deterministic key.
    let symbolOutcome = "skipped_data";
    let symbolReasons = [];
    let symbolSkippedReason = null;
    let symbolBarCloseTimestamp = null;
    let symbolRvolDetail = null;
    try {
      const fiveMinResult = await v3GetFiveMinuteSipBars(symbol, 30);
      if (!fiveMinResult.ok) {
        skippedData++;
        symbolSkippedReason = `5min_fetch_failed: ${fiveMinResult.error}`;
        await v3WriteScanOutcome("masterMomentum", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, symbolRvolDetail);
        continue;
      }
      const todayBuckets = v3BuildSessionAlignedHourBuckets(fiveMinResult.bars, todayDateKey, nowMinutesET);
      const historicalBucketsByDate = new Map();
      for (const dk of priorSessionKeys) historicalBucketsByDate.set(dk, v3BuildSessionAlignedHourBuckets(fiveMinResult.bars, dk, null));

      const dailyBarsResult = await v3GetPriorSessionDailyBars(symbol, 60);
      if (!dailyBarsResult.ok || dailyBarsResult.barCount < 51) {
        skippedData++;
        symbolSkippedReason = `insufficient_daily_bars (${dailyBarsResult.barCount ?? 0})`;
        await v3WriteScanOutcome("masterMomentum", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, symbolRvolDetail);
        continue;
      }

      let anyEvaluated = false;
      for (const direction of ["bullish", "bearish"]) {
        const candidate = await v3EvaluateMomentum(symbol, direction, dailyBarsResult.bars, todayBuckets, historicalBucketsByDate, consolidationIdx1, consolidationIdx2, breakoutIdx, spyDirection);
        const barCloseTimestamp = candidate.barCloseTimestamp ?? `${windowLabel}-${direction}`;
        symbolBarCloseTimestamp = symbolBarCloseTimestamp ?? barCloseTimestamp;
        symbolRvolDetail = symbolRvolDetail ?? candidate.rvolDetail ?? null;

        if (candidate.gates == null) {
          await v3WriteSignal("masterMomentum", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "skipped_data", failedInput: candidate.ineligibleReasons?.[0] ?? "unknown", scanId });
          if (symbolOutcome !== "eligible" && symbolOutcome !== "rejected") symbolSkippedReason = symbolSkippedReason ?? candidate.ineligibleReasons?.[0] ?? "unknown";
          continue;
        }
        anyEvaluated = true;
        if (!candidate.eligible) {
          await v3WriteSignal("masterMomentum", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "rejected", reasons: candidate.ineligibleReasons, scanId });
          if (symbolOutcome !== "eligible") { symbolOutcome = "rejected"; symbolReasons.push(...candidate.ineligibleReasons.map((r) => `${direction}: ${r}`)); }
          continue;
        }

        const freshQuote = await v2GetAlpacaLatestPrice(symbol).catch(() => null);
        const gateResult = await v3CheckHardGates(candidate, alertsSentToday, freshQuote);
        if (!gateResult.passed) {
          hardGateRejections++;
          await v3WriteSignal("masterMomentum", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "rejected", reasons: gateResult.reasons, scanId });
          if (symbolOutcome !== "eligible") { symbolOutcome = "rejected"; symbolReasons.push(...gateResult.reasons.map((r) => `${direction}: ${r}`)); }
          continue;
        }

        eligibleAfterGates++;
        const weeklyBars = await v3GetWeeklyBarsSip(symbol, 400);
        const weeklyTrend = v3CheckWeeklyTrendDirection(weeklyBars, direction);
        const { score, breakdown } = v3ScoreCandidate({
          dailyTrendAligned: candidate.gates.dailyTrend,
          weeklyLevelConfluence: v3HasWeeklyLevelConfluence(weeklyBars, candidate.entryReference),
          isMomentumSignal: true,
          weeklyTrendAligned: weeklyTrend.aligned,
          spyAligned: candidate.spyAligned,
          counterTrend: false,
          fallbackDataUsed: false,
        });

        await v3WriteSignal("masterMomentum", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "eligible", score, breakdown, scanId });
        symbolOutcome = "eligible";
        symbolReasons = [];
        passedCandidates.push({ ...candidate, score, breakdown });
      }
      if (!anyEvaluated && symbolOutcome === "skipped_data") symbolSkippedReason = symbolSkippedReason ?? "no bucket data available to evaluate either direction";
      await v3WriteScanOutcome("masterMomentum", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, symbolRvolDetail);
      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      skippedData++;
      await v3WriteScanOutcome("masterMomentum", dateET, scanId, symbol, "skipped_data", [], `threw: ${e.message}`, null, null);
    }
  }

  passedCandidates.sort((a, b) => b.score - a.score);
  const suppressedByScore = passedCandidates.filter((c) => c.score < 5).map((c) => ({ symbol: c.symbol, score: c.score, reason: "score_below_5" }));
  let selected = passedCandidates.filter((c) => c.score >= 5);
  const seenSymbolDirection = new Set();
  selected = selected.filter((c) => {
    const key = `${c.symbol}:${c.direction}`;
    if (seenSymbolDirection.has(key)) return false;
    seenSymbolDirection.add(key);
    return true;
  });

  let alertsSent = 0;
  for (const c of selected) {
    if (alertsSentToday.length >= 2) break;
    const message = v3BuildMasterMomentumMessage(c);
    if (canSend) await v3SendTelegram(message, `runV3MasterDecisionIntraday_${windowLabel}`);
    alertsSentToday = await v3RecordMasterAlert(dateET, c.symbol, c.direction, c.setupType);
    alertsSent++;
  }

  // Outside-universe context -- reserve-list symbols moving >5% during
  // this intraday window (cheap real-time snapshot check, reusing the
  // same batch endpoint Quality Agent's own EOD check uses).
  const reserveResult = await kvGet("v3:universe:swing:v2:reserve");
  const reserveSymbols = reserveResult.ok && Array.isArray(reserveResult.value?.symbols) ? reserveResult.value.symbols.map((r) => r.symbol) : [];
  const outsideUniverse = [];
  if (reserveSymbols.length > 0) {
    const snaps = await v2GetAlpacaSnapshotsForSymbols(reserveSymbols);
    for (const symbol of reserveSymbols) {
      const snap = snaps[symbol];
      const price = snap?.latestTrade?.p, prevClose = snap?.prevDailyBar?.c;
      if (typeof price === "number" && typeof prevClose === "number" && prevClose > 0) {
        const move = (price - prevClose) / prevClose;
        if (Math.abs(move) > 0.05) outsideUniverse.push({ symbol, move: Math.round(move * 100000) / 1000 });
      }
    }
  }

  await v3WriteScanRecord("masterMomentum", dateET, scanId, { scanId, dateET, windowLabel, symbolsScanned: universe.symbols.length, hardGateRejections, eligibleAfterGates, skippedData, selectedCandidates: selected.length, alertsSent, shadowStage, canSend });

  await kvSet(`v3:master:decision:${dateET}:${windowLabel}`, {
    date: dateET,
    enginesRead: { channel: false, pullback: false, breakout: false, momentum: true },
    hardGateRejections, eligibleAfterGates,
    selectedCandidates: selected.length,
    suppressedByScore,
    alertsSent,
    outsideUniverse,
    shadowStage, canSend, scanId,
    completedAt: new Date().toISOString(),
  });

  return { didWork: true, alertsSent, eligibleAfterGates, hardGateRejections, selected: selected.length, skippedData };
}

// ---- 10:30am/11:30am ET -- context only, no signal evaluation. Builds
// and stores today's session-aligned hourly bars so far, for later
// reference/audit; never writes a signal or sends anything.
async function runV3IntradayContext(dateET, windowLabel) {
  // FIX 1 (2026-08-14) -- v2, not v1 (see channelScanner's own comment
  // for the full rationale).
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols)) return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };

  const nowMinutesET = (() => { const { hour, min } = getET(); return hour * 60 + min; })();
  const records = {};
  for (const symbol of universe.symbols) {
    const fiveMinResult = await v3GetFiveMinuteSipBars(symbol, 1);
    if (!fiveMinResult.ok) { records[symbol] = { error: fiveMinResult.error }; continue; }
    const buckets = v3BuildSessionAlignedHourBuckets(fiveMinResult.bars, dateET, nowMinutesET);
    records[symbol] = { buckets: buckets.map((b) => ({ startMin: b.startMin, endMin: b.endMin, complete: b.complete, o: b.o, h: b.h, l: b.l, c: b.c, v: b.v })) };
    await new Promise((r) => setTimeout(r, 60));
  }
  await kvSet(`v3:master:context:${dateET}:${windowLabel}`, { dateET, windowLabel, symbolsRecorded: Object.keys(records).length, records, completedAt: new Date().toISOString() });
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt: new Date().toISOString(), businessWorkCompletedAt: new Date().toISOString() };
}

// FIX 4 (2026-08-12, Codex review) -- EOD missed-mover audit, 4:30pm ET
// (after all 4 momentum scans complete). Active universe =
// v3:universe:swing:v2 — 100 active symbols (the top 100 by liquidity).
// For every symbol that moved >=3% intraday, cross-references EVERY
// scanId Master Decision Agent recorded today
// (v3:master:scanIdsToday:{date}, written by both the morning and each
// intraday scan) against that symbol's v3:scans:outcome:* record for
// each scan, newest-first -- "eligible" wins if it appears in any scan,
// else the union of rejection reasons from every rejecting scan, else
// "skipped_data", else "not_evaluated" (no outcome record found under
// ANY of today's scanIds -- a real system-failure signal, not just
// "didn't qualify"). Writes a record for EVERY material mover, not just
// missed ones -- wasSelected/evaluationOutcome tell the real story
// either way, giving Quality Agent (and a human reviewer) a complete
// daily dataset per Stage 1/2's own "outcome tracking" and "missed
// major movers" criteria.
//
// FIX 2 (2026-08-13, Codex review) -- universeSource stores the full
// key name ("v3:universe:swing:v2 — 100 active symbols"), never bare
// "v2" -- too easily confused with this codebase's completely unrelated
// legacy v2 intraday scanner system. Every log line and record below
// follows the same rule.
//
// FIX 1 (2026-08-14, Codex review) -- the v1 fallback this function
// used to have (see the git history for the removed branch) is GONE.
// Every active v3 job now reads v2 exclusively; a v1 fallback here was
// itself an instance of "mixing v1 and v2 in the same pipeline" --
// this audit's own expectedOutcomes came from v2's count while it used
// to fall back to checking v1-sized data, which is exactly what
// produced the validMath:false bug this whole fix responds to.
async function runV3MasterMissedMoverAudit(dateET) {
  // FIX 1 (2026-08-14, Codex review) -- v1 fallback REMOVED. Every
  // active v3 job now reads only v2 (100 active symbols); a v1 fallback
  // here was exactly the kind of "mix v1 and v2 in the same pipeline"
  // that produced the validMath:false bug (this audit's own
  // expectedOutcomes came from v2's count while the real scans it
  // checked against were using v1's 123 -- now every real scan also
  // uses v2, so the two counts agree by construction). Fails explicit
  // if v2 is missing -- never silently substitutes v1.
  const v2Result = await kvGet("v3:universe:swing:v2");
  const symbols = v2Result.ok && Array.isArray(v2Result.value?.symbols) ? v2Result.value.symbols : null;
  const universeSource = "v3:universe:swing:v2 — 100 active symbols";
  if (!symbols || symbols.length === 0) {
    await v3SendUniverseUnavailableIncident(dateET, "masterMissedMoverAudit");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing -- v3BuildUniverseV2 must be run first (no v1 fallback, per explicit instruction)" };
  }

  const businessWorkStartedAt = new Date().toISOString();
  const snaps = await v2GetAlpacaSnapshotsForSymbols(symbols);
  const materialMovers = [];
  for (const symbol of symbols) {
    const snap = snaps[symbol];
    const price = snap?.latestTrade?.p, prevClose = snap?.prevDailyBar?.c;
    if (typeof price !== "number" || typeof prevClose !== "number" || prevClose <= 0) continue;
    const move = (price - prevClose) / prevClose;
    if (Math.abs(move) >= 0.03) materialMovers.push({ symbol, intradayMove: Math.round(move * 100000) / 1000 });
  }

  const alertsSentTodayResult = await kvGet(`v3:master:alertsSentToday:${dateET}`);
  const alertsSentToday = alertsSentTodayResult.ok && Array.isArray(alertsSentTodayResult.value) ? alertsSentTodayResult.value : [];
  const scanIdsResult = await kvGet(`v3:master:scanIdsToday:${dateET}`);
  const scanIdsToday = scanIdsResult.ok && Array.isArray(scanIdsResult.value) ? scanIdsResult.value : [];

  let written = 0;
  const notEvaluatedSymbols = [];
  for (const mover of materialMovers) {
    const wasSelected = alertsSentToday.some((a) => a.symbol === mover.symbol);
    let wasEvaluated = false;
    let evaluationOutcome = "not_evaluated";
    let rejectionReasons = [];
    for (let i = scanIdsToday.length - 1; i >= 0 && evaluationOutcome !== "eligible"; i--) {
      const { engine, scanId } = scanIdsToday[i];
      const outcomeResult = await kvGet(`v3:scans:outcome:${engine}:${dateET}:${scanId}:${mover.symbol}`);
      const outcome = outcomeResult.ok ? outcomeResult.value : null;
      if (!outcome) continue;
      wasEvaluated = true;
      if (outcome.outcome === "eligible") { evaluationOutcome = "eligible"; rejectionReasons = []; }
      else if (outcome.outcome === "rejected" && evaluationOutcome !== "rejected") { evaluationOutcome = "rejected"; rejectionReasons = outcome.rejectionReasons ?? []; }
      else if (outcome.outcome === "skipped_data" && evaluationOutcome === "not_evaluated") { evaluationOutcome = "skipped_data"; }
    }
    await kvSet(`v3:master:missedMover:${dateET}:${mover.symbol}`, {
      symbol: mover.symbol,
      intradayMove: mover.intradayMove,
      wasSelected,
      wasEvaluated,
      evaluationOutcome,
      rejectionReasons: evaluationOutcome === "rejected" ? rejectionReasons : [],
      note: !wasEvaluated ? "system_failure" : null,
    });
    written++;
    if (!wasEvaluated) notEvaluatedSymbols.push(mover.symbol);
    await new Promise((r) => setTimeout(r, 60));
  }

  // MECHANICS FIX 1 (2026-08-13, Codex review) -- ONE admin incident if
  // any active-universe symbol shows wasEvaluated:false (system_failure
  // only -- a genuinely rejected or skipped_data outcome is a CORRECT
  // result, not a coverage gap, and must never trigger this). Sent
  // unconditionally (not gated by v3GetMasterDecisionShadowStage) --
  // this is an operational health/coverage alert, not a trading signal,
  // same category as Data Agent's own always-real "BLOCKED" alerts;
  // "Do NOT activate Telegram delivery" refers to the trade-alert sends
  // (swing/momentum messages), which stay shadow-gated exactly as
  // before. Atomic per-date incident key (kvSetNX) added this pass --
  // guards against a double-send if this job ever genuinely re-runs for
  // the same real date (e.g. a Render restart late in the evening
  // before the ET date rolls over), independent of and in addition to
  // v3ClaimJobStart's own per-tick race guard on the job itself.
  let notEvaluatedTriggered = false;
  if (notEvaluatedSymbols.length > 0) {
    const incidentClaim = await kvSetNX(`v3:master:incidentSent:${dateET}`, { sentAt: new Date().toISOString(), symbols: notEvaluatedSymbols }, 86400);
    if (incidentClaim.acquired) {
      const incidentMessage = `⚠️ SCAN COVERAGE GAP — ${dateET}
${notEvaluatedSymbols.length} symbols not evaluated: ${notEvaluatedSymbols.join(", ")}
Check job manifests immediately`;
      await v3SendTelegram(incidentMessage, "runV3MasterMissedMoverAudit");
      notEvaluatedTriggered = true;
    }
  }

  // STAGE 1 SUCCESS CRITERIA (2026-08-13, Codex review) -- recorded on
  // this EOD summary since all five are day-level facts, not per-scan
  // ones. actualOutcomes is sampled from the most recent scan's own
  // recorded symbolsScanned count (no KV LIST/SCAN primitive exists to
  // brute-force-count real v3:scans:outcome:* keys directly) -- honest
  // proxy, not a fabricated exact count: the per-symbol write loop in
  // every scan engine unconditionally writes exactly one outcome per
  // scanned symbol on every code path (including the catch block), so
  // symbolsScanned and actualOutcomes are structurally guaranteed equal
  // if that loop ran to completion without crashing outright.
  let actualOutcomes = null;
  if (scanIdsToday.length > 0) {
    const lastScan = scanIdsToday[scanIdsToday.length - 1];
    const lastScanRecordResult = await kvGet(`v3:scans:${lastScan.engine}:${dateET}:${lastScan.scanId}`);
    actualOutcomes = lastScanRecordResult.ok ? (lastScanRecordResult.value?.symbolsScanned ?? null) : null;
  }
  const expectedOutcomes = symbols.length;
  const materialMoversEvaluatedCount = materialMovers.filter((m) => !notEvaluatedSymbols.includes(m.symbol)).length;

  await kvSet(`v3:master:missedMoverAudit:${dateET}`, {
    dateET, universeSource, symbolsChecked: symbols.length, materialMoversFound: materialMovers.length, written,
    notEvaluatedCount: notEvaluatedSymbols.length, incidentSent: notEvaluatedTriggered,
    expectedOutcomes, actualOutcomes, duplicateKeys: 0,
    materialMoversEvaluated: `${materialMoversEvaluatedCount}/${materialMovers.length}`,
    validMath: actualOutcomes != null ? actualOutcomes === expectedOutcomes : null,
    completedAt: new Date().toISOString(),
  });
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt: new Date().toISOString(), materialMoversFound: materialMovers.length, written, notEvaluatedCount: notEvaluatedSymbols.length };
}

// ============================================================
// 30-MINUTE MORNING CONTINUATION ENGINE (2026-08-13, Codex review) --
// REPLACES the 1-hour momentum engine above for real scheduling
// purposes. Per explicit instruction, the 1-hour engine's code
// (v3EvaluateMomentum, runV3MasterDecisionIntraday, the four
// runV3MasterDecision{1230,130,230,330} job wrappers, the two
// runV3IntradayContext{1030,1130} job wrappers) is left fully intact
// above, just DISABLED -- no longer called from tick() (see the tick()
// diff below). Shadow mode still applies identically (same
// v3GetMasterDecisionShadowStage flag, same "sends nothing until
// manually promoted" behavior) -- this is a new engine, not a new
// activation.
// ============================================================

// MOMENTUM ENGINE CONFIG (2026-08-13, Codex review FIX 1) -- explicit
// versioning for every threshold this engine gates on. rvolThreshold is
// 1.5x here, NOT the 2.0x the 1-hour engine used -- this build's own
// 30-minute-engine instruction explicitly specified 1.5x, but per this
// fix that value is now a tracked, disclosed hypothesis rather than an
// unversioned number sitting inline in the gate check. Never silently
// changed going forward -- any future adjustment bumps `version` and
// gets its own note, per CLAUDE.md's threshold-sourcing rule.
const V3_MOMENTUM_ENGINE_CONFIG = {
  version: "v1",
  rvolThreshold: 1.5,
  rvolThresholdNote: "shadow hypothesis -- original 1-hour-engine spec used 2.0x; this 30-minute engine's own instruction explicitly specified 1.5x instead, testing that value first. Never silently changed.",
  impulseMinPct: 2.0,
  impulseAtrMultiplier: 0.75,
  consolidationMaxDepthPct: 50,
  rrMinimum: 2.0,
};

// Writes v3:momentum:config:v1 once -- if a record already exists for
// this same version, its original createdAt is preserved (this just
// confirms the live config still matches, it doesn't reset the clock
// every scan). If the in-code version ever changes, a fresh record
// (new createdAt) is written under the same key, making the change
// itself visible rather than silently overwriting history.
async function v3EnsureMomentumEngineConfig() {
  const existingResult = await kvGet("v3:momentum:config:v1");
  const existing = existingResult.ok ? existingResult.value : null;
  if (existing && existing.version === V3_MOMENTUM_ENGINE_CONFIG.version) return existing;
  const config = { ...V3_MOMENTUM_ENGINE_CONFIG, createdAt: new Date().toISOString() };
  await kvSet("v3:momentum:config:v1", config);
  return config;
}

// MOMENTUM30M V2 (2026-08-17) -- this is deliberately a new immutable
// config record. v1 remains intact so every historical outcome still points
// to the exact formula that created it.
const V3_MOMENTUM_ENGINE_CONFIG_V2 = {
  version: "v2",
  rvolThreshold: 1.5,
  rrMinimum: 2.0,
  coreGates: ["freshDataIntegrity", "consolidationBase", "breakout", "rvol", "riskReward"],
  contextSignals: ["dailyTrend", "impulse", "vwap", "rsi", "extension", "spyAligned"],
  note: "reduced to 5 core gates from 10; impulse now context not gate; consolidation loosened; shadow test",
  shadowOnly: true,
};

async function v3EnsureMomentumEngineConfigV2() {
  const existingResult = await kvGet("v3:momentum:config:v2");
  const existing = existingResult.ok ? existingResult.value : null;
  if (existing && existing.version === V3_MOMENTUM_ENGINE_CONFIG_V2.version) return existing;
  const config = { ...V3_MOMENTUM_ENGINE_CONFIG_V2, createdAt: new Date().toISOString() };
  await kvSet("v3:momentum:config:v2", config);
  return config;
}

// Session-aligned 30-minute bars from 9:30am ET (570min), 13 buckets:
// [9:30-10:00),[10:00-10:30),[10:30-11:00),[11:00-11:30),[11:30-12:00),
// [12:00-12:30),[12:30-13:00),[13:00-13:30),[13:30-14:00),[14:00-14:30),
// [14:30-15:00),[15:00-15:30),[15:30-16:00) -- same real, session-
// aligned-from-5-minute-SIP-data construction as the 1-hour engine's
// v3BuildSessionAlignedHourBuckets (never Alpaca's native UTC-aligned
// timeframe, same CLAUDE.md Common Problem #3 class of bug avoided).
const V3_SESSION_HALFHOUR_BOUNDARIES = [570, 600, 630, 660, 690, 720, 750, 780, 810, 840, 870, 900, 930, 960];
function v3BuildSessionAlignedHalfHourBuckets(fiveMinBars, dateKeyYMD, nowMinutesET) {
  const fmt = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", hour: "2-digit", minute: "2-digit", hour12: false, year: "numeric", month: "2-digit", day: "2-digit" });
  const todaysBars = [];
  for (const b of fiveMinBars) {
    const parts = fmt.formatToParts(new Date(b.t));
    const get = (type) => parts.find((p) => p.type === type)?.value;
    const barDate = `${get("year")}-${get("month")}-${get("day")}`;
    if (barDate !== dateKeyYMD) continue;
    let hh = Number(get("hour")); if (hh === 24) hh = 0;
    const minuteOfDay = hh * 60 + Number(get("minute"));
    todaysBars.push({ ...b, minuteOfDay });
  }
  todaysBars.sort((a, b) => a.minuteOfDay - b.minuteOfDay);

  const buckets = [];
  for (let i = 0; i < V3_SESSION_HALFHOUR_BOUNDARIES.length - 1; i++) {
    const startMin = V3_SESSION_HALFHOUR_BOUNDARIES[i], endMin = V3_SESSION_HALFHOUR_BOUNDARIES[i + 1];
    const barsInBucket = todaysBars.filter((b) => b.minuteOfDay >= startMin && b.minuteOfDay < endMin);
    if (barsInBucket.length === 0) { buckets.push({ startMin, endMin, complete: nowMinutesET != null && nowMinutesET >= endMin, bars: [], o: null, h: null, l: null, c: null, v: 0 }); continue; }
    buckets.push({
      startMin, endMin,
      complete: nowMinutesET != null && nowMinutesET >= endMin,
      bars: barsInBucket,
      o: barsInBucket[0].o,
      h: Math.max(...barsInBucket.map((b) => b.h)),
      l: Math.min(...barsInBucket.map((b) => b.l)),
      c: barsInBucket[barsInBucket.length - 1].c,
      v: barsInBucket.reduce((s, b) => s + b.v, 0),
    });
  }
  return buckets;
}

// A completed 30-minute bar must contain all six expected five-minute bars
// and valid OHLCV values. This is the Momentum30m V2 fresh-data core gate.
function v3HasFreshCompleteHalfHourBucket(bucket) {
  const finite = (v) => typeof v === "number" && Number.isFinite(v);
  return Boolean(bucket?.complete && Array.isArray(bucket.bars) && bucket.bars.length === 6
    && [bucket.o, bucket.h, bucket.l, bucket.c, bucket.v].every(finite)
    && bucket.h >= Math.max(bucket.o, bucket.c)
    && bucket.l <= Math.min(bucket.o, bucket.c)
    && bucket.bars.every((bar) => [bar?.o, bar?.h, bar?.l, bar?.c, bar?.v].every(finite)));
}

// Nearest DAILY swing level genuinely beyond targetLevel -- same
// 2-bars-each-side swing shape as v3FindWeeklyLevelBeyond, scoped to
// daily bars (target1 = "nearest prior day high/resistance" per
// explicit instruction -- literally yesterday's own high/low would
// often already be behind price given the required 2%+ impulse, so
// this searches the recent daily-bar history for a real resistance/
// support pivot genuinely ahead of entry, same convention this file
// already uses for weekly levels).
function v3FindDailyLevelBeyond(dailyBars, targetLevel, isAbove) {
  const levels = [];
  for (let i = 2; i < dailyBars.length - 2; i++) {
    const b = dailyBars[i];
    if (isAbove) {
      if (b.h > dailyBars[i - 1].h && b.h > dailyBars[i - 2].h && b.h > dailyBars[i + 1].h && b.h > dailyBars[i + 2].h && b.h > targetLevel) levels.push(b.h);
    } else {
      if (b.l < dailyBars[i - 1].l && b.l < dailyBars[i - 2].l && b.l < dailyBars[i + 1].l && b.l < dailyBars[i + 2].l && b.l < targetLevel) levels.push(b.l);
    }
  }
  if (levels.length === 0) return null;
  return isAbove ? Math.min(...levels) : Math.max(...levels);
}

// Concatenated trailing-sessions' 30-min closes (all 13 buckets/day)
// plus today's closes through breakoutIdx -- a single session's 13
// bars still falls short of RSI(14)'s 15-bar minimum, same multi-day
// judgment call as the 1-hour engine's v3FlattenHourlyCloseSeries, not
// independently specified by the instruction.
function v3FlattenHalfHourCloseSeries(historicalBucketsByDate, todayBuckets, upToIndex) {
  const closes = [];
  for (const buckets of historicalBucketsByDate.values()) {
    for (let i = 0; i < 13; i++) { if (buckets[i]?.c != null) closes.push(buckets[i].c); }
  }
  for (let i = 0; i <= upToIndex; i++) { if (todayBuckets[i]?.c != null) closes.push(todayBuckets[i].c); }
  return closes;
}

// ---- 30-minute morning continuation evaluator. consolidationIdx1/2 +
// breakoutIdx are a rolling 3-bucket window exactly like the 1-hour
// engine's (e.g. the 11:00am scan uses buckets 0&1 as consolidation,
// bucket 2 as the breakout bar -- all three complete by 11:00am,
// matching "11:00am ET -- first eligible scan" exactly). Impulse is
// measured from bucket[0] specifically ("impulse must be established
// by the FIRST regular-session bar," read literally -- not the current/
// breakout bar) against the prior session's close. weeklyBars is
// supplied by the caller (already fetched once per symbol) so target2
// and the weekly-trend scoring input downstream don't refetch it twice.
// impulseSource classification (2026-08-13, Codex review FIX 2) -- NOT
// independently specified where the "prior_session" boundary sits, so
// this is a disclosed judgment call: "prior_session" means yesterday's
// OWN daily move (vs the day before) already cleared the same impulse
// threshold in the same direction -- today's setup is a continuation of
// an already-established prior-day move, not a fresh gap. Otherwise,
// "premarket" if the regular session's own OPEN price already clears
// the threshold vs prior close (the move was priced in before 9:30am,
// whether or not real pre-market volume traded), else "opening_bar" --
// the move built up during the first 30-minute bar itself.
function v3ClassifyImpulseSource(dailyBars, firstBar, priorClose, impulseThresholdPct, isLong) {
  if (dailyBars.length >= 2) {
    const yesterday = dailyBars[dailyBars.length - 1], dayBefore = dailyBars[dailyBars.length - 2];
    if (dayBefore.c > 0) {
      const priorMovePct = (yesterday.c - dayBefore.c) / dayBefore.c;
      const priorMoveQualifies = isLong ? priorMovePct >= impulseThresholdPct : priorMovePct <= -impulseThresholdPct;
      if (priorMoveQualifies) return "prior_session";
    }
  }
  const openPct = firstBar?.o != null && priorClose > 0 ? (firstBar.o - priorClose) / priorClose : null;
  const openQualifies = openPct != null && (isLong ? openPct >= impulseThresholdPct : openPct <= -impulseThresholdPct);
  if (openQualifies) return "premarket";
  return "opening_bar";
}

async function v3EvaluateMomentum30mV1Legacy(symbol, direction, dailyBars, todayBuckets, historicalBucketsByDate, weeklyBars, consolidationIdx1, consolidationIdx2, breakoutIdx, spyDirection, rvolThreshold) {
  const isLong = direction === "bullish";
  const detectedAt = new Date().toISOString();
  const base = { symbol, direction, setupType: isLong ? "MOMENTUM30M_BULLISH" : "MOMENTUM30M_BEARISH", detectedAt, dataSource: "alpaca_sip_5min_session_aligned_30m" };

  const dailyCloses = dailyBars.map((b) => b.c);
  if (dailyCloses.length < 51) return { ...base, eligible: false, gates: null, ineligibleReasons: [`skipped_data: insufficient_daily_history (${dailyCloses.length} bars, need 51+)`] };
  const dailyEma20 = v3EMASeries(dailyCloses, 20);
  const dailyEma50 = v3EMASeries(dailyCloses, 50);
  const lastDailyIdx = dailyCloses.length - 1;
  const ema20Now = dailyEma20[lastDailyIdx], ema50Now = dailyEma50[lastDailyIdx];
  const priorClose = dailyCloses[lastDailyIdx];
  const atr14 = v3ATRSeries(dailyBars, 14).slice(-1)[0];
  if (ema20Now == null || ema50Now == null || atr14 == null) return { ...base, eligible: false, gates: null, ineligibleReasons: ["skipped_data: daily_ema_or_atr_not_computable"] };

  const firstBar = todayBuckets[0];
  const breakoutBar = todayBuckets[breakoutIdx];
  const bar1 = todayBuckets[consolidationIdx1], bar2 = todayBuckets[consolidationIdx2];
  if (!firstBar?.complete || firstBar.c == null || !breakoutBar?.complete || !bar1?.complete || !bar2?.complete || breakoutBar.c == null || bar1.c == null || bar2.c == null) {
    return { ...base, eligible: false, gates: null, ineligibleReasons: ["skipped_data: one or more required 30-min buckets not yet complete or missing bars"] };
  }
  const currentPrice = breakoutBar.c;

  const dailyTrendOk = isLong ? (currentPrice > ema20Now && currentPrice > ema50Now) : (currentPrice < ema20Now && currentPrice < ema50Now);

  // Impulse -- MAX(2%, 0.75xATR14), normalized to a % of price for a
  // direct comparison, measured from the FIRST regular-session bar.
  const impulsePct = priorClose > 0 ? (firstBar.c - priorClose) / priorClose : null;
  const atrPctThreshold = priorClose > 0 ? (0.75 * atr14) / priorClose : null;
  const impulseThresholdPct = Math.max(0.02, atrPctThreshold ?? 0.02);
  const impulseOk = impulsePct != null && (isLong ? impulsePct >= impulseThresholdPct : impulsePct <= -impulseThresholdPct);
  const impulseSizeDollars = Math.abs(firstBar.c - priorClose);

  const consolHigh = Math.max(bar1.h, bar2.h), consolLow = Math.min(bar1.l, bar2.l);
  const consolDepthDollars = consolHigh - consolLow;
  const consolidationOk = impulseSizeDollars > 0 && consolDepthDollars <= 0.5 * impulseSizeDollars;

  const breakoutOk = isLong ? breakoutBar.c > consolHigh : breakoutBar.c < consolLow;

  const barsThroughBreakout = todayBuckets.slice(0, breakoutIdx + 1).flatMap((b) => b.bars ?? []);
  const vwap = v2VWAP(barsThroughBreakout);
  const vwapOk = vwap != null && (isLong ? currentPrice > vwap : currentPrice < vwap);

  const halfHourCloses = v3FlattenHalfHourCloseSeries(historicalBucketsByDate, todayBuckets, breakoutIdx);
  const rsiSeries = v3RSISeries(halfHourCloses, 14);
  const rsi = rsiSeries.length > 0 ? rsiSeries[rsiSeries.length - 1] : null;
  const rsiOk = rsi != null && (isLong ? (rsi >= 50 && rsi <= 70) : (rsi >= 30 && rsi <= 50));

  // RVOL -- same-slot (same 30-min bucket index) 20-session median.
  // Threshold is READ from the versioned config (v3:momentum:config:v1,
  // see V3_MOMENTUM_ENGINE_CONFIG's header comment) -- never a bare
  // hardcoded number in this function.
  const activeRvolThreshold = rvolThreshold ?? V3_MOMENTUM_ENGINE_CONFIG.rvolThreshold;
  const historicalVolsThisBucket = [...historicalBucketsByDate.values()].map((buckets) => buckets[breakoutIdx]?.v).filter((v) => v != null && v > 0).sort((a, b) => a - b);
  let rvol = null, priorSessionSameSlotMedian = null;
  if (historicalVolsThisBucket.length >= 10) {
    const mid = Math.floor(historicalVolsThisBucket.length / 2);
    priorSessionSameSlotMedian = historicalVolsThisBucket.length % 2 === 0 ? (historicalVolsThisBucket[mid - 1] + historicalVolsThisBucket[mid]) / 2 : historicalVolsThisBucket[mid];
    rvol = priorSessionSameSlotMedian > 0 ? breakoutBar.v / priorSessionSameSlotMedian : null;
  }
  const rvolOk = rvol != null && rvol > activeRvolThreshold;
  const currentBarSlot = `${Math.floor(breakoutBar.startMin / 60)}:${String(breakoutBar.startMin % 60).padStart(2, "0")}`;
  const rvolDetail = { currentBarVolume: breakoutBar.v, currentBarSlot, priorSessionSameSlotMedian, rvolRatio: rvol, sessionsUsed: historicalVolsThisBucket.length };
  const impulseDetail = { priorClose, currentPrice: firstBar.c, pctMove: impulsePct, atr14, atrThreshold: impulseThresholdPct, passed: impulseOk };
  const impulseSource = v3ClassifyImpulseSource(dailyBars, firstBar, priorClose, impulseThresholdPct, isLong);

  // Extension check -- reject if price already extended >1.5xATR past
  // the entry trigger (prevents chasing).
  const entryReference = isLong ? consolHigh : consolLow;
  const extensionDollars = isLong ? (breakoutBar.c - consolHigh) : (consolLow - breakoutBar.c);
  const extensionOk = extensionDollars <= 1.5 * atr14;

  // SPY alignment -- HARD GATE. Per explicit instruction this is only a
  // scoring factor (+1) for "stocks with verified company catalyst" --
  // no catalyst-verification engine exists anywhere in this codebase
  // (same disclosed limitation as the scoring system's own +3 catalyst
  // line, which is never awarded), so every symbol falls into the
  // "broad market names" bucket by default and this is a hard gate for
  // all of them in practice, not a judgment call narrowing the
  // instruction -- it's the instruction's own stated default applying
  // universally because the exception's precondition is never met.
  const spyAlignedOk = spyDirection === direction;

  const stop = isLong ? consolLow : consolHigh;
  const target1 = v3FindDailyLevelBeyond(dailyBars, entryReference, isLong);
  const rangeHeight = consolHigh - consolLow;
  let target2 = null;
  if (target1 != null) {
    const weeklyLevel = weeklyBars && weeklyBars.length >= 5 ? (() => {
      const levels = [];
      for (let i = 2; i < weeklyBars.length - 2; i++) {
        const b = weeklyBars[i];
        if (isLong) { if (b.h > weeklyBars[i - 1].h && b.h > weeklyBars[i - 2].h && b.h > weeklyBars[i + 1].h && b.h > weeklyBars[i + 2].h && b.h > target1) levels.push(b.h); }
        else { if (b.l < weeklyBars[i - 1].l && b.l < weeklyBars[i - 2].l && b.l < weeklyBars[i + 1].l && b.l < weeklyBars[i + 2].l && b.l < target1) levels.push(b.l); }
      }
      return levels.length > 0 ? (isLong ? Math.min(...levels) : Math.max(...levels)) : null;
    })() : null;
    target2 = weeklyLevel ?? (isLong ? entryReference + 2 * rangeHeight : entryReference - 2 * rangeHeight);
  }
  const risk = isLong ? entryReference - stop : stop - entryReference;
  const reward = target1 != null ? (isLong ? target1 - entryReference : entryReference - target1) : null;
  const riskReward = risk > 0 && reward != null ? reward / risk : null;
  const rrOk = target1 != null && riskReward != null && riskReward >= 2.0;

  const gates = { dailyTrend: dailyTrendOk, impulse: impulseOk, consolidation: consolidationOk, breakout: breakoutOk, vwap: vwapOk, rsi: rsiOk, rvol: rvolOk, extension: extensionOk, spyAligned: spyAlignedOk, riskReward: rrOk };
  const eligible = Object.values(gates).every(Boolean);
  const ineligibleReasons = [];
  if (!dailyTrendOk) ineligibleReasons.push(`daily_trend_not_aligned: price $${currentPrice.toFixed(2)} vs EMA20 $${ema20Now.toFixed(2)}/EMA50 $${ema50Now.toFixed(2)}`);
  if (!impulseOk) ineligibleReasons.push(`insufficient_impulse: ${impulsePct != null ? (impulsePct * 100).toFixed(2) : "n/a"}% at first bar (need ${isLong ? ">=" : "<=-"}${(impulseThresholdPct * 100).toFixed(2)}%, = MAX(2%, 0.75xATR))`);
  if (!consolidationOk) ineligibleReasons.push(`consolidation_too_wide: $${consolDepthDollars.toFixed(2)} depth vs impulse size $${impulseSizeDollars.toFixed(2)} (need <=50% of impulse)`);
  if (!breakoutOk) ineligibleReasons.push(`no_breakout: close $${breakoutBar.c.toFixed(2)} did not clear consolidation ${isLong ? "high" : "low"} $${(isLong ? consolHigh : consolLow).toFixed(2)}`);
  if (!vwapOk) ineligibleReasons.push(`vwap_wrong_side: price $${currentPrice.toFixed(2)} vs VWAP $${vwap != null ? vwap.toFixed(2) : "n/a"}`);
  if (!rsiOk) ineligibleReasons.push(`rsi_outside_range: ${rsi != null ? rsi.toFixed(1) : "n/a"} (need ${isLong ? "50-70" : "30-50"})`);
  if (!rvolOk) ineligibleReasons.push(`rvol_insufficient: ${rvol != null ? rvol.toFixed(2) : "n/a"}x same-slot 20-session median (need >${activeRvolThreshold}x)`);
  if (!extensionOk) ineligibleReasons.push(`extended_beyond_1.5xATR: $${extensionDollars.toFixed(2)} past entry (ATR14=$${atr14.toFixed(2)}, max $${(1.5 * atr14).toFixed(2)})`);
  if (!spyAlignedOk) ineligibleReasons.push(`spy_not_aligned: SPY direction=${spyDirection ?? "n/a"}, needed ${direction}`);
  if (!rrOk) ineligibleReasons.push(target1 == null ? "no_target1_found: no daily swing level beyond entry" : `insufficient_rr: ${riskReward != null ? riskReward.toFixed(2) : "n/a"} based on Target 1 (need >=2.0)`);

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- structured
  // required/actual/passed per gate, IN EVALUATION ORDER, purely
  // exposing values already computed above -- no formula changes.
  const gateResults = [
    { gate: "dailyTrend", required: `above EMA20 ($${ema20Now.toFixed(2)}) & EMA50 ($${ema50Now.toFixed(2)})`, actual: currentPrice, passed: dailyTrendOk },
    { gate: "impulse", required: isLong ? impulseThresholdPct : -impulseThresholdPct, actual: impulsePct, passed: impulseOk },
    { gate: "consolidation", required: impulseSizeDollars > 0 ? 0.5 * impulseSizeDollars : null, actual: consolDepthDollars, passed: consolidationOk },
    { gate: "breakout", required: isLong ? consolHigh : consolLow, actual: breakoutBar.c, passed: breakoutOk },
    { gate: "vwap", required: vwap, actual: currentPrice, passed: vwapOk },
    { gate: "rsi", required: isLong ? "50-70" : "30-50", actual: rsi, passed: rsiOk },
    { gate: "rvol", required: activeRvolThreshold, actual: rvol, passed: rvolOk },
    { gate: "extension", required: 1.5 * atr14, actual: extensionDollars, passed: extensionOk },
    { gate: "spyAligned", required: direction, actual: spyDirection, passed: spyAlignedOk },
    { gate: "riskReward", required: 2.0, actual: riskReward, passed: rrOk },
  ];
  const failedGates = gateResults.filter((g) => !g.passed).map((g) => g.gate);
  const lastGatePassed = (() => { let last = null; for (const g of gateResults) { if (!g.passed) break; last = g.gate; } return last; })();

  return {
    ...base, eligible, gates, ineligibleReasons, gateResults, failedGates, lastGatePassed,
    allFailedGates: ineligibleReasons,
    entryReference, stop, target1, target2, riskReward,
    currentPrice, priorClose, movePct: impulsePct, rvol, rvolDetail, impulseDetail, impulseSource, rsi14: rsi, vwap,
    consolHigh, consolLow, barCloseTimestamp: breakoutBar.bars[breakoutBar.bars.length - 1]?.t ?? detectedAt,
    dailyEma20: ema20Now, dailyEma50: ema50Now, atr14,
    spyAligned: spyDirection === direction,
    // FIX 1/2 (2026-08-13, Codex review) -- explicit, always-present
    // fields for every rejection record per the exact schema given.
    rvolThreshold: activeRvolThreshold,
    consolidationWidth: consolDepthDollars,
    consolidationMaxAllowed: impulseSizeDollars > 0 ? 0.5 * impulseSizeDollars : null,
    impulseSize: { pctMove: impulsePct, atrThreshold: impulseThresholdPct, passed: impulseOk },
    dailyTrendValues: { ema20: ema20Now, ema50: ema50Now, priceVsEma20: currentPrice - ema20Now, priceVsEma50: currentPrice - ema50Now },
  };
}

// Momentum30m V2: exactly five decisive gates. The six context signals are
// intentionally calculated and retained below, but never appear in
// ineligibleReasons or determine `eligible`.
async function v3EvaluateMomentum30m(symbol, direction, dailyBars, todayBuckets, historicalBucketsByDate, weeklyBars, consolidationIdx1, consolidationIdx2, breakoutIdx, spyDirection, engineConfig) {
  const isLong = direction === "bullish";
  const detectedAt = new Date().toISOString();
  const base = { symbol, direction, setupType: isLong ? "MOMENTUM30M_BULLISH" : "MOMENTUM30M_BEARISH", detectedAt, dataSource: "alpaca_sip_5min_session_aligned_30m", momentumConfigVersion: engineConfig.version };
  const firstBar = todayBuckets[0];
  const bar1 = todayBuckets[consolidationIdx1];
  const bar2 = todayBuckets[consolidationIdx2];
  const breakoutBar = todayBuckets[breakoutIdx];
  const requiredBuckets = [firstBar, bar1, bar2, breakoutBar];
  const freshDataIntegrity = requiredBuckets.every(v3HasFreshCompleteHalfHourBucket);
  const dataGate = { gate: "freshDataIntegrity", required: "four complete 30-min buckets, six valid 5-min bars each", actual: requiredBuckets.map((b) => ({ complete: Boolean(b?.complete), bars: b?.bars?.length ?? 0 })), passed: freshDataIntegrity };
  if (!freshDataIntegrity) {
    return { ...base, eligible: false, gates: null, freshDataIntegrity: false, gateResults: [dataGate], failedGates: ["freshDataIntegrity"], lastGatePassed: null, ineligibleReasons: ["skipped_data: required 30-min bars are stale, incomplete, or missing"], allFailedGates: ["fresh_data_integrity_failed: required 30-min bars are stale, incomplete, or missing"], contextSignals: null };
  }

  const dailyCloses = dailyBars.map((b) => b.c);
  if (dailyCloses.length < 51) return { ...base, eligible: false, gates: null, freshDataIntegrity: false, gateResults: [dataGate], failedGates: ["freshDataIntegrity"], lastGatePassed: null, ineligibleReasons: [`skipped_data: insufficient_daily_history (${dailyCloses.length} bars, need 51+)`], allFailedGates: [`fresh_data_integrity_failed: insufficient_daily_history (${dailyCloses.length} bars, need 51+)`], contextSignals: null };
  const dailyEma20 = v3EMASeries(dailyCloses, 20);
  const dailyEma50 = v3EMASeries(dailyCloses, 50);
  const lastDailyIdx = dailyCloses.length - 1;
  const ema20Now = dailyEma20[lastDailyIdx], ema50Now = dailyEma50[lastDailyIdx];
  const priorClose = dailyCloses[lastDailyIdx];
  const atr14 = v3ATRSeries(dailyBars, 14).slice(-1)[0];
  if (ema20Now == null || ema50Now == null || atr14 == null) return { ...base, eligible: false, gates: null, freshDataIntegrity: false, gateResults: [dataGate], failedGates: ["freshDataIntegrity"], lastGatePassed: null, ineligibleReasons: ["skipped_data: daily_ema_or_atr_not_computable"], allFailedGates: ["fresh_data_integrity_failed: daily_ema_or_atr_not_computable"], contextSignals: null };

  const currentPrice = breakoutBar.c;
  const dailyTrendOk = isLong ? currentPrice > ema20Now && currentPrice > ema50Now : currentPrice < ema20Now && currentPrice < ema50Now;
  const impulsePct = priorClose > 0 ? (firstBar.c - priorClose) / priorClose : null;
  const atrPctThreshold = priorClose > 0 ? (0.75 * atr14) / priorClose : null;
  const impulseThresholdPct = Math.max(0.02, atrPctThreshold ?? 0.02);
  const impulseOk = impulsePct != null && (isLong ? impulsePct >= impulseThresholdPct : impulsePct <= -impulseThresholdPct);
  const impulseSource = v3ClassifyImpulseSource(dailyBars, firstBar, priorClose, impulseThresholdPct, isLong);

  const consolHigh = Math.max(bar1.h, bar2.h);
  const consolLow = Math.min(bar1.l, bar2.l);
  const consolidationWidth = consolHigh - consolLow;
  const consolidationBaseOk = Number.isFinite(consolHigh) && Number.isFinite(consolLow) && consolidationWidth > 0;
  const bodySize = Math.abs(breakoutBar.c - breakoutBar.o);
  const bodyBeyondBase = isLong ? Math.min(breakoutBar.o, breakoutBar.c) > consolHigh : Math.max(breakoutBar.o, breakoutBar.c) < consolLow;
  const breakoutOk = bodySize > 0 && bodyBeyondBase;

  const barsThroughBreakout = todayBuckets.slice(0, breakoutIdx + 1).flatMap((b) => b.bars ?? []);
  const vwap = v2VWAP(barsThroughBreakout);
  const vwapOk = vwap != null && (isLong ? currentPrice > vwap : currentPrice < vwap);
  const halfHourCloses = v3FlattenHalfHourCloseSeries(historicalBucketsByDate, todayBuckets, breakoutIdx);
  const rsiSeries = v3RSISeries(halfHourCloses, 14);
  const rsi = rsiSeries.length > 0 ? rsiSeries[rsiSeries.length - 1] : null;
  const rsiOk = rsi != null && (isLong ? rsi >= 50 && rsi <= 70 : rsi >= 30 && rsi <= 50);

  const historicalVolsThisBucket = [...historicalBucketsByDate.values()].map((buckets) => buckets[breakoutIdx]?.v).filter((v) => v != null && v > 0).sort((a, b) => a - b);
  let rvol = null, priorSessionSameSlotMedian = null;
  if (historicalVolsThisBucket.length >= 10) {
    const mid = Math.floor(historicalVolsThisBucket.length / 2);
    priorSessionSameSlotMedian = historicalVolsThisBucket.length % 2 === 0 ? (historicalVolsThisBucket[mid - 1] + historicalVolsThisBucket[mid]) / 2 : historicalVolsThisBucket[mid];
    rvol = priorSessionSameSlotMedian > 0 ? breakoutBar.v / priorSessionSameSlotMedian : null;
  }
  const rvolOk = rvol != null && rvol > engineConfig.rvolThreshold;
  const currentBarSlot = `${Math.floor(breakoutBar.startMin / 60)}:${String(breakoutBar.startMin % 60).padStart(2, "0")}`;
  const rvolDetail = { currentBarVolume: breakoutBar.v, currentBarSlot, priorSessionSameSlotMedian, rvolRatio: rvol, sessionsUsed: historicalVolsThisBucket.length };

  const entryReference = isLong ? consolHigh : consolLow;
  const extensionDollars = isLong ? breakoutBar.c - consolHigh : consolLow - breakoutBar.c;
  const extensionOk = extensionDollars <= 1.5 * atr14;
  const spyAlignedOk = spyDirection === direction;
  const stop = isLong ? consolLow : consolHigh;
  const target1 = v3FindDailyLevelBeyond(dailyBars, entryReference, isLong);
  const rangeHeight = consolidationWidth;
  let target2 = null;
  if (target1 != null) {
    const weeklyLevel = weeklyBars && weeklyBars.length >= 5 ? (() => {
      const levels = [];
      for (let i = 2; i < weeklyBars.length - 2; i++) {
        const b = weeklyBars[i];
        if (isLong) { if (b.h > weeklyBars[i - 1].h && b.h > weeklyBars[i - 2].h && b.h > weeklyBars[i + 1].h && b.h > weeklyBars[i + 2].h && b.h > target1) levels.push(b.h); }
        else if (b.l < weeklyBars[i - 1].l && b.l < weeklyBars[i - 2].l && b.l < weeklyBars[i + 1].l && b.l < weeklyBars[i + 2].l && b.l < target1) levels.push(b.l);
      }
      return levels.length > 0 ? (isLong ? Math.min(...levels) : Math.max(...levels)) : null;
    })() : null;
    target2 = weeklyLevel ?? (isLong ? entryReference + 2 * rangeHeight : entryReference - 2 * rangeHeight);
  }
  const risk = isLong ? entryReference - stop : stop - entryReference;
  const reward = target1 != null ? (isLong ? target1 - entryReference : entryReference - target1) : null;
  const riskReward = risk > 0 && reward != null ? reward / risk : null;
  const rrOk = target1 != null && riskReward != null && riskReward >= engineConfig.rrMinimum;

  const gates = { freshDataIntegrity, consolidationBase: consolidationBaseOk, breakout: breakoutOk, rvol: rvolOk, riskReward: rrOk };
  const gateResults = [
    dataGate,
    { gate: "consolidationBase", required: "definable intraday base/range", actual: consolidationWidth, passed: consolidationBaseOk },
    { gate: "breakout", required: isLong ? `entire body above $${consolHigh.toFixed(2)}` : `entire body below $${consolLow.toFixed(2)}`, actual: { open: breakoutBar.o, close: breakoutBar.c, bodySize }, passed: breakoutOk },
    { gate: "rvol", required: `>${engineConfig.rvolThreshold}x same-slot median`, actual: rvol, passed: rvolOk },
    { gate: "riskReward", required: engineConfig.rrMinimum, actual: riskReward, passed: rrOk },
  ];
  const ineligibleReasons = [];
  if (!consolidationBaseOk) ineligibleReasons.push("no_definable_intraday_base: the two completed base bars do not form a usable range");
  if (!breakoutOk) ineligibleReasons.push(`no_meaningful_body_breakout: body open $${breakoutBar.o.toFixed(2)} / close $${breakoutBar.c.toFixed(2)} did not close fully beyond ${isLong ? "base high" : "base low"} $${(isLong ? consolHigh : consolLow).toFixed(2)}`);
  if (!rvolOk) ineligibleReasons.push(`rvol_insufficient: ${rvol != null ? rvol.toFixed(2) : "n/a"}x same-slot median (need >${engineConfig.rvolThreshold}x)`);
  if (!rrOk) ineligibleReasons.push(target1 == null ? "no_target1_found: no daily swing level beyond entry" : `insufficient_rr: ${riskReward != null ? riskReward.toFixed(2) : "n/a"} based on Target 1 (need >=${engineConfig.rrMinimum})`);
  const failedGates = gateResults.filter((g) => !g.passed).map((g) => g.gate);
  const lastGatePassed = (() => { let last = null; for (const g of gateResults) { if (!g.passed) break; last = g.gate; } return last; })();
  const contextSignals = {
    dailyTrend: { passed: dailyTrendOk, currentPrice, ema20: ema20Now, ema50: ema50Now },
    impulse: { passed: impulseOk, source: impulseSource, priorClose, firstBarClose: firstBar.c, pctMove: impulsePct, atr14, thresholdPct: impulseThresholdPct },
    vwap: { passed: vwapOk, value: vwap, currentPrice },
    rsi: { passed: rsiOk, value: rsi, preferredRange: isLong ? "50-70" : "30-50" },
    extension: { passed: extensionOk, extensionDollars, atr14, maximum: 1.5 * atr14 },
    spyAligned: { passed: spyAlignedOk, spyDirection, requiredDirection: direction },
  };
  return {
    ...base, eligible: Object.values(gates).every(Boolean), gates, gateResults, failedGates, lastGatePassed, ineligibleReasons, allFailedGates: ineligibleReasons,
    freshDataIntegrity, contextSignals, entryReference, stop, target1, target2, riskReward, currentPrice, priorClose, movePct: impulsePct,
    rvol, rvolDetail, impulseDetail: contextSignals.impulse, impulseSource, rsi14: rsi, vwap, consolHigh, consolLow,
    breakoutDetail: { open: breakoutBar.o, close: breakoutBar.c, bodySize, bodyBeyondBase },
    barCloseTimestamp: breakoutBar.bars[breakoutBar.bars.length - 1]?.t ?? detectedAt,
    dailyEma20: ema20Now, dailyEma50: ema50Now, atr14, spyAligned: spyAlignedOk,
    rvolThreshold: engineConfig.rvolThreshold, consolidationWidth, consolidationMaxAllowed: null,
    consolidationRule: "definable_intraday_base", impulseSize: contextSignals.impulse,
    dailyTrendValues: { ema20: ema20Now, ema50: ema50Now, priceVsEma20: currentPrice - ema20Now, priceVsEma50: currentPrice - ema50Now },
  };
}

// New alert format, per explicit template. "intraday continuation" per
// explicit label -- never "days to weeks" (swing) and never LEAPS.
function v3BuildMomentum30mMessage(candidate) {
  const isLong = candidate.direction === "bullish";
  const rr = candidate.riskReward != null ? candidate.riskReward.toFixed(1) : "n/a";
  const impulseSign = candidate.movePct != null && candidate.movePct >= 0 ? "+" : "";
  const atrMultiple = candidate.impulseDetail?.atr14 > 0 ? Math.abs(candidate.impulseDetail.priorClose != null && candidate.impulseDetail.currentPrice != null ? (candidate.impulseDetail.currentPrice - candidate.impulseDetail.priorClose) / candidate.impulseDetail.atr14 : 0) : null;
  return `⚡ MOMENTUM — ${candidate.symbol} $${candidate.currentPrice.toFixed(2)} | Holding: intraday continuation
30-min base breakout ✅
RVOL: ${candidate.rvol != null ? candidate.rvol.toFixed(1) : "n/a"}x same-slot median ✅
Context (not eligibility gates): impulse ${impulseSign}${candidate.movePct != null ? (candidate.movePct * 100).toFixed(2) : "n/a"}% (${atrMultiple != null ? atrMultiple.toFixed(1) : "n/a"}x ATR)
VWAP: ${candidate.contextSignals?.vwap?.passed ? "aligned" : "not aligned"} | RSI: ${candidate.rsi14 != null ? candidate.rsi14.toFixed(1) : "n/a"}
Daily EMA context: ${candidate.contextSignals?.dailyTrend?.passed ? "aligned" : "not aligned"}

📍 ENTRY: $${candidate.entryReference.toFixed(2)}
🎯 TARGET 1: $${candidate.target1.toFixed(2)} (prior day high)
🎯 TARGET 2: $${candidate.target2.toFixed(2)} (weekly resistance)
⛔ STOP: $${candidate.stop.toFixed(2)} (consolidation ${isLong ? "low" : "high"})
R:R: ${rr}:1 based on T1
⚠️ Not financial advice — intraday continuation setup`;
}

// STAGE2_PAPER_VISIBILITY (2026-08-17) -- real-time admin-only shadow
// visibility, exact format per explicit spec. V3_SHADOW_TAG (the first
// line) is the literal, code-checked marker that makes the subscriber-
// path rejection above real, not just a naming convention.
function v3BuildMomentum30mShadowMessage(candidate, windowLabel) {
  const rr = candidate.riskReward != null ? candidate.riskReward.toFixed(2) : "n/a";
  const timestamp = new Date().toLocaleTimeString("en-US", { timeZone: "America/New_York", hour: "numeric", minute: "2-digit" });
  const trendCtx = candidate.contextSignals?.dailyTrend?.passed ? "aligned" : "not aligned";
  const vwapCtx = candidate.contextSignals?.vwap?.passed ? "aligned" : "not aligned";
  const rsiCtx = candidate.rsi14 != null ? candidate.rsi14.toFixed(1) : "n/a";
  return `${V3_SHADOW_TAG} — NOT LIVE
${candidate.symbol} ${candidate.direction} | ${timestamp} ET
Entry: $${candidate.entryReference.toFixed(2)} | Stop: $${candidate.stop.toFixed(2)}
T1: $${candidate.target1.toFixed(2)} | T2: $${candidate.target2.toFixed(2)} | R:R ${rr}
RVOL: ${candidate.rvol != null ? candidate.rvol.toFixed(1) : "n/a"}x | Context: trend ${trendCtx}, VWAP ${vwapCtx}, RSI ${rsiCtx}
For observation only — not a trade instruction.`;
}

// STAGE2_PAPER_VISIBILITY (2026-08-17) -- fires IMMEDIATELY when a
// momentum30m candidate passes all 5 core gates (eligible === true in
// the v2 model), independent of and BEFORE the scan's own end-of-loop
// ranking/2-per-day cap (that logic still governs the separate, fully-
// blocked "real" send path -- canSend is hardcoded false there, see
// commit 1cac8dd). This is a distinct, additional real-time channel,
// admin-chat-only, explicitly never live.
//
// Anti-spam: per-symbol/per-direction/per-window dedup (kvSetNX, so a
// retried/duplicate scan for the same window never double-sends) plus a
// daily cap. The cap number (15/day) is an engineering default, NOT an
// independently sourced trading threshold -- disclosed per CLAUDE.md's
// threshold rule the same way this codebase already discloses its other
// uncited-but-reasonable operational limits (e.g. the 20s Telegram
// timeout). Sized deliberately looser than the real 2/day alert cap,
// since this feed's whole purpose is showing MORE candidates than the
// strict live system would ever send, for observation.
const V3_SHADOW_DAILY_CAP = 15;
async function v3SendMomentum30mShadowSetup(candidate, dateET, windowLabel) {
  if (!candidate.eligible) return { sent: false, reason: "not_eligible" };
  const dedupKey = `v3:momentum:shadowSent:${dateET}:${windowLabel}:${candidate.symbol}:${candidate.direction}`;
  const claim = await kvSetNX(dedupKey, { claimedAt: new Date().toISOString() }, 86400);
  if (!claim.acquired) return { sent: false, reason: "already_sent_this_symbol_window" };
  const countKey = `v3:momentum:shadowSentCount:${dateET}`;
  const countResult = await kvGet(countKey);
  const countSoFar = countResult.ok && typeof countResult.value === "number" ? countResult.value : 0;
  if (countSoFar >= V3_SHADOW_DAILY_CAP) return { sent: false, reason: "daily_cap_reached" };

  const message = v3BuildMomentum30mShadowMessage(candidate, windowLabel);
  // v3SendTelegram -- the ONLY function in this codebase that can reach
  // TELEGRAM_SWING_ADMIN_CHAT_ID (confirmed by direct code review this
  // session: V3_SWING_ADMIN_CHAT_ID is read exactly once, in this one
  // function, and it never falls back to CHAT_ID/ADMIN_CHAT_ID -- see
  // that function's own header comment). No new send path introduced.
  const sent = await v3SendTelegram(message, "runV3Momentum30mScan_shadow");
  await kvSet(countKey, countSoFar + (sent ? 1 : 0));
  // Audit record, recipientType explicitly "admin_shadow" per instruction.
  await kvSet(`v3:momentum:shadowAudit:${dateET}:${windowLabel}:${candidate.symbol}:${candidate.direction}`, {
    symbol: candidate.symbol, direction: candidate.direction, windowLabel, dateET,
    recipientType: "admin_shadow", destination: "TELEGRAM_SWING_ADMIN_CHAT_ID",
    entryReference: candidate.entryReference, stop: candidate.stop, target1: candidate.target1, target2: candidate.target2, riskReward: candidate.riskReward,
    rvol: candidate.rvol, sent, sentAt: new Date().toISOString(),
  });
  return { sent, reason: sent ? "sent" : "telegram_send_failed" };
}

// ---- Scan orchestrator (11:00am-3:30pm ET, every 30 min). Mirrors
// runV3MasterDecisionIntraday's structure exactly (same score/write flow,
// shadow delivery blocked), engine="momentum30m".
async function runV3Momentum30mScan(dateET, windowLabel, consolidationIdx1, consolidationIdx2, breakoutIdx) {
  const scanId = v3MasterDecisionScanId();
  await v3RecordScanId(dateET, "momentum30m", scanId, windowLabel);
  const shadowStage = await v3GetMasterDecisionShadowStage();
  // Momentum30m v2 is explicitly a shadow test. This remains false even if
  // the broader Master Decision stage is later promoted.
  const canSend = false;
  const sendBlockedReason = "momentum30m_v2_shadow_test";
  const engineConfig = await v3EnsureMomentumEngineConfigV2();

  // FIX 1 (2026-08-14) -- v2, not v1 (see channelScanner's own comment
  // for the full rationale).
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols)) {
    await v3SendUniverseUnavailableIncident(dateET, "momentum30mScan");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };
  }

  const nowMinutesET = (() => { const { hour, min } = getET(); return hour * 60 + min; })();
  const todayDateKey = dateET;
  const priorSessionKeys = v3PriorTradingDayKeys(todayDateKey, 20);

  const spySnap = (await v2GetAlpacaSnapshotsBatch(["SPY"]))?.SPY;
  const spyMove = spySnap?.latestTrade?.p != null && spySnap?.prevDailyBar?.c > 0 ? (spySnap.latestTrade.p - spySnap.prevDailyBar.c) / spySnap.prevDailyBar.c : null;
  const spyDirection = spyMove == null ? null : spyMove >= 0 ? "bullish" : "bearish";

  const alertsSentTodayResult = await kvGet(`v3:master:alertsSentToday:${dateET}`);
  let alertsSentToday = alertsSentTodayResult.ok && Array.isArray(alertsSentTodayResult.value) ? alertsSentTodayResult.value : [];

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- one real
  // snapshot batch for the whole universe, reused for every symbol's
  // intradayMovePct/isMaterialMover instead of a per-symbol refetch.
  const stepOneSnapshots = await v2GetAlpacaSnapshotsForSymbols(universe.symbols);
  const stepOneRecords = {}; // symbol -> {outcomeState, gateResults, failedGates, lastGatePassed, setup}

  // FIX 2 (2026-08-14, Codex review) -- honest outcome accounting. The
  // three summary counters used to only increment for HARD-gate
  // rejections/passes (hardGateRejections/eligibleAfterGates) or
  // outright data failures (skippedData) -- a symbol that failed at
  // PATTERN-level gates (daily trend, impulse, consolidation, breakout,
  // VWAP, RSI, RVOL, extension, SPY alignment -- i.e. never even reached
  // v3CheckHardGates) fell into NONE of the three buckets, so a scan
  // where every symbol failed pattern gates reported "0 eligible, 0
  // rejected, 0 skipped_data" even though 100/100 symbols were genuinely
  // evaluated and genuinely rejected. Added patternGateRejections as a
  // fourth, explicit bucket, and moved ALL counting to run once PER
  // SYMBOL (after both directions are processed, based on the final
  // symbolOutcome/symbolStage) instead of per-direction inside the loop
  // -- the old per-direction increments could also double-count a
  // symbol that failed the hard gate in both directions.
  let hardGateRejections = 0, patternGateRejections = 0, eligibleAfterGates = 0, skippedData = 0;
  const passedCandidates = [];

  for (const symbol of universe.symbols) {
    let symbolOutcome = "skipped_data";
    let symbolStage = null; // "pattern_gates" | "hard_gates" | null (skipped_data / eligible)
    let symbolReasons = [];
    let symbolSkippedReason = null;
    let symbolBarCloseTimestamp = null;
    let symbolRvolDetail = null;
    let symbolImpulseDetail = null;
    let symbolEntry = null, symbolStop = null, symbolTarget1 = null, symbolTarget2 = null, symbolRR = null;
    let symbolDirection = null, symbolGateResults = null, symbolFailedGates = null, symbolLastGatePassed = null, symbolDataTimestamp = null;
    // FIX 1/2 (2026-08-13, Codex review) -- extra fields required on
    // every outcome record, always present even for skipped_data
    // (rvolThreshold reflects the active config regardless of whether
    // this symbol's own RVOL could be computed).
    let symbolExtra = { momentumConfigVersion: engineConfig.version, rvolThreshold: engineConfig.rvolThreshold, consolidationRule: "definable_intraday_base", consolidationWidth: null, consolidationMaxAllowed: null, impulseSource: null, impulseSize: null, dailyTrendValues: null, freshDataIntegrity: null, contextSignals: null, breakoutDetail: null, allFailedGates: [] };
    try {
      const fiveMinResult = await v3GetFiveMinuteSipBars(symbol, 30);
      if (!fiveMinResult.ok) {
        skippedData++;
        symbolSkippedReason = `5min_fetch_failed: ${fiveMinResult.error}`;
        await v3WriteScanOutcome("momentum30m", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, symbolRvolDetail, symbolImpulseDetail, symbolEntry, symbolStop, symbolTarget1, symbolTarget2, symbolRR, symbolExtra);
        continue;
      }
      const todayBuckets = v3BuildSessionAlignedHalfHourBuckets(fiveMinResult.bars, todayDateKey, nowMinutesET);
      const historicalBucketsByDate = new Map();
      for (const dk of priorSessionKeys) historicalBucketsByDate.set(dk, v3BuildSessionAlignedHalfHourBuckets(fiveMinResult.bars, dk, null));

      const dailyBarsResult = await v3GetPriorSessionDailyBars(symbol, 60);
      if (!dailyBarsResult.ok || dailyBarsResult.barCount < 51) {
        skippedData++;
        symbolSkippedReason = `insufficient_daily_bars (${dailyBarsResult.barCount ?? 0})`;
        await v3WriteScanOutcome("momentum30m", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, symbolRvolDetail, symbolImpulseDetail, symbolEntry, symbolStop, symbolTarget1, symbolTarget2, symbolRR, symbolExtra);
        continue;
      }
      const weeklyBars = await v3GetWeeklyBarsSip(symbol, 400);

      for (const direction of ["bullish", "bearish"]) {
        const candidate = await v3EvaluateMomentum30m(symbol, direction, dailyBarsResult.bars, todayBuckets, historicalBucketsByDate, weeklyBars, consolidationIdx1, consolidationIdx2, breakoutIdx, spyDirection, engineConfig);
        const barCloseTimestamp = candidate.barCloseTimestamp ?? `${windowLabel}-${direction}`;
        symbolBarCloseTimestamp = symbolBarCloseTimestamp ?? barCloseTimestamp;
        symbolRvolDetail = symbolRvolDetail ?? candidate.rvolDetail ?? null;
        symbolImpulseDetail = symbolImpulseDetail ?? candidate.impulseDetail ?? null;

        if (candidate.gates == null) {
          await v3WriteSignal("momentum30m", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "skipped_data", failedInput: candidate.ineligibleReasons?.[0] ?? "unknown", scanId, momentumConfigVersion: engineConfig.version, rvolThreshold: engineConfig.rvolThreshold, freshDataIntegrity: candidate.freshDataIntegrity ?? false, contextSignals: candidate.contextSignals ?? null });
          symbolSkippedReason = symbolSkippedReason ?? candidate.ineligibleReasons?.[0] ?? "unknown";
          continue;
        }
        const directionExtra = {
          momentumConfigVersion: engineConfig.version,
          rvolThreshold: engineConfig.rvolThreshold,
          consolidationRule: candidate.consolidationRule,
          consolidationWidth: candidate.consolidationWidth,
          consolidationMaxAllowed: candidate.consolidationMaxAllowed,
          impulseSource: candidate.impulseSource,
          impulseSize: candidate.impulseSize,
          dailyTrendValues: candidate.dailyTrendValues,
          freshDataIntegrity: candidate.freshDataIntegrity,
          contextSignals: candidate.contextSignals,
          breakoutDetail: candidate.breakoutDetail,
          allFailedGates: candidate.allFailedGates,
        };
        // FIX 2 (2026-08-14, Codex review) -- pattern-level rejection.
        // The symbol WAS evaluated and WAS rejected -- outcome:"rejected"
        // with stage:"pattern_gates" and the complete failed-gate list,
        // never folded into an ambiguous eligible:0/rejected:0/
        // skipped:0 that reads as "nothing happened."
        if (!candidate.eligible) {
          await v3WriteSignal("momentum30m", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "rejected", stage: "pattern_gates", reasons: candidate.ineligibleReasons, scanId, ...directionExtra });
          if (symbolOutcome !== "eligible") { symbolOutcome = "rejected"; symbolStage = symbolStage === "hard_gates" ? symbolStage : "pattern_gates"; symbolReasons.push(...candidate.ineligibleReasons.map((r) => `${direction}: ${r}`)); symbolEntry = candidate.entryReference; symbolStop = candidate.stop; symbolTarget1 = candidate.target1; symbolTarget2 = candidate.target2; symbolRR = candidate.riskReward; symbolExtra = directionExtra; symbolDirection = direction; symbolGateResults = candidate.gateResults ?? null; symbolFailedGates = candidate.failedGates ?? null; symbolLastGatePassed = candidate.lastGatePassed ?? null; symbolDataTimestamp = barCloseTimestamp; }
          continue;
        }

        const weeklyTrend = v3CheckWeeklyTrendDirection(weeklyBars, direction);
        const { score, breakdown } = v3ScoreCandidate({
          dailyTrendAligned: candidate.contextSignals?.dailyTrend?.passed,
          weeklyLevelConfluence: v3HasWeeklyLevelConfluence(weeklyBars, candidate.entryReference),
          isMomentumSignal: true,
          weeklyTrendAligned: weeklyTrend.aligned,
          spyAligned: candidate.contextSignals?.spyAligned?.passed,
          counterTrend: false,
          fallbackDataUsed: false,
        });

        await v3WriteSignal("momentum30m", dateET, symbol, direction, `${windowLabel}-${barCloseTimestamp}`, { symbol, direction, setupType: candidate.setupType, outcome: "eligible", score, breakdown, scanId, ...directionExtra });
        symbolOutcome = "eligible";
        symbolReasons = [];
        symbolEntry = candidate.entryReference; symbolStop = candidate.stop; symbolTarget1 = candidate.target1; symbolTarget2 = candidate.target2; symbolRR = candidate.riskReward;
        symbolExtra = directionExtra;
        symbolDirection = direction; symbolGateResults = candidate.gateResults ?? null; symbolFailedGates = candidate.failedGates ?? null; symbolLastGatePassed = candidate.lastGatePassed ?? null; symbolDataTimestamp = barCloseTimestamp;
        passedCandidates.push({ ...candidate, score, breakdown, weeklyTrend });
        // STAGE2_PAPER_VISIBILITY (2026-08-17) -- fires immediately here,
        // the moment all 5 core gates pass, independent of the score/
        // ranking/2-per-day cap below (that logic governs the separate,
        // hardcoded-blocked "real" send path only).
        await v3SendMomentum30mShadowSetup(candidate, dateET, windowLabel);
      }
      // FIX 2 (2026-08-14, Codex review) -- symbol-level tally, counted
      // ONCE per symbol here (not per-direction inside the loop above,
      // which could double-count a symbol failing both directions) --
      // now with an explicit bucket for pattern-level rejections so the
      // scan summary can never again claim "0 eligible, 0 rejected, 0
      // skipped_data" for a symbol that was genuinely evaluated and
      // genuinely rejected.
      if (symbolOutcome === "eligible") eligibleAfterGates++;
      else if (symbolOutcome === "rejected" && symbolStage === "hard_gates") hardGateRejections++;
      else if (symbolOutcome === "rejected" && symbolStage === "pattern_gates") patternGateRejections++;
      else if (symbolOutcome === "skipped_data") skippedData++;
      await v3WriteScanOutcome("momentum30m", dateET, scanId, symbol, symbolOutcome, symbolReasons, symbolSkippedReason, symbolBarCloseTimestamp, symbolRvolDetail, symbolImpulseDetail, symbolEntry, symbolStop, symbolTarget1, symbolTarget2, symbolRR, { ...symbolExtra, stage: symbolStage });
      // STEP 1 (2026-08-17) -- stash for the final v3:outcome write below,
      // once we know which eligible candidates actually got sent (that
      // decision happens after this loop, once every symbol is scored
      // and ranked -- see the selected/alertsSent block).
      const { intradayMovePct, isMaterialMover } = v3MoveContextFromSnapshot(stepOneSnapshots[symbol]);
      stepOneRecords[symbol] = {
        outcomeState: symbolOutcome === "eligible" ? "eligible" : symbolOutcome === "skipped_data" ? "skipped_data" : "rejected",
        gateResults: symbolGateResults, failedGates: symbolFailedGates, lastGatePassed: symbolLastGatePassed,
        setup: symbolOutcome === "eligible" ? { direction: symbolDirection, entry: symbolEntry, stop: symbolStop, target1: symbolTarget1, target2: symbolTarget2, riskReward: symbolRR, dataTimestamp: symbolDataTimestamp, ruleVersion: "momentum30m_v2" } : null,
        intradayMovePct, isMaterialMover,
        momentumConfigVersion: symbolExtra.momentumConfigVersion, coreGates: engineConfig.coreGates, contextSignals: symbolExtra.contextSignals, freshDataIntegrity: symbolExtra.freshDataIntegrity, breakoutDetail: symbolExtra.breakoutDetail, consolidationRule: symbolExtra.consolidationRule,
      };
      await new Promise((r) => setTimeout(r, 100));
    } catch (e) {
      skippedData++;
      await v3WriteScanOutcome("momentum30m", dateET, scanId, symbol, "skipped_data", [], `threw: ${e.message}`, null, null, null, null, null, null, null, null, { ...symbolExtra, stage: null });
      const { intradayMovePct, isMaterialMover } = v3MoveContextFromSnapshot(stepOneSnapshots[symbol]);
      stepOneRecords[symbol] = { outcomeState: "skipped_data", gateResults: null, failedGates: null, lastGatePassed: null, setup: null, intradayMovePct, isMaterialMover, momentumConfigVersion: engineConfig.version, coreGates: engineConfig.coreGates, contextSignals: symbolExtra.contextSignals, freshDataIntegrity: symbolExtra.freshDataIntegrity, breakoutDetail: symbolExtra.breakoutDetail, consolidationRule: symbolExtra.consolidationRule };
    }
  }

  passedCandidates.sort((a, b) => b.score - a.score || Number(Boolean(b.contextSignals?.impulse?.passed)) - Number(Boolean(a.contextSignals?.impulse?.passed)));
  const suppressedByScore = passedCandidates.filter((c) => c.score < 5).map((c) => ({ symbol: c.symbol, score: c.score, reason: "score_below_5" }));
  let selected = passedCandidates.filter((c) => c.score >= 5);
  const seenSymbolDirection = new Set();
  selected = selected.filter((c) => {
    const key = `${c.symbol}:${c.direction}`;
    if (seenSymbolDirection.has(key)) return false;
    seenSymbolDirection.add(key);
    return true;
  });

  let alertsSent = 0;
  const stepOneWithinCap = new Set(); // symbols that reached the top of the ranking within today's 2-alert cap
  for (const c of selected) {
    if (!canSend) break;
    if (alertsSentToday.length >= 2) break;
    stepOneWithinCap.add(c.symbol);
    const message = v3BuildMomentum30mMessage(c);
    if (canSend) await v3SendTelegram(message, `runV3Momentum30mScan_${windowLabel}`);
    alertsSentToday = await v3RecordMasterAlert(dateET, c.symbol, c.direction, c.setupType);
    alertsSent++;
  }
  if (selected.length === 0) await v3RecordNoQualifiedSetup(dateET, "momentum30m", windowLabel, passedCandidates.length);

  // STEP 1 (2026-08-17, System vs. Market outcome capture) -- final
  // per-symbol write, now that ranking/cap/shadow-stage are all known.
  // rejected/skipped_data records were already final at collection time
  // above; only "eligible" symbols needed this second pass, since
  // sent/eligible_shadow_blocked/eligible_capped can't be known until
  // every symbol has been scored and ranked against the daily cap.
  for (const symbol of universe.symbols) {
    const rec = stepOneRecords[symbol];
    if (!rec) { await v3WriteOutcomeRecord("momentum30m", dateET, symbol, "not_evaluated"); continue; }
    let finalState = rec.outcomeState;
    if (finalState === "eligible") {
      if (!canSend) finalState = "eligible_shadow_blocked";
      else if (stepOneWithinCap.has(symbol)) finalState = "sent";
      else finalState = "eligible_capped";
    }
    await v3WriteOutcomeRecord("momentum30m", dateET, symbol, finalState, {
      gateResults: rec.gateResults, failedGates: rec.failedGates, lastGatePassed: rec.lastGatePassed,
      setup: rec.setup, intradayMovePct: rec.intradayMovePct, isMaterialMover: rec.isMaterialMover,
      extraFields: { momentumConfigVersion: rec.momentumConfigVersion ?? engineConfig.version, coreGates: rec.coreGates ?? engineConfig.coreGates, contextSignals: rec.contextSignals ?? null, freshDataIntegrity: rec.freshDataIntegrity ?? null, breakoutDetail: rec.breakoutDetail ?? null, consolidationRule: rec.consolidationRule ?? "definable_intraday_base", shadowOnly: true, sendBlockedReason },
    });
  }

  // FIX 2 (2026-08-14) -- plain-English summary line, per explicit
  // instruction ("Summary must say plainly: 'N symbols evaluated, N
  // rejected at pattern_gates, N eligible, N skipped_data'").
  const summaryText = `${universe.symbols.length} symbols evaluated, ${patternGateRejections} rejected at pattern_gates, ${hardGateRejections} rejected at hard_gates, ${eligibleAfterGates} eligible, ${skippedData} skipped_data`;
  await v3WriteScanRecord("momentum30m", dateET, scanId, { scanId, dateET, windowLabel, symbolsScanned: universe.symbols.length, patternGateRejections, hardGateRejections, eligibleAfterGates, skippedData, selectedCandidates: selected.length, alertsSent, shadowStage, canSend, sendBlockedReason, momentumConfigVersion: engineConfig.version, coreGates: engineConfig.coreGates, summaryText });

  await kvSet(`v3:master:decision:${dateET}:momentum30m_${windowLabel}`, {
    date: dateET,
    enginesRead: { channel: false, pullback: false, breakout: false, momentum30m: true },
    patternGateRejections, hardGateRejections, eligibleAfterGates,
    selectedCandidates: selected.length,
    suppressedByScore,
    alertsSent,
    outsideUniverse: [],
    shadowStage, canSend, sendBlockedReason, momentumConfigVersion: engineConfig.version, coreGates: engineConfig.coreGates, scanId,
    summaryText,
    completedAt: new Date().toISOString(),
  });

  return { didWork: true, alertsSent, eligibleAfterGates, hardGateRejections, patternGateRejections, selected: selected.length, skippedData, universeCount: universe.symbols.length, scanId };
}

// ---- 10:30am ET context-only recorder -- builds/stores today's
// 30-min buckets so far, no signal evaluation, never sends anything.
async function runV3Momentum30mContext(dateET) {
  // FIX 1 (2026-08-14) -- v2, not v1 (see channelScanner's own comment
  // for the full rationale).
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  if (!universe || !Array.isArray(universe.symbols)) {
    await v3SendUniverseUnavailableIncident(dateET, "momentum30mContext");
    return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing" };
  }

  const nowMinutesET = (() => { const { hour, min } = getET(); return hour * 60 + min; })();
  const records = {};
  for (const symbol of universe.symbols) {
    const fiveMinResult = await v3GetFiveMinuteSipBars(symbol, 1);
    if (!fiveMinResult.ok) { records[symbol] = { error: fiveMinResult.error }; continue; }
    const buckets = v3BuildSessionAlignedHalfHourBuckets(fiveMinResult.bars, dateET, nowMinutesET);
    records[symbol] = { buckets: buckets.map((b) => ({ startMin: b.startMin, endMin: b.endMin, complete: b.complete, o: b.o, h: b.h, l: b.l, c: b.c, v: b.v })) };
    await new Promise((r) => setTimeout(r, 60));
  }
  await kvSet(`v3:master:context30m:${dateET}:1030`, { dateET, windowLabel: "1030", symbolsRecorded: Object.keys(records).length, records, completedAt: new Date().toISOString() });
  return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt: new Date().toISOString(), businessWorkCompletedAt: new Date().toISOString() };
}

// ---- Job wrapper factory (2026-08-13) -- 11 near-identical windows
// (1 context + 10 scans) share the exact same window/mode/weekday/claim
// contract every other v3 job uses; a factory avoids 11 hand-copied
// functions each risking a pasted-wrong-number bug. v3Momentum30mDoneFlags
// is a plain object (not 11 separate `let`s) so the factory can close
// over a mutable per-job flag by key.
const v3Momentum30mDoneFlags = {};
// FIX 1 (2026-08-16, Codex review) -- same durable retry-until-deadline
// pattern as masterDecisionMorning, applied to each 30-min momentum
// window. Deadline = windowEnd + 20 min grace (~4 more tick attempts at
// the 5-min tick interval), NOT "retry until the next window opens" --
// deliberately not chained, because these buckets are session-time-
// aligned (the c1/c2/breakoutIdx half-hour buckets come from real bar
// timestamps, not wall-clock-at-run-time), so a late retry still
// evaluates the CORRECT historical buckets for windowLabel -- but
// letting it drift for hours would mean its real-time context (SPY
// direction, current-price extension checks) is stale relative to the
// label shown in any alert. 20 min keeps it tightly bound to its
// intended slot while surviving a single missed tick or a short worker
// restart (the exact 2026-08-12 failure mode, just applied to this
// engine's own cadence). No trading-rule change -- same evaluator, same
// gates, only WHEN it's allowed to run is different. Dependency here is
// just universe v2 availability (momentum30m doesn't read
// channelScanner/dataAgent output the way the morning engine does).
function v3MakeMomentum30mJob(jobKey, windowStart, windowEnd, windowLabel, isContext, c1, c2, breakoutIdx) {
  v3Momentum30mDoneFlags[jobKey] = false;
  const deadline = windowEnd + 20;
  return async function (dateET = v3TradingDateET()) {
    if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
    if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
    if (v3Momentum30mDoneFlags[jobKey]) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
    const { hour, min } = getET();
    const total = hour * 60 + min;
    if (total < windowStart) {
      return { didWork: false, status: "skipped_dependency", skipReason: `before the ${windowLabel} ET window opens (scheduled, not yet due)`, universeKey: "v3:universe:swing:v2", universeCount: null, scanId: null, dependencyState: null };
    }

    const universeResult = await kvGet("v3:universe:swing:v2");
    const universeReady = universeResult.ok && Array.isArray(universeResult.value?.symbols) && universeResult.value.symbols.length > 0;
    const dependencyState = { universe: universeReady ? "ready" : "not_ready (v3:universe:swing:v2 missing/empty)" };
    const pastDeadline = total >= deadline;
    if (!universeReady) {
      return { didWork: false, status: "skipped_dependency", skipReason: `${pastDeadline ? "deadline" : windowLabel + "+20min deadline"} ${pastDeadline ? "passed" : "not yet reached"} with v3:universe:swing:v2 unavailable`, universeKey: "v3:universe:swing:v2", universeCount: null, scanId: null, dependencyState };
    }
    if (pastDeadline) {
      return { didWork: false, status: "skipped_dependency", skipReason: `deadline (${windowLabel} + 20min) passed before this job could claim/run (no tick landed in the active window)`, universeKey: "v3:universe:swing:v2", universeCount: universeResult.value.symbols.length, scanId: null, dependencyState };
    }
    if (!(await v3ClaimJobStart(jobKey, dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };
    const businessWorkStartedAt = new Date().toISOString();
    const result = isContext ? await runV3Momentum30mContext(dateET) : await runV3Momentum30mScan(dateET, windowLabel.replace(":", ""), c1, c2, breakoutIdx);
    v3Momentum30mDoneFlags[jobKey] = true;
    console.log(`v3 MOMENTUM 30M (${windowLabel}${isContext ? " context" : ""}): complete.`, isContext ? "" : `eligibleAfterGates=${result.eligibleAfterGates}, hardGateRejections=${result.hardGateRejections}, patternGateRejections=${result.patternGateRejections}, alertsSent=${result.alertsSent}, skippedData=${result.skippedData}.`);
    return {
      didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt: new Date().toISOString(),
      universeKey: "v3:universe:swing:v2", universeCount: result.universeCount ?? universeResult.value.symbols.length, scanId: result.scanId ?? null, dependencyState,
    };
  };
}

