// FIX 1 (2026-08-16, Codex review) -- watchdog. Checked once in a
// 10:15-10:25am ET window (real deadline for masterDecisionMorning is
// 10:00am -- this gives 15 min of buffer for the manifest write itself
// to land before checking). Reads masterDecisionMorning's OWN manifest
// (already fully durable per the state machine above) -- if it never
// did real work today, sends exactly ONE admin incident, deduped via
// kvSetNX so a later tick within the same 10-minute check window never
// double-sends. This is the human-facing half of FIX 1: the retry logic
// above prevents most missed days outright, but if dependencies
// genuinely never became ready (or the whole worker was down through
// the entire 8:35-10:00 window), Bill finds out same-morning instead of
// discovering it days later during a manual audit, as happened
// 2026-08-12.
let v3MasterDecisionWatchdogDone = false;
async function runV3MasterDecisionWatchdog(dateET = v3TradingDateET()) {
  if (!isV3ModeActive() || !isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not applicable" };
  if (v3MasterDecisionWatchdogDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  if (total < 615 || total >= 625) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 10:15-10:25am ET watchdog window" };
  v3MasterDecisionWatchdogDone = true;
  const manifestResult = await kvGet(`v3:jobs:masterDecisionMorning:${dateET}`);
  const manifest = manifestResult.ok ? manifestResult.value : null;
  if (manifest?.didWork === true) {
    return { didWork: true, status: "completed", skipReason: null };
  }
  const claim = await kvSetNX(`v3:master:watchdogSent:${dateET}`, { sentAt: new Date().toISOString() }, 86400);
  if (claim.acquired) {
    await v3SendTelegram(`⚠️ MASTER DECISION DID NOT RUN — ${dateET}, window missed, no candidates evaluated`, "runV3MasterDecisionWatchdog");
  }
  return { didWork: true, status: "completed", skipReason: null };
}

// FIX 3 (2026-08-16, Codex review) -- per-symbol gate-failure tally for
// one engine/scanId, used to build the transparency report's "Top
// rejection gates" and "Near-misses" lines. No KV LIST/SCAN primitive
// exists in this codebase (confirmed repeatedly elsewhere -- see
// runV3MasterMissedMoverAudit's own comment on actualOutcomes), so this
// reads each KNOWN universe symbol's own outcome key directly rather
// than trying to enumerate keys. Gate name = the text before the first
// ": " in each rejectionReasons string (e.g. "insufficient_impulse:
// 0.75% ..." -> "insufficient_impulse"). A near-miss = a symbol whose
// outcome was rejected with EXACTLY ONE failed gate -- closest to
// passing everything.
async function v3GatherGateBreakdown(engine, dateET, scanId, symbols) {
  const gateCounts = {};
  const nearMisses = [];
  let eligible = 0, rejected = 0, skippedData = 0;
  if (!scanId) return { eligible: 0, rejected: 0, skippedData: 0, topGates: [], nearMisses: [], sampled: 0 };
  for (const symbol of symbols) {
    const result = await kvGet(`v3:scans:outcome:${engine}:${dateET}:${scanId}:${symbol}`);
    const rec = result.ok ? result.value : null;
    if (!rec) continue;
    if (rec.outcome === "eligible") eligible++;
    else if (rec.outcome === "rejected") {
      rejected++;
      const reasons = Array.isArray(rec.rejectionReasons) ? rec.rejectionReasons : [];
      for (const r of reasons) {
        const gate = String(r).split(":")[0].trim();
        gateCounts[gate] = (gateCounts[gate] ?? 0) + 1;
      }
      if (reasons.length === 1) nearMisses.push(`${symbol} - ${reasons[0].split(":")[0].trim()}`);
    } else {
      skippedData++;
    }
    await new Promise((r) => setTimeout(r, 30));
  }
  const topGates = Object.entries(gateCounts).sort((a, b) => b[1] - a[1]).slice(0, 5);
  return { eligible, rejected, skippedData, topGates, nearMisses: nearMisses.slice(0, 5), sampled: eligible + rejected + skippedData };
}

const V3_MOMENTUM_WINDOW_KEYS = [
  { jobKey: "momentum30mScan1100", decisionWindow: "1100am" },
  { jobKey: "momentum30mScan1130", decisionWindow: "1130am" },
  { jobKey: "momentum30mScan1200", decisionWindow: "1200pm" },
  { jobKey: "momentum30mScan1230", decisionWindow: "1230pm" },
  { jobKey: "momentum30mScan1300", decisionWindow: "100pm" },
  { jobKey: "momentum30mScan1330", decisionWindow: "130pm" },
  { jobKey: "momentum30mScan1400", decisionWindow: "200pm" },
  { jobKey: "momentum30mScan1430", decisionWindow: "230pm" },
  { jobKey: "momentum30mScan1500", decisionWindow: "300pm" },
  { jobKey: "momentum30mScan1530", decisionWindow: "330pm" },
];

// FIX 3 (2026-08-16, Codex review) -- daily internal validation report,
// TELEGRAM_SWING_ADMIN_CHAT_ID only, sent via the shared v3SendTelegram
// (same function every other v3 admin message uses -- never a separate
// send path). Runs after the 4:30pm missed-mover audit completes (see
// job wrapper below for the dependency gate). Uses "Shadow stage:" (not
// "shadow mode") throughout, matching the exact spec text -- the
// existing content guard in v3SendTelegram only blocks the literal
// phrase "shadow mode" (case-insensitive), which this report never
// contains, so no special-case bypass is needed or added; this was
// verified by reading the guard's own regex (/shadow mode/i) before
// writing this function, not assumed.
async function runV3DailyTransparencyReport(dateET) {
  const universeResult = await kvGet("v3:universe:swing:v2");
  const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
  const symbols = Array.isArray(universe?.symbols) ? universe.symbols : [];

  const [dataAgentM, channelM, masterDecisionM] = await Promise.all([
    kvGet(`v3:jobs:dataAgent:${dateET}`),
    kvGet(`v3:jobs:channelScanner:${dateET}`),
    kvGet(`v3:jobs:masterDecisionMorning:${dateET}`),
  ]);
  const dataAgent = dataAgentM.ok ? dataAgentM.value : null;
  const channel = channelM.ok ? channelM.value : null;
  const masterDecision = masterDecisionM.ok ? masterDecisionM.value : null;

  // Momentum: topline counts summed across every window that actually
  // ran today (its v3:master:decision:...momentum30m_{window} record
  // exists); detailed gate-breakdown/near-misses sampled from only the
  // LAST window that ran (reading all 10 windows' full symbol sets
  // would be up to 1,000 individual KV reads every single day with no
  // bulk-read primitive available -- disclosed scoping choice, not an
  // oversight; the topline numbers below are still a full-day sum, only
  // the gate-name/near-miss detail is a last-window sample).
  let momentumRanCount = 0, momentumEvaluated = 0, momentumEligible = 0, momentumRejected = 0, momentumSelected = 0;
  let lastRanWindow = null, lastRanScanId = null;
  for (const w of V3_MOMENTUM_WINDOW_KEYS) {
    const decisionResult = await kvGet(`v3:master:decision:${dateET}:momentum30m_${w.decisionWindow}`);
    const decision = decisionResult.ok ? decisionResult.value : null;
    if (!decision) continue;
    momentumRanCount++;
    momentumEvaluated += symbols.length;
    momentumEligible += decision.eligibleAfterGates ?? 0;
    momentumRejected += (decision.patternGateRejections ?? 0) + (decision.hardGateRejections ?? 0);
    momentumSelected += decision.selectedCandidates ?? 0;
    lastRanWindow = w.decisionWindow;
    lastRanScanId = decision.scanId ?? null;
  }
  const momentumSample = await v3GatherGateBreakdown("momentum30m", dateET, lastRanScanId, symbols);

  const morningDecisionResult = await kvGet(`v3:master:decision:${dateET}:morning`);
  const morningDecision = morningDecisionResult.ok ? morningDecisionResult.value : null;
  const morningScanId = morningDecision?.scanId ?? masterDecision?.scanId ?? null;
  const morningBreakdown = await v3GatherGateBreakdown("masterMorning", dateET, morningScanId, symbols);
  const dailyEvaluated = symbols.length;
  const dailyEligible = morningDecision?.eligibleAfterGates ?? morningBreakdown.eligible;
  const dailyRejected = (morningDecision?.patternGateRejections ?? 0) + (morningDecision?.hardGateRejections ?? 0);
  const dailySkipped = morningBreakdown.skippedData;

  const missedMoverResult = await kvGet(`v3:master:missedMoverAudit:${dateET}`);
  const missedMover = missedMoverResult.ok ? missedMoverResult.value : null;

  const alertsResult = await kvGet(`v3:master:alertsSentToday:${dateET}`);
  const wouldHaveSent = alertsResult.ok && Array.isArray(alertsResult.value) ? alertsResult.value : [];

  const shadowStage = await v3GetMasterDecisionShadowStage();

  const missedWindows = [];
  if (!(dataAgent?.status === "completed" && dataAgent?.didWork === true)) missedWindows.push("dataAgent");
  if (!(channel?.status === "completed" && channel?.didWork === true)) missedWindows.push("channelScanner");
  if (!(masterDecision?.status === "completed" && masterDecision?.didWork === true)) missedWindows.push("masterDecisionMorning");
  for (const w of V3_MOMENTUM_WINDOW_KEYS) {
    const decisionResult = await kvGet(`v3:master:decision:${dateET}:momentum30m_${w.decisionWindow}`);
    if (!decisionResult.ok || !decisionResult.value) missedWindows.push(w.jobKey);
  }

  const fmtGates = (topGates) => topGates.length === 0 ? "none" : topGates.map(([g, c]) => `${g}: ${c}`).join(", ");
  const fmtNearMisses = (nm) => nm.length === 0 ? "none" : nm.join("; ");
  const wouldHaveSentLines = wouldHaveSent.length === 0
    ? "0"
    : `${wouldHaveSent.length}\n` + wouldHaveSent.map((a) => `${a.symbol} — ${a.setupType ?? "n/a"}, direction=${a.direction ?? "n/a"}`).join("\n");

  const message = `🗄️ LEGACY/INACTIVE — Master Decision Agent shadow-mode validation only
Never graduated past stage1_mechanics; superseded by swingEma20, sweepReclaim,
and finnhubOrContinuation, which each have their own real reports. Retained
here for historical debugging only — KV-only as of 2026-09-02, no longer sent.

FLEXAI INTERNAL VALIDATION — ${dateET}
Not a trade instruction.

Universe: v3:universe:swing:v2 — ${symbols.length} symbols

Jobs:
Data Agent: ${dataAgent?.status ?? "missing"} didWork=${dataAgent?.didWork ?? false}
Channel Scanner: ${channel?.status ?? "missing"} didWork=${channel?.didWork ?? false}
Master Decision: ${masterDecision?.status ?? "missing"} didWork=${masterDecision?.didWork ?? false}
Momentum (10 windows): ${momentumRanCount}/10 ran

Daily engines (channel/pullback/breakout):
Evaluated: ${dailyEvaluated} | Eligible: ${dailyEligible} | Rejected: ${dailyRejected} | Skipped-data: ${dailySkipped}
Top rejection gates: ${fmtGates(morningBreakdown.topGates)}
Near-misses: ${fmtNearMisses(morningBreakdown.nearMisses)}

Momentum engine (30-min):
Evaluated: ${momentumEvaluated} | Eligible: ${momentumEligible} | Rejected: ${momentumRejected}
Top rejection gates (${lastRanWindow ?? "n/a"} sample): ${fmtGates(momentumSample.topGates)}

Would-have-sent if live: ${wouldHaveSentLines}

Coverage: expectedOutcomes ${missedMover?.expectedOutcomes ?? "n/a"} / actualOutcomes ${missedMover?.actualOutcomes ?? "n/a"} / validMath ${missedMover?.validMath ?? "n/a"}
Missed windows: ${missedWindows.length === 0 ? "none" : missedWindows.join(", ")}

Shadow stage: ${shadowStage} — sends blocked`;

  // CLEANUP (2026-09-02) -- this report was confusing the picture next
  // to the real engines: it always shows the dormant channel/pullback/
  // breakout/momentum30m pipeline (stuck in shadowStage="stage1_mechanics"
  // since it was built, never graduated to live sends -- confirmed via
  // real production data on 2026-09-01: Eligible 0/0, "Would-have-sent
  // if live: 0") and says nothing about swingEma20/sweepReclaim/
  // finnhubOrContinuation, which have their own real reports. No longer
  // sent to Telegram -- same "make the old pipeline's message KV-only"
  // treatment already applied elsewhere in this file. Message/KV record
  // still generated in full and preserved for historical debugging,
  // nothing about the underlying jobs/data below this line is touched.
  await kvSet(`v3:master:transparencyReport:${dateET}`, { dateET, message, sent: false, sendSkippedReason: "legacy_report_disabled_2026-09-02", generatedAt: new Date().toISOString() });
  return { didWork: true, status: "completed", skipReason: null, sent: false };
}

async function runV3DailyTransparencyReportJob(dateET = v3TradingDateET()) {
  if (!isV3ModeActive()) return { didWork: false, status: "skipped_outside_window", skipReason: "FLEXAI_MODE not in a v3 mode" };
  if (!isWeekday()) return { didWork: false, status: "skipped_outside_window", skipReason: "not a weekday" };
  if (v3DailyTransparencyReportDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  const { hour, min } = getET();
  const total = hour * 60 + min;
  const WINDOW_OPEN_MIN = 1000; // 4:40pm ET -- right after the 4:30-4:40pm missed-mover audit window closes
  const DEADLINE_MIN = 1050;    // 5:10pm ET
  if (total < WINDOW_OPEN_MIN) return { didWork: false, status: "skipped_dependency", skipReason: "before the 4:40pm ET window opens (scheduled, not yet due)" };

  const auditManifestResult = await kvGet(`v3:jobs:masterMissedMoverAudit:${dateET}`);
  const auditManifest = auditManifestResult.ok ? auditManifestResult.value : null;
  const auditReady = !!(auditManifest && auditManifest.status === "completed" && auditManifest.didWork === true);
  if (!auditReady) {
    const pastDeadline = total >= DEADLINE_MIN;
    return { didWork: false, status: "skipped_dependency", skipReason: `missedMoverAudit not ready (status=${auditManifest?.status ?? "missing"})${pastDeadline ? " -- deadline passed" : ", will retry next tick"}` };
  }
  if (!(await v3ClaimJobStart("dailyTransparencyReport", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };
  console.log("=== v3 DAILY TRANSPARENCY REPORT starting ===");
  const result = await runV3DailyTransparencyReport(dateET);
  v3DailyTransparencyReportDone = true;
  console.log(`v3 DAILY TRANSPARENCY REPORT: complete — sent=${result.sent}.`);
  return result;
}


// ADMIN PIPE CHECK (2026-09-14) -- fires exactly ONCE, ever (permanent
// kvSetNX claim, no per-day reset, no time-window gate -- runs on the
// very next tick after deploy). Exists purely to prove the REAL
// v3SendTelegram/V3_SWING_ADMIN_CHAT_ID worker path can deliver right
// after TELEGRAM_SWING_ADMIN_CHAT_ID was set on Render, since a raw
// curl to a manually-captured chat_id (already done separately) proves
// Telegram itself works but not that THIS function/env-var path does.
// The boolean result is recorded to KV (v3SendTelegram itself never
// persists a message_id anywhere) so this is checkable afterward
// without needing Render log access.
// INSTRUMENTED (2026-09-14, second pass) -- the first version delegated
// to v3SendTelegram and only got a boolean back, which was not enough
// to diagnose two straight sent:false results. This version mirrors
// v3SendTelegram's own guard order EXACTLY (same module-level
// TELEGRAM_BOT / V3_SWING_ADMIN_CHAT_ID / V3_TELEGRAM_ALLOWED_SOURCE_TYPE_PAIRS
// bindings -- reimplemented inline here rather than delegating, ONLY so
// the real HTTP status is visible, which v3SendTelegram's own
// boolean-only contract never exposes to any caller) so this is
// provably testing the SAME conditions the real function gates on, not
// a different code path. No secret VALUE is ever persisted --
// swingAdminLength is a character count only.
async function runV3AdminPipeCheckJob() {
  const claim = await kvSetNX("v3:jobs:adminPipeCheckV1:done", { startedAt: new Date().toISOString() }, 60 * 60 * 24 * 365);
  if (!claim.ok) return { didWork: false, status: "blocked_dependency", skipReason: `KV claim failed: ${claim.error}` };
  if (!claim.acquired) return { didWork: false, status: "already_completed", skipReason: "one-time admin pipe check already ran" };

  const message = "FlexAI · PIPE CHECK · not a setup";
  const sourceSystem = "runV3AdminPipeCheck";
  const messageType = "system.pipeCheck";

  const botLoaded = !!TELEGRAM_BOT;
  const swingAdminLength = V3_SWING_ADMIN_CHAT_ID ? String(V3_SWING_ADMIN_CHAT_ID).length : 0;
  const pairEntry = V3_TELEGRAM_ALLOWED_SOURCE_TYPE_PAIRS.get(v3PairKey(sourceSystem, messageType));
  const allowlistPass = !!pairEntry;

  let sent = false;
  let telegramHttp = "no request";

  if (botLoaded && swingAdminLength > 0 && allowlistPass) {
    const labeledMessage = `ENGINE: ${pairEntry.engineLabel} | MODE: PAPER | STATUS: INFO\n${message}`;
    try {
      const fetch = (await import("node-fetch")).default;
      const r = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT}/sendMessage`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ chat_id: V3_SWING_ADMIN_CHAT_ID, text: labeledMessage }),
      });
      telegramHttp = r.status;
      if (r.ok) {
        const d = await r.json();
        sent = d.ok === true;
      }
    } catch (e) {
      telegramHttp = `fetch_error: ${e.message}`;
    }
  }

  const reason = { botLoaded, swingAdminLength, allowlistPass, telegramHttp, sent, completedAt: new Date().toISOString() };
  await kvSet("v3:jobs:adminPipeCheckV1:result", reason);
  return { didWork: true, status: "completed", skipReason: null, sent };
}


// ---- STEP 4 — runV3DataAgent ----
// 2026-08-10 (Codex review, critical fix, second pass) -- dateET is now
// a REQUIRED parameter, supplied by tick() (via v3RunJobWithManifest)
// from the single value checkReset() derived for this tick -- this
// function no longer calls v3TradingDateET() itself at all. Falls back
// to computing it only if genuinely called standalone (e.g. a future
// manual/test invocation with no argument) so this never throws on a
// missing date, but the normal production call path always supplies it
// explicitly -- "never allow each job to derive its own date
// differently."
// 2026-08-12 (Codex review, critical fix) -- returns a structured
// { didWork, status, skipReason, businessWorkStartedAt,
// businessWorkCompletedAt } at EVERY return point now, per the new
// v3RunJobWithManifest contract, instead of an implicit undefined that
// let the wrapper wrongly infer "completed" from every no-op no-throw
// return. See v3RunJobWithManifest's own header comment for the full
// incident this responds to.
async function runV3DataAgent(dateET = v3TradingDateET()) {
  if (v3DataAgentDone) return { didWork: false, status: "already_completed", skipReason: "in-memory done-flag already true this process" };
  // 2026-08-11 (Codex review CHANGE 1) -- explicit 8:00-8:10am ET window
  // check, added when this moved from a bare "run once market data is
  // final" (no wall-clock check at all -- previously always effectively
  // 4:15pm+ since that was the earliest time yesterday's-close data
  // could be final) to a specific pre-market slot. Without this, once
  // v3MostRecentClosedTradingDayET's fix makes finalDailyBarVerified
  // true continuously overnight, this would fire as early as ~12:05am
  // (the first tick after the done-flag resets for the new date)
  // instead of the requested 8am -- same 10-minute-window convention as
  // every other v3 job for tick-cadence safety.
  const { hour, min } = getET();
  const total = hour * 60 + min;
  if (total < 480 || total >= 490) return { didWork: false, status: "skipped_outside_window", skipReason: "outside the 8:00-8:10am ET window" };
  // FIX 2: the plain isWeekday() gate this used to open with is replaced
  // by a real NYSE-calendar check (v3GetNyseSessionInfo), which subsumes
  // weekends AND holidays in one check, and -- unlike the old silent
  // `return` -- now writes an explicit, inspectable
  // "market_closed_no_scan" record instead of leaving the day's KV key
  // completely absent (which was indistinguishable from "crashed" or
  // "never ran" during the exact incident this fix responds to).
  const session = v3GetNyseSessionInfo(dateET);
  if (session.didTrade === false) {
    await kvSet(`v3:data:health:${dateET}`, {
      status: "market_closed_no_scan",
      dateET,
      timezone: "America/New_York",
      reason: session.reason,
      checkedAt: new Date().toISOString(),
      runAt: new Date().toISOString(),
    });
    v3DataAgentDone = true;
    console.log(`v3 Data Agent: market_closed_no_scan (${session.reason}) for ${dateET} — not scanning.`);
    return { didWork: false, status: "skipped_outside_window", skipReason: `not a trading day (${session.reason})` };
  }

  console.log("=== v3 DATA AGENT starting ===");
  try {
    // Step 1 -- CORRECTION 3 (2026-08-06): explicit final-daily-bar gate,
    // not just /v2/clock's is_open flag. During market hours (or if the
    // close-confirmed-but-bar-not-yet-published edge case is hit), write
    // the exact "waiting" shape specified and do NOT set the done-flag,
    // so this retries again next tick within today's window.
    const barStatus = await v3CheckFinalDailyBarStatus();
    if (!barStatus.finalDailyBarVerified) {
      const waitingRecord = {
        status: "waiting_for_final_daily_bar",
        dateET,
        timezone: "America/New_York",
        runAt: new Date().toISOString(),
        scannerState: barStatus.scannerState,
        marketOpen: barStatus.marketOpen === true,
        note: barStatus.note || "scanner will run after market close confirmed",
        latestBarDate: barStatus.latestBarDate,
        latestCompletedBarDate: barStatus.latestBarDate,
        finalDailyBarVerified: false,
        symbolsValid: 0,
        checkedAt: new Date().toISOString(),
      };
      await kvSet(`v3:data:health:${dateET}`, waitingRecord);
      console.log(`v3 Data Agent: ${waitingRecord.status} —`, JSON.stringify(waitingRecord));
      return { didWork: false, status: "skipped_outside_window", skipReason: "waiting for final daily bar to be confirmed/published -- will retry next tick" }; // non-terminal -- retry next tick within today's window
    }
    // FIX 1 (2026-08-11) -- claimed after the retryable final-daily-bar
    // gate above, so a legitimate "still waiting" retry never gets
    // blocked by its own earlier claim.
    if (!(await v3ClaimJobStart("dataAgent", dateET))) return { didWork: false, status: "already_completed", skipReason: "another tick already claimed this job for today (race guard)" };
    const businessWorkStartedAt = new Date().toISOString();
    const marketCloseConfirmed = true;
    const finalDailyBarVerified = true;

    // Step 2 -- pull SIP daily bars for the entire swing universe.
    // FIX 1 (2026-08-14) -- v2, not v1 (see channelScanner's own comment
    // for the full rationale).
    const universeResult = await kvGet("v3:universe:swing:v2");
    const universe = universeResult.ok && universeResult.value ? universeResult.value : null;
    if (!universe || !Array.isArray(universe.symbols) || universe.symbols.length === 0) {
      console.error("v3 Data Agent: no v3:universe:swing:v2 found — v3BuildUniverseV2 must be run first. Blocking.");
      await kvSet(`v3:data:health:${dateET}`, {
        status: "blocked", dateET, timezone: "America/New_York", runAt: new Date().toISOString(),
        scannerState: "eligible", finalDailyBarVerified, symbolsChecked: 0, symbolsValid: 0, symbolsExcluded: 0, exclusionReasons: [],
        dataIntegrityWarnings: 0, dataIntegrityFailures: 0, sipYahooCrossCheckPassed: 0,
        latestBarDate: barStatus.latestBarDate, latestCompletedBarDate: barStatus.latestBarDate, marketCloseConfirmed, checkedAt: new Date().toISOString(),
      });
      await v3SendTelegram(`🚨 V3 DATA AGENT BLOCKED — ${dateET}\nNo universe found (v3:universe:swing:v2 missing). Run v3BuildUniverseV2 first.\nNo scanners will run today.`, "runV3DataAgent");
      v3DataAgentDone = true;
      return { didWork: false, status: "blocked_dependency", skipReason: "v3:universe:swing:v2 missing -- v3BuildUniverseV2 must be run first" };
    }

    let sipResults;
    try {
      sipResults = await v3GetCompletedDailySipBars(universe.symbols, 320);
    } catch (e) {
      console.error("v3 Data Agent: v3GetCompletedDailySipBars threw —", e.message);
      await kvSet(`v3:data:health:${dateET}`, {
        status: "blocked", dateET, timezone: "America/New_York", runAt: new Date().toISOString(),
        scannerState: "eligible", finalDailyBarVerified, symbolsChecked: universe.symbols.length, symbolsValid: 0, symbolsExcluded: universe.symbols.length,
        exclusionReasons: universe.symbols.map((symbol) => ({ symbol, reason: `sip_fetch_threw: ${e.message}` })),
        dataIntegrityWarnings: 0, dataIntegrityFailures: 0, sipYahooCrossCheckPassed: 0,
        latestBarDate: barStatus.latestBarDate, latestCompletedBarDate: barStatus.latestBarDate, marketCloseConfirmed, checkedAt: new Date().toISOString(),
      });
      await v3SendTelegram(`🚨 V3 DATA AGENT BLOCKED — ${dateET}\nSIP bars fetch failed: ${e.message}\nNo scanners will run today.`, "runV3DataAgent");
      v3DataAgentDone = true;
      return { didWork: false, status: "blocked_dependency", skipReason: `SIP bars fetch failed: ${e.message}` };
    }

    // Step 4 -- corporate actions in the last 5 days (splits/spinoffs) --
    // flag and exclude from channel calc until adjusted.
    const exclusionReasons = [];
    let symbolsValid = 0;
    let dataIntegrityWarnings = 0, dataIntegrityFailures = 0, sipYahooCrossCheckPassed = 0;
    let latestBarDateOverall = null;

    for (const symbol of universe.symbols) {
      const sip = sipResults[symbol];
      if (!sip || !sip.ok) {
        exclusionReasons.push({ symbol, reason: sip ? `sip_error: ${sip.error}` : "sip_result_missing" });
        continue;
      }
      if (sip.dataIntegrityFailure) {
        dataIntegrityFailures++;
        // 2026-08-11 (urgent fix) -- the failing crossCheck entry (the
        // one whose diffPct actually exceeded 1.0%) is what gets
        // recorded/alerted on, not just a bare reason string.
        const failingEntry = sip.crossCheck.find((c) => c.flag === "data_integrity_failure") || sip.crossCheck[sip.crossCheck.length - 1];
        exclusionReasons.push({ symbol, reason: "sip_yahoo_data_integrity_failure", diffPct: failingEntry?.diffPct ?? null, sipClose: failingEntry?.sipClose ?? null, yahooClose: failingEntry?.yahooClose ?? null });
        await kvSet(`v3:data:excluded:${dateET}:${symbol}`, {
          reason: "sip_yahoo_data_integrity_failure",
          sipClose: failingEntry?.sipClose ?? null,
          yahooClose: failingEntry?.yahooClose ?? null,
          diffPct: failingEntry?.diffPct ?? null,
          excludedAt: new Date().toISOString(),
        });
        // 2026-08-12 (Codex review FIX 1) -- the immediate per-symbol
        // Telegram alert from the prior fix is REMOVED. Real problem: an
        // immediate send-per-exclusion could become real noise on a day
        // with several borderline symbols (each one a separate ping),
        // and none of it is actionable in the moment anyway -- excluding
        // one symbol never blocks the rest of the scan (that's the whole
        // point of the per-symbol isolation this same fix chain already
        // built). The v3:data:excluded:{dateET}:{symbol} record above is
        // kept (still useful, queryable detail); the only user-facing
        // surface now is the single "Data notes:" line in the 6pm Swing
        // Lab report (see v3BuildSwingLabReportMessage) -- one clean
        // line per excluded symbol, not a separate alert per symbol.
        continue;
      }
      if (sip.dataIntegrityWarning) dataIntegrityWarnings++;
      if (sip.crossCheck.some((c) => c.flag === "ok")) sipYahooCrossCheckPassed++;

      // Step 5 -- completeness: 300+ bars, no gaps (checked as "no
      // missing weekday" over the trailing real window, same convention
      // as this file's existing minute-of-day completeness checks).
      if (sip.barCount < 300) {
        exclusionReasons.push({ symbol, reason: `insufficient_bars (${sip.barCount}/300)` });
        continue;
      }

      // Step 4 -- recent corporate action (5-day window, tighter than
      // the universe build's own 30-day check, since this runs daily).
      const corpAction = await v3CheckRecentCorporateAction(symbol, 5);
      if (corpAction.ok && corpAction.hasUnresolvedAction) {
        exclusionReasons.push({ symbol, reason: "corporate_action_last_5d_unadjusted" });
        continue;
      }

      symbolsValid++;
      if (!latestBarDateOverall || (sip.latestBarDate && sip.latestBarDate > latestBarDateOverall)) latestBarDateOverall = sip.latestBarDate;
      await new Promise((r) => setTimeout(r, 50));
    }

    const symbolsChecked = universe.symbols.length;
    const symbolsExcluded = exclusionReasons.length;
    // 2026-08-11 (urgent fix) -- was "any exclusion at all => degraded",
    // which meant a single symbol (e.g. GS, at a real 0.052% SIP/Yahoo
    // diff that shouldn't have excluded it in the first place -- see the
    // percentage-threshold fix above) dragged the WHOLE 123-symbol
    // universe's status down and blocked every downstream scanner's
    // health gate. Per explicit instruction: "ok" requires 100+ valid
    // symbols (comfortably tolerates a handful of individual exclusions
    // without downgrading the whole run), "degraded" is everything below
    // that. "blocked" is reserved for the earlier gate failures elsewhere
    // in this function (market not closed, no universe found, SIP fetch
    // threw entirely) -- by this point finalDailyBarVerified is already
    // guaranteed true, so those don't apply to this specific line.
    const status = symbolsValid >= 100 ? "ok" : "degraded";

    const businessWorkCompletedAt = new Date().toISOString();
    const healthRecord = {
      status, dateET, timezone: "America/New_York", runAt: businessWorkCompletedAt,
      scannerState: "eligible", finalDailyBarVerified,
      symbolsChecked, symbolsValid, symbolsExcluded, exclusionReasons,
      dataIntegrityWarnings, dataIntegrityFailures, sipYahooCrossCheckPassed,
      latestBarDate: latestBarDateOverall, latestCompletedBarDate: latestBarDateOverall,
      marketCloseConfirmed, checkedAt: businessWorkCompletedAt,
    };
    await kvSet(`v3:data:health:${dateET}`, healthRecord);

    if (status === "blocked") {
      await v3SendTelegram(`🚨 V3 DATA AGENT BLOCKED — ${dateET}\nsymbolsChecked=${symbolsChecked}, symbolsValid=0, symbolsExcluded=${symbolsExcluded}\nNo scanners will run today. See v3:data:health:${dateET} for exclusion detail.`, "runV3DataAgent");
    }

    v3DataAgentDone = true;
    console.log(`v3 DATA AGENT: complete — status=${status}, valid=${symbolsValid}/${symbolsChecked}, integrity warnings=${dataIntegrityWarnings}, failures=${dataIntegrityFailures}`);
    return { didWork: true, status: "completed", skipReason: null, businessWorkStartedAt, businessWorkCompletedAt };
  } catch (e) {
    console.error("v3 Data Agent error:", e.message);
    await v3SendTelegram(`🚨 V3 DATA AGENT error: ${e.message}`, "runV3DataAgent");
    return { didWork: false, status: "failed", skipReason: String(e?.message ?? e).slice(0, 300) };
  }
}

// ============================================================
// MASTER AUDIT AGENT v1 (auditAgent.v1) -- BITE 1 (2026-09-09,
// Codex-approved design). READ-ONLY: detects/classifies/reports the
// health of every other component in this system. Never restarts,
// fixes, or changes anything else -- touches no engine's formula, KV
// key, dedup, or Telegram binding. Own namespace: v3:auditAgent:*.
//
// Built in direct response to a real incident this same session: the
// legacy "News Agent" (runNewsAgentV2) has been silently unreachable
// since the 2026-08-06 FLEXAI_MODE mode-gate shipped (its call site
// sits after tick()'s unconditional `return` inside the
// isV3ModeActive() block -- see that block's own comment, "exit tick()
// before any V2 job runs") -- confirmed via direct code read and real
// KV evidence (v2:jobs:newsAgent:{date} is null for the last 5 days).
// Nobody noticed for over a month because nothing was watching for
// "component whose own code makes it structurally unreachable in the
// current configuration," as opposed to "component that threw an
// error" (which this project already has other monitoring for). This
// is exactly the class of failure the CAPABILITY REGISTRY +
// MODE-REACHABILITY check below exists to catch systematically, not
// just for this one already-found case.
//
// FIVE STATES (per spec -- UNKNOWN and missing evidence NEVER render
// green):
//   HEALTHY             -- reachable, evidence found within tolerance.
//   DEGRADED            -- reachable, evidence found but stale (1x-2x
//                          the tolerance window).
//   CRITICAL            -- either (a) required-in-production but its
//                          own code is unreachable under the current
//                          FLEXAI_MODE ("CONFIGURED UNREACHABLE" --
//                          the News Agent class), or (b) reachable but
//                          evidence is missing/more than 2x stale.
//   EXPECTEDLY_INACTIVE -- a declared, deliberate pause/retirement, or
//                          a non-trading day for a weekday-only
//                          component. Never used as a silent fallback
//                          for "not found" -- only for an EXPLICIT,
//                          disclosed reason.
//   UNKNOWN             -- evidence could not be determined at all
//                          (a KV read itself failed) OR a non-required
//                          component has no evidence -- genuinely
//                          "don't know," never treated as healthy.
// ============================================================

// ---- CAPABILITY REGISTRY ----
//
// Each entry's `expectedModes` is a STRUCTURAL fact about the code --
// which FLEXAI_MODE values this component's call site actually
// executes under today, confirmed by direct code read (tick()'s own
// control flow), NOT a normative wish. `requiredInProduction` is the
// NORMATIVE fact -- should this always produce real output regardless
// of mode. The News-Agent-class bug is exactly the mismatch between
// these two: expectedModes=["legacy"] (a structural fact, confirmed by
// tick()'s early-return) while requiredInProduction=true (Bill's
// stated expectation, this same conversation) -- current FLEXAI_MODE
// not being in expectedModes, combined with requiredInProduction=true,
// is what renders CRITICAL: CONFIGURED_UNREACHABLE below.
//
// evidenceCheck is an async fn(lookbackDays) => { found, dateChecked,
// daysAgo, error } -- every implementation below reads durable KV
// records directly by known date-derived keys (job manifests, or each
// engine's own daily/per-symbol output records) -- NEVER kv.keys()/
// SCAN, so this can never hit the same wall that broke /track-record.
//
// SCOPE DECISION (disclosed, not silent): the ~15 other legacy V2 jobs
// gated by the exact same tick() early-return as News Agent
// (trendRegime, moversAgent, preMarketMetrics, orbPlanner,
// trendRegimeTargeted, alpacaReadinessCheck, trendIntraday, the 4
// qualityX jobs, newsWatcher, masterAgent) are NOT individually
// registered here. Unlike News Agent, each of those has a direct v3
// functional successor already in this registry (dataAgent/
// channelScanner/masterSwingAgent/qualityAgent/swingLabReport/
// dailyTransparencyReport cover the same watchlist-build/scan/quality-
// grade/EOD-report functions) -- their V2 originals being unreachable
// is the INTENDED result of the migration, not a gap. News Agent is
// the one exception because nothing in the v3 pipeline provides real
// news-driven alerts (finnhubCert's news module is feed-certification
// plumbing only, not a decision signal -- see its own header). If any
// of those 15 turn out to lack a true v3 successor after all, they
// should be added individually in a follow-up pass -- flagging this
// scope boundary explicitly rather than silently deciding it.
const V3_AUDIT_MODES_ALL_V3 = ["swing_transition", "swing_lab", "swing_live_admin"];

async function v3AuditCheckManifestEvidence(manifestKeyPrefix, lookbackDays, opts = {}) {
  const { legacy = false } = opts; // legacy=true reads v2's {executionStatus} shape instead of v3's {didWork}
  for (let i = 0; i < lookbackDays; i++) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toLocaleDateString("en-CA", { timeZone: "America/New_York" });
    const result = await kvGet(`${manifestKeyPrefix}:${dateStr}`);
    if (!result.ok) return { found: false, dateChecked: null, daysAgo: null, error: result.error };
    const v = result.value;
    const success = legacy ? v?.executionStatus === "completed" : v?.didWork === true;
    if (v && success) return { found: true, dateChecked: dateStr, daysAgo: i, error: null };
  }
  return { found: false, dateChecked: null, daysAgo: null, error: null };
}

// Generic any-of-these-keys-exists check, for engines whose real daily
// output isn't a v3RunJobWithManifest manifest (they manage their own
// internal short-TTL claim key instead, which is a poor durability
// signal -- see each entry's own note for why its specific durable key
// was chosen over the transient claim).
async function v3AuditCheckKeysExistEvidence(keyFnList, lookbackDays) {
  for (let i = 0; i < lookbackDays; i++) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const dateStr = d.toLocaleDateString("en-CA", { timeZone: "America/New_York" });
    for (const keyFn of keyFnList) {
      const result = await kvGet(keyFn(dateStr));
      if (!result.ok) return { found: false, dateChecked: null, daysAgo: null, error: result.error };
      if (result.value != null) return { found: true, dateChecked: dateStr, daysAgo: i, error: null };
    }
  }
  return { found: false, dateChecked: null, daysAgo: null, error: null };
}

// Cross-repo evidence -- flexai-saas's REAL subscriber-facing alert
// system shares this SAME Upstash instance (confirmed live earlier
// this session: identical KV_REST_API_URL/TOKEN in both repos' env).
// alerts:recent is a 50-entry rolling log, NOT authoritative for every
// send site (per CLAUDE.md, only 6 call sites write to it) -- disclosed
// explicitly in this entry's note, not silently treated as complete.
async function v3AuditCheckAlertsRecentEvidence(lookbackDays) {
  const result = await kvGet("alerts:recent");
  if (!result.ok) return { found: false, dateChecked: null, daysAgo: null, error: result.error };
  const entries = Array.isArray(result.value) ? result.value : [];
  if (entries.length === 0) return { found: false, dateChecked: null, daysAgo: null, error: null };
  const timestamps = entries.map((e) => new Date(e.timestamp ?? e.sentAt ?? e.at ?? 0).getTime()).filter((t) => t > 0);
  if (timestamps.length === 0) return { found: false, dateChecked: null, daysAgo: null, error: null };
  const mostRecentMs = Math.max(...timestamps);
  const daysAgo = Math.floor((Date.now() - mostRecentMs) / (24 * 60 * 60 * 1000));
  return { found: true, dateChecked: new Date(mostRecentMs).toISOString(), daysAgo, error: null };
}

